insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-age:27-4a70b97176','aux-age',27,'Al pulsar Adjuntar archivo en un mensaje nuevo de Outlook:','["Aparece una lista de archivos recientes y la opción de buscar en el equipo", "Se abre el navegador", "Se ejecuta el antivirus", "Se adjunta automáticamente el último archivo abierto en el equipo"]'::jsonb,0,'Outlook · Correo','También se pueden adjuntar archivos de OneDrive como vínculo.',null),
('aux-age:24-cadc1fb8a4','aux-age',24,'Si creas un documento nuevo en Word, nunca lo guardas y se cierra, puedes intentar recuperarlo con:','["Archivo > Información > Administrar documento > Recuperar documentos no guardados", "Archivo > Abrir > Examinar > Abrir y reparar, eligiendo el archivo temporal", "Revisar > Comparar", "Vista > Mostrar"]'::jsonb,0,'Word · Recuperación','Depende de que Autorrecuperación esté activada.',null),
('aux-age:23-3f41f55dcc','aux-age',23,'Para ver el espacio libre de una unidad de disco, lo más directo es:','["Abrir las propiedades de la unidad desde «Este equipo»", "No es posible ver el espacio por unidad", "Abrir las propiedades de un archivo de la unidad", "Mirar el panel de vista previa"]'::jsonb,0,'Explorador · Unidades','También se ve con la barra de capacidad en «Este equipo».',null),
('aux-age:23-986b0b409a','aux-age',23,'Se recomienda usar «Expulsar» antes de retirar una memoria USB para:','["Liberar memoria RAM", "Evitar que se sobrecaliente o que se dañe físicamente el conector", "Evitar la pérdida o corrupción de datos que aún se estén escribiendo", "No olvidarla conectada"]'::jsonb,2,'Windows · Dispositivos','Windows termina las escrituras pendientes antes de avisar de que es seguro quitarla.',null),
('aux-age:27-92a7d94a46','aux-age',27,'Las marcas de seguimiento de Outlook pueden aplicarse a:','["Solo mensajes recibidos en copia", "Mensajes enviados y recibidos", "Solo mensajes enviados", "Solo mensajes recibidos"]'::jsonb,1,'Outlook · Organizar','Al enviar se puede añadir además un aviso para el destinatario.',null),
('aux-age:27-f88df37ff7','aux-age',27,'¿Cuál de estas acciones NO se realiza desde el Calendario de Outlook?','["Eliminar citas", "Crear citas y reuniones", "Enviar invitaciones y gestionar respuestas", "Gestionar contactos y listas de distribución"]'::jsonb,3,'Outlook · Calendario','Los contactos se gestionan en Personas (Contactos).',null),
('aux-age:25-6febc935ee','aux-age',25,'En Excel, el contenido real de la celda activa (por ejemplo, la fórmula y no su resultado) se ve en:','["La barra de fórmulas", "La cinta de opciones", "El cuadro de nombres", "La barra de estado"]'::jsonb,0,'Excel · Interfaz','El cuadro de nombres muestra la dirección de la celda activa.',null),
('aux-age:25-8c1ec3be31','aux-age',25,'¿Cuántas hojas puede tener como máximo un libro de Excel?','["255 hojas por libro", "No hay un número fijo; depende de la memoria disponible", "16", "1"]'::jsonb,1,'Excel · Especificaciones','Un libro nuevo se crea con una hoja, pero se pueden añadir muchas más.',null),
('aux-age:23-d394517e5f','aux-age',23,'Compartir una carpeta en red significa:','["Reducir su tamaño", "Convertirla en solo lectura para todos los usuarios del equipo, sin acceso desde la red", "Ocultarla", "Hacer que su contenido sea accesible para otros usuarios de la red, con los permisos que se indiquen"]'::jsonb,3,'Windows · Red','Se configura en las propiedades de la carpeta.',null),
('aux-age:24-d0f86ef509','aux-age',24,'En la búsqueda avanzada de Word con caracteres comodín, ¿qué símbolo excluye los caracteres indicados entre corchetes, como en [!a-c]?','["*", "!", "-", "?"]'::jsonb,1,'Word · Buscar','? sustituye a un carácter y * a cualquier cadena.',null),
('aux-age:24-940323f342','aux-age',24,'Si vinculas una lista multinivel a los estilos Título 1, 2 y 3, la tabla de contenido generada:','["Duplica la numeración", "Muestra solo el texto de los títulos sin números", "Incluye los números de la lista junto al texto de cada título", "No muestra los títulos"]'::jsonb,2,'Word · Referencias','La tabla de contenido toma el texto y la numeración de los títulos.',null),
('aux-age:24-1cbc5b1c8d','aux-age',24,'La barra de herramientas de acceso rápido de Word se puede colocar debajo de la cinta mediante la opción:','["Anclar barra de herramientas a la cinta", "Restablecer el diseño predeterminado de la cinta", "Mostrar debajo de la cinta de opciones", "Cambiar posición de paneles"]'::jsonb,2,'Word · Interfaz','Se elige desde el menú de personalización de la propia barra.',null),
('aux-age:27-ac5b054df9','aux-age',27,'La diferencia principal entre IMAP y POP3 es que:','["IMAP sincroniza mensajes y carpetas con el servidor; POP3 descarga los mensajes sin sincronizar", "Son iguales", "POP3 sincroniza mensajes y carpetas con el servidor; IMAP descarga los mensajes y los borra del servidor", "IMAP solo sirve para enviar"]'::jsonb,0,'Outlook · Cuentas','Con IMAP se ve lo mismo desde varios dispositivos.',null),
('aux-age:24-63381da673','aux-age',24,'El panel Editor de Word sirve para:','["Registrar los cambios de cada revisor para aceptarlos o rechazarlos uno a uno", "Editar el documento a la vez con otras personas", "Revisar ortografía y gramática y ofrecer sugerencias de claridad, concisión y estilo", "Convertir el documento a PDF"]'::jsonb,2,'Word · Revisar','Se abre con F7 o desde Inicio > Editor.',null),
('aux-age:24-db17f86530','aux-age',24,'Para insertar el contenido de otro documento de Word dentro del documento actual se usa:','["Insertar > Objeto > Texto de archivo", "No es posible", "Referencias > Referencia cruzada", "Insertar > Cuadro de texto"]'::jsonb,0,'Word · Insertar','Inserta el texto del otro archivo en la posición del cursor.',null),
('aux-age:24-0c556a6184','aux-age',24,'Para que varias personas editen un documento de Word a la vez (coautoría), el documento debe:','["Enviarse como adjunto por correo a todos los coautores con permiso de edición", "Estar guardado en OneDrive o SharePoint y compartido con permiso de edición", "Estar en el escritorio de cada usuario", "Ser de la misma organización obligatoriamente"]'::jsonb,1,'Word · Coautoría','Se ven en tiempo real los cambios de los demás.',null),
('aux-age:25-7da32a0401','aux-age',25,'En Excel, una celda es:','["Un archivo", "Una hoja", "Un formato aplicado a un rango", "La intersección de una fila y una columna"]'::jsonb,3,'Excel · Conceptos','Se identifica por la letra de columna y el número de fila, como B3.',null),
('aux-age:25-63e619c47c','aux-age',25,'En Excel en español, ¿cuál es la sintaxis correcta de la función que devuelve caracteres desde el final de un texto?','["FIN(texto;núm)", "STRR(texto;[núm])", "DERECHA(núm_de_caracteres;texto)", "DERECHA(texto;[núm_de_caracteres])"]'::jsonb,3,'Excel · Funciones de texto','IZQUIERDA devuelve caracteres desde el principio y EXTRAE desde una posición intermedia.',null),
('aux-age:23-1466ed73f1','aux-age',23,'La herramienta Mapa de caracteres de Windows sirve para:','["Ver la distribución del teclado en pantalla", "Buscar e insertar símbolos y caracteres especiales", "Localizar equipos en la red", "Asignar accesos directos"]'::jsonb,1,'Windows · Accesorios','Permite copiar el carácter para pegarlo en cualquier aplicación.',null),
('aux-age:23-f8f90031ba','aux-age',23,'Al agrupar archivos por tipo en el Explorador, el número que aparece entre paréntesis junto a cada grupo indica:','["Cuántos archivos hay en ese grupo", "Cuántas aplicaciones pueden abrirlos", "El orden del grupo", "Cuántos archivos están duplicados"]'::jsonb,0,'Explorador · Vistas','Por ejemplo, «Documento de Microsoft Word (12)».',null),
('aux-age:23-cca99469a4','aux-age',23,'En el Explorador de archivos, la ruta completa de la carpeta en la que estás se ve en:','["El panel de vista previa", "La barra de estado", "La barra de direcciones", "La cinta de opciones"]'::jsonb,2,'Explorador · Navegación','Al hacer clic en ella se muestra la ruta como texto.',null),
('aux-age:24-ee46cd3ae7','aux-age',24,'El botón Dictar de Word se encuentra en:','["La pestaña Insertar, e inserta un archivo de audio", "La pestaña Revisar, y lee el documento en voz alta con la voz predeterminada", "La pestaña Vista, y activa el lector de pantalla", "La pestaña Inicio, y convierte en texto lo que dices por el micrófono"]'::jsonb,3,'Word · Inicio','Leer en voz alta está en la pestaña Revisar.',null),
('aux-age:27-a5bb923f67','aux-age',27,'La lista de Autocompletar de Outlook, que sugiere direcciones al escribir, se basa principalmente en:','["La libreta de direcciones global de la organización, ordenada por departamentos y cargos", "Las direcciones a las que has enviado correo desde esa cuenta, aunque no estén en Contactos", "El orden alfabético de la organización", "Solo los contactos guardados"]'::jsonb,1,'Outlook · Correo','Se pueden quitar entradas concretas de la lista.',null),
('aux-age:26-797ce4161b','aux-age',26,'En Access, un campo es:','["Una información concreta de cada registro, como el nombre o el correo", "Una fila completa de la tabla con todos los datos de un mismo elemento", "Una consulta guardada", "Un formulario con los datos de un registro concreto de la tabla abierta"]'::jsonb,0,'Access · Tablas','Cada columna de la tabla es un campo.',null),
('aux-age:23-adb803dc96','aux-age',23,'La extensión de un archivo es:','["El nombre del usuario que lo creó", "El grupo de caracteres tras el último punto del nombre que indica su tipo y la aplicación asociada", "El grupo de caracteres tras el primer punto del nombre, que indica la carpeta en la que se guardó el archivo y su propietario", "El tamaño del archivo"]'::jsonb,1,'Windows · Archivos','Por ejemplo .docx, .xlsx o .pdf.',null),
('aux-age:2-76b93deb50','aux-age',2,'Según el art. 56.1 CE, el Rey asume la más alta representación del Estado español:','["En las relaciones internacionales, especialmente con las naciones de su comunidad histórica", "En las relaciones internacionales, salvo en las que se reservan al Ministerio de Asuntos Exteriores", "En las relaciones internacionales, especialmente con los Estados miembros de la Unión Europea", "En las relaciones con las Comunidades Autónomas, especialmente con las de régimen foral"]'::jsonb,0,'Art. 56.1 CE','El Rey es el Jefe del Estado, símbolo de su unidad y permanencia, arbitra y modera el funcionamiento regular de las instituciones y asume la más alta representación en las relaciones internacionales, especialmente con las naciones de su comunidad histórica.',null),
('aux-age:2-b16fdf6735','aux-age',2,'La persona del Rey, según el art. 56.3 CE:','["Es inviolable durante su reinado y responde de sus actos tras la abdicación", "Es inviolable, pero responde civilmente de sus actos privados ante el Tribunal Supremo", "No está sujeta a responsabilidad, salvo por los actos que realice sin refrendo", "Es inviolable y no está sujeta a responsabilidad"]'::jsonb,3,'Art. 56.3 CE','Sus actos estarán siempre refrendados en la forma del art. 64 y carecen de validez sin ese refrendo, salvo lo dispuesto en el art. 65.2.',null),
('aux-age:2-894e56b051','aux-age',2,'¿Qué dignidad corresponde al heredero de la Corona, según el art. 57.2 CE?','["Príncipe de Viana", "Príncipe de Asturias", "Infante de España", "Príncipe de Gerona"]'::jsonb,1,'Art. 57.2 CE','El Príncipe heredero, desde su nacimiento o desde que se produzca el hecho que origine el llamamiento, tendrá la dignidad de Príncipe de Asturias y los demás títulos vinculados tradicionalmente al sucesor de la Corona.',null),
('aux-age:2-b1a8f40ae8','aux-age',2,'Extinguidas todas las líneas llamadas en Derecho a la sucesión de la Corona, ¿quién provee a la sucesión?','["El pueblo español, mediante referéndum consultivo convocado por el Presidente del Gobierno", "Las Cortes Generales, en la forma que más convenga a los intereses de España", "El Congreso de los Diputados, por mayoría absoluta y en votación única", "El Gobierno, mediante real decreto acordado en Consejo de Ministros"]'::jsonb,1,'Art. 57.3 CE','Así lo dispone el art. 57.3 CE.',null),
('aux-age:2-195428a485','aux-age',2,'Las abdicaciones y renuncias y cualquier duda de hecho o de derecho en el orden de sucesión a la Corona se resolverán:','["Por una ley orgánica", "Por acuerdo del Consejo de Estado", "Por una ley ordinaria de las Cortes", "Por un real decreto del Gobierno"]'::jsonb,0,'Art. 57.5 CE','El art. 57.5 CE exige ley orgánica. Así se hizo con la abdicación de Juan Carlos I (LO 3/2014).',null),
('aux-age:2-43295713a7','aux-age',2,'Las personas con derecho a la sucesión que contrajeran matrimonio contra la expresa prohibición del Rey y de las Cortes Generales:','["Perderán solo la dignidad de Príncipe o Princesa de Asturias, pero no el derecho a suceder", "Quedarán excluidas de la sucesión por sí y sus descendientes", "Podrán ser rehabilitadas por las Cortes por mayoría absoluta", "Quedarán excluidas de la sucesión, pero no sus descendientes"]'::jsonb,1,'Art. 57.4 CE','La exclusión alcanza a la persona y a sus descendientes.',null),
('aux-age:2-906b13832a','aux-age',2,'La Reina consorte o el consorte de la Reina, según el art. 58 CE:','["Pueden asumir funciones constitucionales por delegación expresa del Rey, refrendada por el Presidente", "No pueden asumir funciones constitucionales, salvo lo dispuesto para la Regencia", "No pueden asumir funciones constitucionales en ningún caso, ni siquiera la Regencia", "Asumen las funciones del Rey durante sus ausencias del territorio nacional"]'::jsonb,1,'Art. 58 CE','La única excepción es la Regencia.',null),
('aux-age:2-960fdc2e2b','aux-age',2,'Cuando el Rey fuere menor de edad, ¿quién ejerce inmediatamente la Regencia?','["Una Regencia de una, tres o cinco personas nombrada por las Cortes Generales", "El pariente mayor de edad más próximo a suceder en la Corona y, en su defecto, el padre o la madre del Rey", "El Presidente del Gobierno, hasta que las Cortes nombren una Regencia de tres personas", "El padre o la madre del Rey y, en su defecto, el pariente mayor de edad más próximo a suceder en la Corona"]'::jsonb,3,'Art. 59.1 CE','Ejercerá la Regencia durante el tiempo de la minoría de edad del Rey, según el orden establecido en la Constitución.',null),
('aux-age:2-1fab92d816','aux-age',2,'Si no hubiere ninguna persona a quien corresponda la Regencia, ¿cómo la nombran las Cortes Generales?','["Se compondrá de una o dos personas", "Se compondrá siempre de una sola persona, elegida por las Cortes", "Se compondrá de tres o cinco personas", "Se compondrá de una, tres o cinco personas"]'::jsonb,3,'Art. 59.3 CE','Las Cortes Generales nombran la Regencia, que se compondrá de una, tres o cinco personas.',null),
('aux-age:2-4e94106cec','aux-age',2,'Para ejercer la Regencia, según el art. 59.4 CE, es preciso:','["Ser español y mayor de edad", "Ser español de origen y mayor de 30 años", "Ser miembro de la Familia Real y mayor de edad", "Ser español y haber jurado la Constitución ante el Congreso"]'::jsonb,0,'Art. 59.4 CE','La Regencia se ejerce por mandato constitucional y siempre en nombre del Rey.',null),
('aux-age:2-6778d6d44f','aux-age',2,'La inhabilitación del Rey para el ejercicio de su autoridad debe ser reconocida por:','["El Tribunal Constitucional", "El Consejo de Ministros", "El Tribunal Supremo", "Las Cortes Generales"]'::jsonb,3,'Art. 59.2 CE','Si el Rey se inhabilitare y la imposibilidad fuere reconocida por las Cortes Generales, entrará a ejercer inmediatamente la Regencia el Príncipe heredero, si fuere mayor de edad.',null),
('aux-age:2-d3fe036507','aux-age',2,'¿Quién es tutor del Rey menor, según el art. 60.1 CE, en primer lugar?','["El Presidente del Gobierno, mientras las Cortes no designen otra persona mediante una ley orgánica", "La persona que en su testamento hubiese nombrado el Rey difunto, si es mayor de edad y español de nacimiento", "La persona que designen las Cortes Generales por mayoría de tres quintos", "El padre o la madre del Rey, aunque hayan contraído nuevo matrimonio, y en su defecto quien designen las Cortes"]'::jsonb,1,'Art. 60.1 CE','Si no lo hubiese nombrado, será tutor el padre o la madre mientras permanezcan viudos; en su defecto, lo nombrarán las Cortes Generales.',null),
('aux-age:2-a6e11edbb1','aux-age',2,'El Rey, al ser proclamado ante las Cortes Generales:','["No presta juramento, porque su legitimidad deriva directamente de la Constitución", "Prestará juramento de desempeñar fielmente sus funciones, guardar y hacer guardar la Constitución y las leyes y respetar los derechos de los ciudadanos y de las CCAA", "Prometerá ante el Presidente del Tribunal Constitucional cumplir y hacer cumplir la Constitución y las leyes, y respetar los derechos de los ciudadanos y de las Comunidades Autónomas", "Prestará juramento ante el Consejo de Ministros, que levantará acta de la proclamación"]'::jsonb,1,'Art. 61.1 CE','El Príncipe heredero, al alcanzar la mayoría de edad, y el Regente o Regentes, al asumir sus funciones, prestan el mismo juramento y el de fidelidad al Rey (art. 61.2).',null),
('aux-age:2-b4df81d275','aux-age',2,'¿Cuál de estas funciones corresponde al Rey según el art. 62 CE?','["Ejercer el derecho de gracia con arreglo a la ley, que no podrá autorizar indultos generales", "Ejercer el derecho de gracia con arreglo a la ley, incluidos los indultos generales cuando lo acuerde el Consejo de Ministros", "Dirigir la política exterior del Estado y la Administración militar", "Nombrar a los magistrados del Tribunal Supremo a propuesta del Gobierno, previo informe del Consejo General del Poder Judicial"]'::jsonb,0,'Art. 62 i) CE','La dirección de la política interior y exterior corresponde al Gobierno (art. 97 CE).',null),
('aux-age:2-b99e4f65df','aux-age',2,'Según el art. 62 CE, el Rey preside las sesiones del Consejo de Ministros:','["Cuando lo estime oportuno, a petición del Presidente del Gobierno", "Una vez al trimestre, de forma obligatoria", "Siempre que se deliberen asuntos de Estado o de política exterior", "Nunca, porque es un órgano del Gobierno"]'::jsonb,0,'Art. 62 g) CE','Al Rey le corresponde ser informado de los asuntos de Estado y presidir el Consejo de Ministros cuando lo estime oportuno, a petición del Presidente del Gobierno.',null),
('aux-age:2-fbb8a7ba87','aux-age',2,'¿A quién corresponde, según el art. 63.3 CE, declarar la guerra y hacer la paz?','["Al Rey, previa deliberación del Consejo de Ministros", "Al Rey, previa autorización de las Cortes Generales", "Al Gobierno, previa autorización del Congreso de los Diputados", "A las Cortes Generales, a propuesta del Rey"]'::jsonb,1,'Art. 63.3 CE','Corresponde al Rey, previa autorización de las Cortes Generales.',null),
('aux-age:2-6e80012169','aux-age',2,'¿Quién refrenda la propuesta y el nombramiento del Presidente del Gobierno y la disolución prevista en el art. 99 CE?','["El Presidente del Senado, como presidente de las Cortes", "El Presidente del Congreso", "El Ministro de Justicia", "El Presidente del Gobierno en funciones"]'::jsonb,1,'Art. 64.1 CE','El resto de actos del Rey los refrendan el Presidente del Gobierno y, en su caso, los ministros competentes.',null),
('aux-age:2-a9ad92886e','aux-age',2,'De los actos del Rey serán responsables:','["Las personas que los refrenden", "El Gobierno de forma solidaria en todo caso", "El Consejo de Estado, que los informa previamente", "El propio Rey, ante las Cortes Generales"]'::jsonb,0,'Art. 64.2 CE','El refrendo traslada la responsabilidad a quien refrenda.',null),
('aux-age:2-4527d16755','aux-age',2,'Según el art. 65 CE, el Rey recibe de los Presupuestos del Estado una cantidad global para el sostenimiento de su Familia y Casa y:','["La distribuye libremente", "La distribuye según el plan que aprueben las Cortes", "La distribuye con autorización del Ministerio de Hacienda", "Debe justificarla anualmente ante el Tribunal de Cuentas"]'::jsonb,0,'Art. 65.1 CE','Además, nombra y releva libremente a los miembros civiles y militares de su Casa (art. 65.2), actos que no necesitan refrendo.',null),
('aux-age:2-171da54943','aux-age',2,'¿Cuántos miembros tiene el Tribunal Constitucional?','["15", "9", "10", "12"]'::jsonb,3,'Art. 159.1 CE','Los nombra el Rey: 4 a propuesta del Congreso, 4 del Senado, 2 del Gobierno y 2 del Consejo General del Poder Judicial.',null),
('aux-age:2-af209a5dd4','aux-age',2,'¿Cuántos magistrados del Tribunal Constitucional se nombran a propuesta del Gobierno?','["2", "4", "1", "3"]'::jsonb,0,'Art. 159.1 CE','Congreso y Senado proponen 4 cada uno, por mayoría de tres quintos; el Gobierno, 2; y el CGPJ, 2.',null),
('aux-age:2-5730fa3615','aux-age',2,'Los magistrados propuestos por el Congreso y el Senado para el Tribunal Constitucional requieren:','["Mayoría de tres quintos de sus miembros", "Mayoría absoluta de sus miembros, en primera votación", "Mayoría de dos tercios de sus miembros, en votación única", "Mayoría simple de los presentes"]'::jsonb,0,'Art. 159.1 CE','Cuatro a propuesta de cada Cámara, por mayoría de tres quintos de sus miembros.',null),
('aux-age:2-553386b89f','aux-age',2,'Los miembros del Tribunal Constitucional deben ser juristas de reconocida competencia con más de:','["20 años de ejercicio profesional", "10 años de ejercicio profesional", "12 años de ejercicio profesional", "15 años de ejercicio profesional"]'::jsonb,3,'Art. 159.2 CE','Se nombran entre magistrados y fiscales, profesores de universidad, funcionarios públicos y abogados.',null),
('aux-age:2-421024e877','aux-age',2,'¿Por cuánto tiempo son designados los miembros del Tribunal Constitucional y cómo se renueva?','["Por 9 años, renovándose por terceras partes cada 3 años", "Por 6 años, renovándose por mitades cada 3 años", "Por 12 años, renovándose por terceras partes cada 4 años", "Por 9 años, renovándose por mitades cada 4 años y medio"]'::jsonb,0,'Art. 159.3 CE','Así lo dispone el art. 159.3 CE.',null),
('aux-age:2-b01be15f15','aux-age',2,'El Presidente del Tribunal Constitucional es nombrado por el Rey:','["Entre sus miembros, a propuesta del mismo Tribunal en pleno y por un período de tres años", "Entre juristas de reconocida competencia con más de quince años de ejercicio, a propuesta del Congreso, por tres años", "Entre sus miembros, a propuesta del Gobierno, oído el Pleno, y por un período de nueve años", "Entre sus miembros, a propuesta del CGPJ y por un período de cuatro años"]'::jsonb,0,'Art. 160 CE','El Pleno propone y el Rey nombra, por tres años.',null),
('aux-age:2-285fc7f24b','aux-age',2,'¿Quiénes están legitimados para interponer el recurso de inconstitucionalidad?','["El Presidente del Gobierno, el Ministerio Fiscal, 50 Diputados, 50 Senadores y los Presidentes y Asambleas de las Comunidades Autónomas", "Cualquier persona natural o jurídica que invoque un interés legítimo, además del Defensor del Pueblo", "El Presidente del Gobierno, el Defensor del Pueblo, 30 Diputados, 30 Senadores y las Asambleas de las CCAA", "El Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores y los órganos colegiados ejecutivos y Asambleas de las CCAA"]'::jsonb,3,'Art. 162.1 a) CE','El Ministerio Fiscal no está legitimado para el recurso de inconstitucionalidad, sí para el de amparo.',null),
('aux-age:2-75af08ce11','aux-age',2,'¿Quiénes están legitimados para interponer el recurso de amparo?','["Toda persona natural o jurídica que invoque un interés legítimo, el Defensor del Pueblo y el Ministerio Fiscal", "El Defensor del Pueblo y el Ministerio Fiscal, a instancia de la persona afectada, que no puede recurrir por sí misma", "Solo la persona directamente afectada por la vulneración del derecho fundamental, asistida de abogado y representada por procurador", "Toda persona natural o jurídica que invoque un interés legítimo, el Defensor del Pueblo y 50 Diputados"]'::jsonb,0,'Art. 162.1 b) CE','Así lo dispone el art. 162.1 b) CE.',null),
('aux-age:2-d1497e37d8','aux-age',2,'Cuando el Gobierno impugna ante el Tribunal Constitucional disposiciones y resoluciones de las CCAA, la impugnación produce la suspensión, que el Tribunal debe ratificar o levantar en un plazo no superior a:','["3 meses", "5 meses", "2 meses", "6 meses"]'::jsonb,1,'Art. 161.2 CE','La suspensión es automática y el Tribunal la ratifica o levanta en un plazo no superior a cinco meses.',null),
('aux-age:2-a068593c80','aux-age',2,'La cuestión de inconstitucionalidad la plantea:','["El Ministerio Fiscal en cualquier proceso, antes de que se dicte sentencia firme por el órgano judicial", "Un órgano judicial que considere que una norma con rango de ley aplicable al caso pueda ser contraria a la Constitución", "El Defensor del Pueblo cuando una ley vulnere derechos fundamentales, en el plazo de tres meses", "Cualquier ciudadano afectado por una norma con rango de ley que considere inconstitucional, en el plazo de tres meses desde su publicación"]'::jsonb,1,'Art. 163 CE','En ningún caso tiene efectos suspensivos.',null),
('aux-age:2-9998c2b16a','aux-age',2,'Las sentencias del Tribunal Constitucional tienen el valor de cosa juzgada:','["A partir del día siguiente de su publicación, y no cabe recurso alguno contra ellas", "A partir de su notificación a las partes, y contra ellas cabe recurso de súplica ante el Pleno", "A partir de su publicación en el BOE con los votos particulares, pero cabe recurso ante el Tribunal Supremo", "A partir de los veinte días de su publicación, y no cabe recurso contra ellas"]'::jsonb,0,'Art. 164.1 CE','Se publican en el BOE con los votos particulares, si los hubiere.',null),
('aux-age:2-14a34d2823','aux-age',2,'¿Qué órgano NO puede proponer magistrados del Tribunal Constitucional?','["El Gobierno", "El Senado", "El Consejo General del Poder Judicial", "El Tribunal Supremo"]'::jsonb,3,'Art. 159.1 CE','Proponen el Congreso, el Senado, el Gobierno y el CGPJ.',null),
('aux-age:2-f6474ad040','aux-age',2,'¿Quiénes pueden ejercer la iniciativa de reforma constitucional?','["Gobierno, Congreso, Senado, Asambleas de las CCAA y la iniciativa popular con 500.000 firmas", "Gobierno y Congreso, y el Senado solo a propuesta de las Asambleas de las CCAA", "Gobierno, Congreso y Senado, y también la iniciativa popular respaldada por un millón de firmas", "Gobierno, Congreso, Senado y Asambleas de las CCAA, pero no la iniciativa popular"]'::jsonb,3,'Art. 166 CE','La iniciativa se ejerce según los apartados 1 y 2 del art. 87, que no incluyen la iniciativa popular del art. 87.3.',null),
('aux-age:2-fbac05071c','aux-age',2,'Por el procedimiento ordinario del art. 167 CE, los proyectos de reforma constitucional deben aprobarse por:','["Mayoría absoluta de cada una de las Cámaras", "Mayoría de tres quintos de cada una de las Cámaras", "Mayoría de dos tercios de cada una de las Cámaras", "Mayoría de tres quintos del Congreso y absoluta del Senado"]'::jsonb,1,'Art. 167.1 CE','Si no hay acuerdo entre las Cámaras, se intenta obtenerlo mediante una comisión de composición paritaria de Diputados y Senadores.',null),
('aux-age:2-3893bc6677','aux-age',2,'Si no se logra la aprobación de una reforma por el procedimiento del art. 167.1 CE, el Congreso podrá aprobarla:','["Por mayoría absoluta, siempre que el texto hubiera obtenido la mayoría de tres quintos del Senado", "Por mayoría de dos tercios, siempre que el texto hubiera obtenido la mayoría absoluta del Senado", "Por mayoría de dos tercios, aunque el Senado haya rechazado el texto por mayoría absoluta", "Por mayoría de tres quintos, siempre que el texto se someta después a referéndum obligatorio de todos los españoles"]'::jsonb,1,'Art. 167.2 CE','Así lo prevé el art. 167.2 CE.',null),
('aux-age:2-2513da5e09','aux-age',2,'En la reforma por el procedimiento del art. 167 CE, el referéndum es:','["Facultativo: se celebra si lo solicita, en los 15 días siguientes a la aprobación, una décima parte de los miembros de cualquiera de las Cámaras", "Facultativo: se celebra si lo solicita, en los 15 días siguientes, la mayoría absoluta del Congreso", "Obligatorio en todo caso, y se celebra en los 15 días siguientes a la aprobación del texto por las Cortes Generales, con independencia de lo que soliciten las Cámaras", "Facultativo: se celebra si lo solicitan, en los 30 días siguientes, 50 Diputados o 50 Senadores"]'::jsonb,0,'Art. 167.3 CE','En el procedimiento agravado del art. 168, en cambio, el referéndum es obligatorio.',null),
('aux-age:2-bc71718274','aux-age',2,'La revisión total de la Constitución o una parcial que afecte al Título preliminar, a la Sección 1.ª del Capítulo II del Título I o al Título II exige:','["Aprobación por tres quintos de cada Cámara, disolución inmediata de las Cortes y referéndum facultativo", "Aprobación por mayoría absoluta de cada Cámara, disolución inmediata de las Cortes y referéndum obligatorio", "Aprobación por dos tercios de cada Cámara, disolución inmediata de las Cortes, ratificación por las nuevas Cámaras y referéndum", "Aprobación por dos tercios del Congreso y mayoría absoluta del Senado, y después referéndum obligatorio"]'::jsonb,2,'Art. 168 CE','Las nuevas Cámaras deben ratificar la decisión, estudiar el nuevo texto y aprobarlo por mayoría de dos tercios de ambas.',null),
('aux-age:2-d7191d2239','aux-age',2,'¿Cuándo no podrá iniciarse la reforma constitucional?','["Durante la regencia o la minoría de edad del Rey", "Durante el último año de la legislatura o mientras haya un proceso electoral convocado", "En tiempo de guerra o de vigencia de alguno de los estados del art. 116", "Mientras esté pendiente de resolver un recurso de inconstitucionalidad contra una ley orgánica"]'::jsonb,2,'Art. 169 CE','Los estados del art. 116 son los de alarma, excepción y sitio.',null),
('aux-age:3-63568bef2c','aux-age',3,'Según el art. 66.2 CE, las Cortes Generales:','["Ejercen la potestad legislativa, elaboran los Presupuestos y dirigen la política exterior", "Ejercen la potestad legislativa del Estado, aprueban sus Presupuestos, controlan la acción del Gobierno y tienen las demás competencias que les atribuya la Constitución", "Aprueban los Presupuestos y controlan al Gobierno, pero la potestad legislativa es del Congreso", "Ejercen la potestad legislativa y reglamentaria del Estado y dirigen la Administración General del Estado"]'::jsonb,1,'Art. 66.2 CE','Las Cortes representan al pueblo español y están formadas por el Congreso de los Diputados y el Senado (art. 66.1).',null),
('aux-age:3-2dba8dc959','aux-age',3,'Según el art. 67 CE, los miembros de las Cortes Generales:','["Están ligados por el mandato del partido con el que concurrieron a las elecciones, salvo en votaciones secretas", "No están ligados por mandato imperativo", "Pueden ser a la vez Diputados y Senadores si lo autoriza la Mesa", "Pueden acumular el acta de Diputado con la de una Asamblea autonómica"]'::jsonb,1,'Art. 67.2 CE','Nadie puede ser miembro de las dos Cámaras simultáneamente ni acumular el acta de una Asamblea de CA con la de Diputado al Congreso (art. 67.1).',null),
('aux-age:3-ada2d4707d','aux-age',3,'¿Entre qué número mínimo y máximo de Diputados puede componerse el Congreso según la Constitución?','["Entre 250 y 400", "Entre 350 y 400", "Entre 300 y 350", "Entre 300 y 400"]'::jsonb,3,'Art. 68.1 CE','La Constitución fija la horquilla y la LOREG concreta el número en 350.',null),
('aux-age:3-cc78bdc90a','aux-age',3,'Según el art. 68 CE, la circunscripción electoral para el Congreso es:','["La Comunidad Autónoma, y Ceuta y Melilla están representadas cada una por dos Diputados", "El municipio de más de 50.000 habitantes y, en los demás casos, la provincia", "La provincia, y Ceuta y Melilla están representadas cada una por un Diputado", "La provincia, y Ceuta y Melilla están representadas cada una por dos Diputados"]'::jsonb,2,'Art. 68.2 CE','La elección se verifica en cada circunscripción atendiendo a criterios de representación proporcional (art. 68.3).',null),
('aux-age:3-439ec216e1','aux-age',3,'Las elecciones generales deben tener lugar:','["Entre los 45 y 90 días desde la terminación del mandato", "En los 60 días siguientes a la disolución, sin plazo mínimo", "Entre los 30 y 60 días desde la terminación del mandato", "Entre los 15 y 30 días desde la terminación del mandato"]'::jsonb,2,'Art. 68.6 CE','El Congreso electo debe ser convocado dentro de los 25 días siguientes a la celebración de las elecciones.',null),
('aux-age:3-1bba8c03b7','aux-age',3,'El Congreso electo deberá ser convocado dentro de los:','["25 días siguientes a la celebración de las elecciones", "30 días siguientes a la celebración de las elecciones", "15 días siguientes a la proclamación de los electos", "25 días siguientes a la publicación de los resultados en el BOE"]'::jsonb,0,'Art. 68.6 CE','Así lo dispone el art. 68.6 CE.',null),
('aux-age:3-19fd045f9e','aux-age',3,'¿Cuántos Senadores elige cada una de las ciudades de Ceuta y Melilla?','["1", "3", "2", "4"]'::jsonb,2,'Art. 69.4 CE','Las provincias eligen 4 Senadores cada una por sufragio universal, libre, igual, directo y secreto.',null),
('aux-age:3-9d0314e498','aux-age',3,'Las Comunidades Autónomas designan para el Senado:','["Un Senador por cada 500.000 habitantes de su territorio", "Dos Senadores y otro más por cada millón de habitantes de su territorio", "Un Senador por cada provincia de la Comunidad", "Un Senador y otro más por cada millón de habitantes de su territorio"]'::jsonb,3,'Art. 69.5 CE','La designación corresponde a la Asamblea legislativa o, en su defecto, al órgano colegiado superior de la CA, asegurando la representación proporcional.',null),
('aux-age:3-e4cc52636b','aux-age',3,'Durante su mandato, los Diputados y Senadores solo podrán ser detenidos:','["Con autorización previa del Tribunal Supremo, salvo flagrante delito", "En ningún caso, mientras dure su mandato", "En caso de flagrante delito", "En caso de delito grave, con autorización del Presidente de la Cámara"]'::jsonb,2,'Art. 71.2 CE','Gozan de inmunidad: no pueden ser inculpados ni procesados sin la previa autorización de la Cámara respectiva.',null),
('aux-age:3-6f62bf2fbe','aux-age',3,'¿Qué órgano es competente en las causas contra Diputados y Senadores?','["El Tribunal Superior de Justicia de su circunscripción", "La Sala de lo Penal de la Audiencia Nacional", "La Sala de lo Penal del Tribunal Supremo", "El Tribunal Constitucional, en única instancia"]'::jsonb,2,'Art. 71.3 CE','Así lo establece el art. 71.3 CE.',null),
('aux-age:3-48f08e8f29','aux-age',3,'Los Reglamentos de las Cámaras y su reforma se aprueban:','["Por mayoría absoluta de las Cortes reunidas en sesión conjunta", "Por mayoría de tres quintos, en una votación final sobre su totalidad", "Por mayoría absoluta, en una votación final sobre su totalidad", "Por mayoría simple, artículo por artículo"]'::jsonb,2,'Art. 72.1 CE','Las Cámaras establecen sus propios Reglamentos y aprueban autónomamente sus presupuestos.',null),
('aux-age:3-ccc23f564e','aux-age',3,'Las sesiones conjuntas de ambas Cámaras están presididas por:','["El Presidente de mayor edad", "El Rey", "El Presidente del Congreso", "El Presidente del Senado"]'::jsonb,2,'Art. 72.2 CE','Se rigen por un Reglamento de las Cortes Generales aprobado por mayoría absoluta de cada Cámara.',null),
('aux-age:3-d3fd7b7e0b','aux-age',3,'¿Cuáles son los períodos ordinarios de sesiones de las Cámaras?','["De octubre a diciembre y de febrero a julio", "De septiembre a junio, sin interrupción", "De septiembre a diciembre y de febrero a junio", "De septiembre a diciembre y de enero a junio"]'::jsonb,2,'Art. 73.1 CE','Las Cámaras se reúnen anualmente en dos períodos ordinarios de sesiones.',null),
('aux-age:3-a4a41e676a','aux-age',3,'Las sesiones extraordinarias de las Cámaras pueden celebrarse a petición de:','["El Gobierno o la Diputación Permanente, pero no de los miembros de las Cámaras", "El Rey, el Gobierno o una quinta parte de los miembros de cualquiera de las Cámaras", "El Gobierno, la Diputación Permanente o la mayoría absoluta de los miembros de cualquiera de las Cámaras", "El Presidente del Gobierno, la Mesa del Congreso o la mitad de los grupos parlamentarios"]'::jsonb,2,'Art. 73.2 CE','Se convocan sobre un orden del día determinado y se clausuran una vez que este haya sido agotado.',null),
('aux-age:3-bc23f7c40c','aux-age',3,'¿Cuál de estas materias NO puede delegar el Pleno en las Comisiones Legislativas Permanentes?','["Una ley ordinaria sobre carreteras del Estado", "Los Presupuestos Generales del Estado", "Una ley sobre el régimen de las asociaciones de consumidores", "Una ley sobre el régimen de los colegios profesionales"]'::jsonb,1,'Art. 75.3 CE','Tampoco la reforma constitucional, las cuestiones internacionales, ni las leyes orgánicas y de bases.',null),
('aux-age:3-71ab0eeb3d','aux-age',3,'Las conclusiones de las comisiones de investigación de las Cámaras:','["Se remiten siempre al Tribunal Supremo, que decide si abre causa", "No son vinculantes para los Tribunales ni afectan a las resoluciones judiciales", "Vinculan a la Administración, que debe ejecutarlas en el plazo de un mes", "Son vinculantes para los Tribunales cuando se refieran a hechos delictivos"]'::jsonb,1,'Art. 76.1 CE','El resultado puede comunicarse al Ministerio Fiscal para el ejercicio de las acciones oportunas, y es obligatorio comparecer a requerimiento de las Cámaras (art. 76.2).',null),
('aux-age:3-6d617672dd','aux-age',3,'¿Cuántos miembros como mínimo tiene la Diputación Permanente de cada Cámara?','["15", "25", "30", "21"]'::jsonb,3,'Art. 78.1 CE','Representan a los grupos parlamentarios en proporción a su importancia numérica y la preside el Presidente de la Cámara.',null),
('aux-age:3-3b6fcb112e','aux-age',3,'Para adoptar acuerdos, las Cámaras deben estar reunidas reglamentariamente y con asistencia de:','["La mayoría de sus miembros", "Cualquier número de miembros", "Dos tercios de sus miembros", "Un tercio de sus miembros"]'::jsonb,0,'Art. 79.1 CE','Los acuerdos se aprueban, en general, por mayoría de los miembros presentes (art. 79.2).',null),
('aux-age:3-0dbe74cc8b','aux-age',3,'Según el art. 79.3 CE, el voto de Senadores y Diputados:','["Es personal, pero puede delegarse en otro miembro del mismo grupo", "Es personal, pero el portavoz puede emitirlo por todo el grupo", "Es indelegable, salvo enfermedad acreditada ante la Mesa", "Es personal e indelegable"]'::jsonb,3,'Art. 79.3 CE','Así lo dispone el art. 79.3 CE.',null),
('aux-age:3-184f77d286','aux-age',3,'Las sesiones plenarias de las Cámaras serán públicas:','["Salvo acuerdo en contrario de cada Cámara por mayoría absoluta o con arreglo al Reglamento", "Salvo acuerdo en contrario de la Mesa de cada Cámara", "En todo caso, sin excepción", "Salvo que lo solicite el Gobierno por razones de seguridad nacional, aunque no lo acuerde la Cámara"]'::jsonb,0,'Art. 80 CE','Así lo dispone el art. 80 CE.',null),
('aux-age:3-b3ae5fe58a','aux-age',3,'¿Quién tiene la iniciativa legislativa según el art. 87.1 CE?','["El Gobierno y el Congreso, pero no el Senado", "El Gobierno, el Congreso, el Senado y el Consejo General del Poder Judicial", "El Congreso y el Senado, y el Gobierno solo en materia presupuestaria", "El Gobierno, el Congreso y el Senado"]'::jsonb,3,'Art. 87.1 CE','Las Asambleas de las CCAA pueden solicitar al Gobierno la adopción de un proyecto o remitir a la Mesa del Congreso una proposición (art. 87.2), y existe la iniciativa popular (art. 87.3).',null),
('aux-age:3-1ebd51f928','aux-age',3,'¿Cuántas firmas acreditadas exige como mínimo la iniciativa legislativa popular?','["100.000", "1.000.000", "250.000", "500.000"]'::jsonb,3,'Art. 87.3 CE','No procede en materias propias de ley orgánica, tributarias, de carácter internacional ni en lo relativo a la prerrogativa de gracia.',null),
('aux-age:3-d6f2c9fdd0','aux-age',3,'¿En cuál de estas materias NO procede la iniciativa legislativa popular?','["En materia de vivienda", "En materia tributaria", "En materia de tráfico", "En materia de medio ambiente"]'::jsonb,1,'Art. 87.3 CE','Tampoco en materias de ley orgánica, de carácter internacional ni en la prerrogativa de gracia.',null),
('aux-age:3-6cf1f91628','aux-age',3,'Una Asamblea de Comunidad Autónoma que remite una proposición de ley a la Mesa del Congreso puede delegar su defensa ante esta Cámara en:','["Un máximo de tres miembros de la Asamblea", "Los Senadores designados por la Comunidad", "Un máximo de cinco miembros de la Asamblea", "El Presidente de la Comunidad Autónoma"]'::jsonb,0,'Art. 87.2 CE','Así lo dispone el art. 87.2 CE.',null),
('aux-age:3-aa99b00b16','aux-age',3,'¿En qué plazo puede el Senado oponer su veto o introducir enmiendas a un proyecto aprobado por el Congreso?','["Dos meses desde la aprobación en el Congreso, o un mes si el proyecto se declara urgente", "Dos meses desde el día de la recepción del texto, o veinte días naturales si el proyecto se declara urgente", "Un mes desde la recepción del texto, o diez días naturales si el proyecto se declara urgente", "Tres meses desde la recepción del texto, sin reducción por urgencia"]'::jsonb,1,'Art. 90.2 y 90.3 CE','El veto debe aprobarse por mayoría absoluta del Senado.',null),
('aux-age:3-d522398270','aux-age',3,'El veto del Senado puede ser levantado por el Congreso:','["Por mayoría de tres quintos, o por mayoría absoluta una vez transcurrido un mes", "Por mayoría de dos tercios, en sesión conjunta con el Senado", "Por mayoría absoluta, o por mayoría simple una vez transcurridos dos meses desde su interposición", "Por mayoría simple en todo caso, en una nueva votación"]'::jsonb,2,'Art. 90.2 CE','Así lo dispone el art. 90.2 CE.',null),
('aux-age:3-c155e851b4','aux-age',3,'El Rey sancionará las leyes aprobadas por las Cortes Generales en el plazo de:','["20 días", "10 días", "30 días", "15 días"]'::jsonb,3,'Art. 91 CE','Las promulgará y ordenará su inmediata publicación.',null),
('aux-age:3-9aa85ce3b7','aux-age',3,'El referéndum consultivo sobre decisiones políticas de especial trascendencia es convocado por:','["El Presidente del Gobierno, previa autorización de las Cortes Generales por mayoría absoluta", "El Rey, mediante propuesta del Presidente del Gobierno, previamente autorizada por el Congreso", "El Rey, a propuesta del Congreso de los Diputados por mayoría de tres quintos", "El Gobierno, previa deliberación del Consejo de Ministros y dictamen del Consejo de Estado"]'::jsonb,1,'Art. 92.2 CE','Lo regula la LO 2/1980.',null),
('aux-age:3-f0cc8e38ad','aux-age',3,'Los tratados por los que se atribuya a una organización internacional el ejercicio de competencias derivadas de la Constitución se autorizan:','["Por acuerdo del Consejo de Ministros", "Mediante ley orgánica", "Mediante referéndum", "Mediante ley ordinaria"]'::jsonb,1,'Art. 93 CE','Así se autorizó la adhesión de España a las Comunidades Europeas.',null),
('aux-age:3-f723b8f862','aux-age',3,'La moción de censura debe ser propuesta, al menos, por:','["Un grupo parlamentario, e incluir un candidato a la Presidencia del Gobierno", "La décima parte de los Diputados, sin necesidad de proponer candidato", "La quinta parte de los Diputados, e incluir un programa de gobierno alternativo", "La décima parte de los Diputados, e incluir un candidato a la Presidencia del Gobierno"]'::jsonb,3,'Art. 113.2 CE','Se adopta por mayoría absoluta del Congreso (art. 113.1).',null),
('aux-age:3-7c3961c862','aux-age',3,'La moción de censura no podrá ser votada hasta que transcurran:','["Cinco días desde su presentación", "Dos días desde su presentación", "Tres días desde su presentación", "Diez días desde su presentación"]'::jsonb,0,'Art. 113.3 CE','En los dos primeros días de ese plazo pueden presentarse mociones alternativas.',null),
('aux-age:3-2dae06ea79','aux-age',3,'Si la moción de censura no es aprobada, sus signatarios:','["No podrán presentar otra durante un año", "Podrán presentar otra pasados tres meses", "No podrán presentar otra durante el mismo período de sesiones", "No podrán presentar otra durante el resto de la legislatura"]'::jsonb,2,'Art. 113.4 CE','Así lo dispone el art. 113.4 CE.',null),
('aux-age:3-0fc50874c7','aux-age',3,'La confianza se entiende otorgada cuando vote a favor:','["La mayoría absoluta de los Diputados", "La mayoría absoluta de cada Cámara", "Las tres quintas partes de los Diputados", "La mayoría simple de los Diputados"]'::jsonb,3,'Art. 112 CE','El Presidente plantea la cuestión de confianza, previa deliberación del Consejo de Ministros, sobre su programa o una declaración de política general.',null),
('aux-age:3-d4606c1931','aux-age',3,'Según el art. 115 CE, la disolución de las Cámaras NO puede acordarse:','["Durante los dos primeros años de la legislatura, salvo que lo autorice el Congreso por mayoría absoluta", "Cuando esté en trámite una moción de censura, ni antes de que transcurra un año desde la anterior, salvo lo dispuesto en el art. 99.5", "Cuando esté en trámite una cuestión de confianza o durante el período de sesiones", "Durante el estado de alarma ni antes de que transcurran seis meses desde la anterior"]'::jsonb,1,'Art. 115.2 y 115.3 CE','La disolución la propone el Presidente, previa deliberación del Consejo de Ministros y bajo su exclusiva responsabilidad.',null),
('aux-age:3-efe22bf7a2','aux-age',3,'Según el art. 54 CE, el Defensor del Pueblo es:','["Alto comisionado del Gobierno, designado por el Consejo de Ministros para supervisar a la Administración", "Alto comisionado de las Cortes Generales, designado por estas para la defensa de los derechos del Título I", "Alto comisionado de las Cortes Generales, designado por el Rey a propuesta del Congreso", "Órgano del Poder Judicial encargado de la defensa de los derechos fundamentales"]'::jsonb,1,'Art. 54 CE','Puede supervisar la actividad de la Administración, dando cuenta a las Cortes Generales.',null),
('aux-age:3-22e23cf127','aux-age',3,'¿Por cuánto tiempo es elegido el Defensor del Pueblo?','["9 años", "4 años", "6 años", "5 años"]'::jsonb,3,'Art. 2.1 LO 3/1981','Lo eligen las Cortes Generales para un período de cinco años.',null),
('aux-age:3-2de8cfa617','aux-age',3,'Si en la elección del Defensor del Pueblo no se alcanzan las mayorías iniciales, la designación queda realizada cuando, tras obtener en el Congreso la mayoría de tres quintos, se alcanza en el Senado:','["La mayoría simple", "La mayoría de tres quintos", "La mayoría absoluta", "La mayoría de dos tercios"]'::jsonb,2,'Art. 2.5 LO 3/1981','En primer término se exigen tres quintos en el Congreso y la ratificación por la misma mayoría en el Senado.',null),
('aux-age:3-0cc5ea9d76','aux-age',3,'¿En qué plazo puede presentarse una queja ante el Defensor del Pueblo?','["En cualquier momento, sin plazo, siempre que los hechos no estén prescritos", "En el plazo máximo de un año, contado a partir del momento en que se tuvo conocimiento de los hechos", "En el plazo máximo de tres meses desde que se produjeron los hechos objeto de la queja", "En el plazo de seis meses desde la notificación de la resolución administrativa"]'::jsonb,1,'Art. 15.1 LO 3/1981','La queja se presenta firmada, con nombre, apellidos y domicilio, y es gratuita: no requiere abogado ni procurador.',null),
('aux-age:3-b76763137e','aux-age',3,'¿Cuántos Adjuntos auxilian al Defensor del Pueblo?','["Uno solo, que le sustituye en caso de ausencia", "Dos: un Adjunto primero y un Adjunto segundo", "Cuatro, nombrados por las Cortes Generales", "Tres, uno por cada área de supervisión"]'::jsonb,1,'Art. 8.1 LO 3/1981','El Defensor les delega funciones y le sustituyen por su orden en caso de imposibilidad temporal o cese.',null),
('aux-age:4-7c29f0e91b','aux-age',4,'Según el art. 117.1 CE, la justicia emana del pueblo y se administra:','["En nombre del pueblo español por Jueces, Magistrados y Fiscales integrantes del poder judicial", "En nombre del Rey por el Consejo General del Poder Judicial", "En nombre de las Cortes Generales por Jueces y Magistrados", "En nombre del Rey por Jueces y Magistrados integrantes del poder judicial"]'::jsonb,3,'Art. 117.1 CE','Los Jueces y Magistrados son independientes, inamovibles, responsables y están sometidos únicamente al imperio de la ley.',null),
('aux-age:4-8b5348c58c','aux-age',4,'¿Cuál de estas notas NO atribuye el art. 117.1 CE a los Jueces y Magistrados?','["Responsabilidad", "Inamovilidad", "Independencia", "Jerarquía"]'::jsonb,3,'Art. 117.1 CE','Son independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley. La dependencia jerárquica es un principio del Ministerio Fiscal (art. 124.2).',null),
('aux-age:4-c327759578','aux-age',4,'Los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados:','["En ningún caso antes de cumplir la edad de jubilación forzosa", "Sino por alguna de las causas y con las garantías previstas en la ley", "Sino por sentencia firme de la Sala de lo Penal del Tribunal Supremo, a instancia del Ministerio Fiscal", "Sino por acuerdo del Ministerio de Justicia, oído el interesado"]'::jsonb,1,'Art. 117.2 CE','Es la garantía de inamovilidad.',null),
('aux-age:4-18d51f39aa','aux-age',4,'El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde:','["A los Juzgados y Tribunales y, en materia administrativa, a los órganos de la Administración", "A los Juzgados y Tribunales, salvo la ejecución, que corresponde al Gobierno", "Exclusivamente a los Juzgados y Tribunales determinados por las leyes", "Al Consejo General del Poder Judicial y a los Juzgados y Tribunales"]'::jsonb,2,'Art. 117.3 CE','Se ejerce en todo tipo de procesos, según las normas de competencia y procedimiento que las leyes establezcan.',null),
('aux-age:4-25c04522d1','aux-age',4,'Según el art. 117.6 CE, los Tribunales de excepción:','["Pueden crearse por ley orgánica", "Están prohibidos", "Solo pueden crearse durante el estado de sitio", "Dependen del Tribunal Supremo"]'::jsonb,1,'Art. 117.6 CE','La ley regula la jurisdicción militar en el ámbito estrictamente castrense y en los supuestos de estado de sitio (art. 117.5).',null),
('aux-age:4-ff58656254','aux-age',4,'La justicia será gratuita, según el art. 119 CE:','["Solo para quienes acrediten insuficiencia de recursos, sin otros supuestos", "Solo en los procesos penales y en los procesos laborales", "Cuando así lo disponga la ley y, en todo caso, respecto de quienes acrediten insuficiencia de recursos para litigar", "Siempre, para todos los ciudadanos españoles y para los extranjeros residentes legalmente en España, en cualquier proceso"]'::jsonb,2,'Art. 119 CE','Así lo dispone el art. 119 CE.',null),
('aux-age:4-2372fb7516','aux-age',4,'Según el art. 120 CE, el procedimiento judicial:','["Será oral en todo caso y en todas las jurisdicciones", "Será secreto salvo en el acto del juicio", "Será predominantemente oral, sobre todo en materia criminal", "Será predominantemente escrito, salvo en materia criminal, en la que será oral"]'::jsonb,2,'Art. 120.2 CE','Las actuaciones judiciales son públicas, con las excepciones que prevean las leyes de procedimiento (art. 120.1).',null),
('aux-age:4-8c1d89cb6f','aux-age',4,'Las sentencias, según el art. 120.3 CE:','["Se pronunciarán en audiencia pública solo en materia penal", "Se notificarán por escrito y no se pronuncian en audiencia pública", "Serán motivadas solo cuando sean condenatorias", "Serán siempre motivadas y se pronunciarán en audiencia pública"]'::jsonb,3,'Art. 120.3 CE','Así lo dispone el art. 120.3 CE.',null),
('aux-age:4-c06690712d','aux-age',4,'Los daños causados por error judicial y los que sean consecuencia del funcionamiento anormal de la Administración de Justicia:','["Darán derecho a una indemnización a cargo del Estado, conforme a la ley", "Darán derecho a indemnización a cargo del Consejo General del Poder Judicial", "No darán derecho a indemnización, salvo que exista dolo", "Darán derecho a una indemnización a cargo del juez o magistrado responsable"]'::jsonb,0,'Art. 121 CE','Así lo dispone el art. 121 CE.',null),
('aux-age:4-2a71cf1a23','aux-age',4,'¿Cuál es el órgano de gobierno del Poder Judicial?','["El Tribunal Constitucional, a través de su Pleno", "El Tribunal Supremo", "El Consejo General del Poder Judicial", "El Ministerio de Justicia"]'::jsonb,2,'Art. 122.2 CE','La ley orgánica establece su estatuto, régimen de incompatibilidades y funciones, en particular en nombramientos, ascensos, inspección y régimen disciplinario.',null),
('aux-age:4-7778647d5e','aux-age',4,'Según el art. 122.3 CE, el Consejo General del Poder Judicial está integrado por:','["El Ministro de Justicia, que lo preside, y veinte miembros nombrados por el Rey por cinco años", "El Presidente del Tribunal Supremo, que lo preside, y veinte miembros nombrados por el Rey por cuatro años", "El Presidente del Tribunal Supremo, que lo preside, y doce miembros nombrados por el Rey por cinco años", "El Presidente del Tribunal Supremo, que lo preside, y veinte miembros nombrados por el Rey por cinco años"]'::jsonb,3,'Art. 122.3 CE','De los veinte vocales, doce son Jueces y Magistrados y ocho se nombran a propuesta de las Cámaras.',null),
('aux-age:4-f8def6707b','aux-age',4,'De los veinte vocales del CGPJ, ¿cuántos se eligen entre Jueces y Magistrados de todas las categorías judiciales?','["12", "8", "10", "16"]'::jsonb,0,'Art. 122.3 CE','Los otros ocho los proponen el Congreso (cuatro) y el Senado (cuatro), por mayoría de tres quintos.',null),
('aux-age:4-13e5ec0c7f','aux-age',4,'Los vocales del CGPJ propuestos por las Cámaras se eligen entre:','["Magistrados del Tribunal Supremo con más de quince años de antigüedad en la carrera", "Abogados y otros juristas de reconocida competencia con más de quince años de ejercicio en su profesión", "Abogados y otros juristas de reconocida competencia con más de diez años de ejercicio en su profesión", "Catedráticos de Derecho y fiscales con más de veinte años de ejercicio profesional"]'::jsonb,1,'Art. 122.3 CE','Cuatro a propuesta del Congreso y cuatro a propuesta del Senado, elegidos en ambos casos por mayoría de tres quintos.',null),
('aux-age:4-603c32b681','aux-age',4,'Según el art. 123 CE, el Tribunal Supremo:','["Es el órgano de gobierno del Poder Judicial y el superior en todos los órdenes", "Es el órgano jurisdiccional superior en todos los órdenes, incluida la materia de garantías constitucionales y el recurso de amparo", "Es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías constitucionales", "Es el órgano jurisdiccional superior solo en el orden penal y en el contencioso-administrativo"]'::jsonb,2,'Art. 123.1 CE','Tiene jurisdicción en toda España. En garantías constitucionales, el órgano superior es el Tribunal Constitucional.',null),
('aux-age:4-8f01aaca96','aux-age',4,'El Presidente del Tribunal Supremo será nombrado por el Rey:','["A propuesta del Gobierno, oído el Consejo General del Poder Judicial y la Sala de Gobierno del propio Tribunal", "A propuesta del Consejo General del Poder Judicial, en la forma que determine la ley", "A propuesta de la Sala de Gobierno del propio Tribunal Supremo", "A propuesta del Congreso de los Diputados por mayoría de tres quintos"]'::jsonb,1,'Art. 123.2 CE','Así lo dispone el art. 123.2 CE.',null),
('aux-age:4-d520325de4','aux-age',4,'¿Dónde tiene su sede el Tribunal Supremo?','["En Granada", "En Barcelona", "En Madrid", "En Valladolid"]'::jsonb,2,'Art. 53 LOPJ','Tiene sede en Madrid y jurisdicción en toda España, y ningún otro órgano puede usar la denominación de «Supremo».',null),
('aux-age:4-2b3c370927','aux-age',4,'¿Cuántas Salas tiene el Tribunal Supremo?','["Cinco: Civil, Penal, Contencioso-administrativo, Social y Militar", "Cuatro: Civil, Penal, Contencioso-administrativo y Social", "Seis: Civil, Penal, Contencioso-administrativo, Social, Militar y de Apelación", "Cinco: Civil, Penal, Contencioso-administrativo, Social y de Apelación"]'::jsonb,0,'Art. 55 LOPJ','Sala Primera, de lo Civil; Segunda, de lo Penal; Tercera, de lo Contencioso-administrativo; Cuarta, de lo Social; y Quinta, de lo Militar.',null),
('aux-age:4-d6a328af8e','aux-age',4,'La Sala Tercera del Tribunal Supremo es la:','["De lo Contencioso-administrativo", "De lo Social y de lo Laboral", "De lo Penal", "De lo Militar"]'::jsonb,0,'Art. 55 LOPJ','La Primera es la de lo Civil, la Segunda la de lo Penal, la Cuarta la de lo Social y la Quinta la de lo Militar.',null),
('aux-age:4-d6c14fe9cd','aux-age',4,'La Audiencia Nacional:','["Tiene su sede en Madrid y jurisdicción en toda España", "Tiene su sede en Madrid y jurisdicción solo en la Comunidad de Madrid", "No tiene sede fija y se reúne donde lo acuerde el CGPJ", "Tiene su sede en Madrid y es el órgano superior en el orden penal"]'::jsonb,0,'Art. 62 LOPJ','Está integrada por las Salas de Apelación, de lo Penal, de lo Contencioso-administrativo y de lo Social (art. 64 LOPJ).',null),
('aux-age:4-bc5665eddd','aux-age',4,'¿Cuál de estas Salas NO forma parte de la Audiencia Nacional?','["Sala de lo Civil", "Sala de lo Social", "Sala de lo Penal", "Sala de Apelación"]'::jsonb,0,'Art. 64 LOPJ','La Audiencia Nacional tiene Salas de Apelación, de lo Penal, de lo Contencioso-administrativo y de lo Social.',null),
('aux-age:4-517fd99c43','aux-age',4,'A efectos judiciales, el Estado se organiza territorialmente en:','["Municipios, comarcas, provincias y Comunidades Autónomas", "Municipios, partidos, provincias y Comunidades Autónomas", "Distritos, partidos judiciales y Comunidades Autónomas", "Partidos judiciales, provincias y circunscripciones"]'::jsonb,1,'Art. 30 LOPJ','Así lo establece el art. 30 LOPJ.',null),
('aux-age:4-fa12c41251','aux-age',4,'Tras la reforma de la LO 1/2025, ¿qué órganos sustituyen a los Juzgados unipersonales de primera instancia, instrucción, penal, social, etc.?','["Las Audiencias Provinciales", "Los Tribunales de Instancia", "Las Oficinas de Justicia en los municipios", "Los Tribunales Superiores de Justicia"]'::jsonb,1,'Art. 26 LOPJ (redacción LO 1/2025)','La potestad jurisdiccional se atribuye a jueces de paz, Tribunales de Instancia, Audiencias Provinciales, TSJ, Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo.',null),
('aux-age:4-1f99fe619d','aux-age',4,'Según el art. 26 LOPJ, en su redacción vigente, ¿cuál de estos órganos tiene atribuida potestad jurisdiccional?','["La Fiscalía General del Estado", "El Tribunal Central de Instancia", "El Consejo General del Poder Judicial", "El Ministerio de Justicia"]'::jsonb,1,'Art. 26 LOPJ','Junto con los jueces de paz, los Tribunales de Instancia, las Audiencias Provinciales, los TSJ, la Audiencia Nacional y el Tribunal Supremo.',null),
('aux-age:4-27fba9c44d','aux-age',4,'Según el art. 152.1 CE, el Tribunal Superior de Justicia:','["Culmina la organización judicial en el ámbito territorial de la Comunidad Autónoma, sin perjuicio de la jurisdicción del Tribunal Supremo", "Es el órgano jurisdiccional superior en todos los órdenes dentro de la Comunidad, sin que quepa recurso ante el Tribunal Supremo", "Es el órgano de gobierno de los jueces de la Comunidad Autónoma", "Depende del Gobierno autonómico, que nombra a su Presidente"]'::jsonb,0,'Art. 152.1 CE','Las sucesivas instancias procesales se agotan ante órganos radicados en el mismo territorio de la CA en que esté el órgano competente en primera instancia.',null),
('aux-age:4-cb00b5bbcc','aux-age',4,'Según el art. 124 CE, el Ministerio Fiscal ejerce sus funciones conforme a los principios de:','["Independencia e inamovilidad, con sujeción en todo caso a los de legalidad y oportunidad", "Unidad de actuación y dependencia jerárquica, con sujeción en todo caso a los de legalidad e imparcialidad", "Jerarquía y oportunidad, con sujeción a los de legalidad e imparcialidad", "Unidad de actuación y autonomía funcional, con sujeción a las instrucciones del Ministerio de Justicia en cada caso"]'::jsonb,1,'Art. 124.2 CE','Lo hace por medio de órganos propios.',null),
('aux-age:4-c0a69760b9','aux-age',4,'¿Quién nombra al Fiscal General del Estado?','["El Gobierno, a propuesta del Ministro de Justicia, oído el Congreso", "El Rey, a propuesta del Gobierno, oído el Consejo General del Poder Judicial", "El Rey, a propuesta del Consejo General del Poder Judicial, oído el Gobierno", "El Congreso de los Diputados, por mayoría de tres quintos"]'::jsonb,1,'Art. 124.4 CE','Así lo dispone el art. 124.4 CE.',null),
('aux-age:4-cd269409e9','aux-age',4,'Según el art. 124.1 CE, ¿cuál de estas es una misión del Ministerio Fiscal?','["Dirigir la Administración de Justicia, nombrar a los jueces y magistrados y ejercer sobre ellos la potestad disciplinaria, por delegación del CGPJ", "Juzgar los delitos cometidos por los miembros del Gobierno", "Ejercer la potestad disciplinaria sobre jueces y magistrados", "Promover la acción de la justicia en defensa de la legalidad, los derechos de los ciudadanos y el interés público tutelado por la ley"]'::jsonb,3,'Art. 124.1 CE','También velar por la independencia de los Tribunales y procurar ante ellos la satisfacción del interés social.',null),
('aux-age:4-8e466ed6df','aux-age',4,'Según el art. 125 CE, los ciudadanos podrán participar en la Administración de Justicia mediante:','["La acción popular y la elección directa de los jueces de paz en todos los municipios, y la institución del Jurado en los procesos civiles y penales que determine la ley", "La acción popular, pero no la institución del Jurado", "La institución del Jurado en todos los procesos penales y civiles", "La acción popular y la institución del Jurado, en la forma y en los procesos penales que la ley determine, y en los Tribunales consuetudinarios y tradicionales"]'::jsonb,3,'Art. 125 CE','El Tribunal del Jurado se regula en la LO 5/1995.',null),
('aux-age:4-d142f78fa4','aux-age',4,'La policía judicial depende, en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente:','["De la Audiencia Nacional", "De los Jueces, de los Tribunales y del Ministerio Fiscal", "Del Ministerio del Interior en exclusiva, a través de las Fuerzas y Cuerpos de Seguridad del Estado", "Del Consejo General del Poder Judicial"]'::jsonb,1,'Art. 126 CE','Así lo dispone el art. 126 CE.',null),
('aux-age:4-e337aebf35','aux-age',4,'Los Jueces y Magistrados, así como los Fiscales, mientras se hallen en activo:','["Podrán pertenecer a partidos políticos y sindicatos, pero no ocupar cargos directivos en ellos ni desempeñar otros cargos públicos", "No podrán desempeñar otros cargos públicos ni pertenecer a partidos políticos o sindicatos", "No podrán pertenecer a sindicatos, pero sí a partidos políticos", "Podrán desempeñar cargos públicos con autorización del CGPJ"]'::jsonb,1,'Art. 127.1 CE','La ley establece el sistema y modalidades de asociación profesional.',null),
('aux-age:4-0d62baa27d','aux-age',4,'¿Pueden los Jueces y Magistrados en activo asociarse profesionalmente?','["No, solo pueden afiliarse a sindicatos", "Sí, la ley establece el sistema y las modalidades de asociación profesional", "Sí, pero solo a través de partidos políticos", "No, la asociación está prohibida en todo caso"]'::jsonb,1,'Art. 127.1 CE','Lo que tienen prohibido es pertenecer a partidos políticos o sindicatos.',null),
('aux-age:4-1997719acd','aux-age',4,'Según el art. 118 CE, cumplir las sentencias y demás resoluciones firmes de los Jueces y Tribunales:','["Es obligado, así como prestar la colaboración requerida por estos en el curso del proceso y en la ejecución de lo resuelto", "Es voluntario hasta que se dicte el auto de ejecución", "Es obligado para los particulares, pero no para la Administración, que puede suspender su ejecución por razones de interés público apreciadas por el Gobierno", "Es obligado solo para las partes del proceso"]'::jsonb,0,'Art. 118 CE','Así lo dispone el art. 118 CE.',null),
('aux-age:4-fa8244a947','aux-age',4,'El principio de unidad jurisdiccional es, según el art. 117.5 CE:','["La base de la organización y funcionamiento de los Tribunales", "Una excepción aplicable solo a la jurisdicción militar", "La base de la organización del Ministerio Fiscal", "Un principio que rige solo en el Tribunal Supremo"]'::jsonb,0,'Art. 117.5 CE','La ley regula el ejercicio de la jurisdicción militar en el ámbito estrictamente castrense y en los supuestos de estado de sitio.',null),
('aux-age:4-1260c9de6e','aux-age',4,'¿Qué ley determina la constitución, funcionamiento y gobierno de los Juzgados y Tribunales?','["La Ley de Enjuiciamiento Civil", "El Reglamento del Consejo General del Poder Judicial", "La Ley de Planta y Demarcación Judicial", "La Ley Orgánica del Poder Judicial"]'::jsonb,3,'Art. 122.1 CE','También el estatuto jurídico de los Jueces y Magistrados de carrera y del personal al servicio de la Administración de Justicia.',null),
('aux-age:5-1cf36203bf','aux-age',5,'Según el art. 97 CE, el Gobierno dirige:','["La Administración civil y militar, y las Cortes dirigen la política interior y la exterior", "La política interior y exterior, la Administración civil y militar y la defensa del Estado", "La política interior y exterior y la Administración civil, pero no la militar, que corresponde al Rey", "La política interior, mientras que la exterior y la defensa corresponden al Rey como Jefe del Estado"]'::jsonb,1,'Art. 97 CE','Ejerce la función ejecutiva y la potestad reglamentaria de acuerdo con la Constitución y las leyes.',null),
('aux-age:5-deafa89de8','aux-age',5,'Según el art. 98.1 CE, el Gobierno se compone de:','["El Presidente, los Vicepresidentes, en su caso, los Ministros y los demás miembros que establezca la ley", "El Presidente, los Vicepresidentes, los Ministros y los Subsecretarios de cada Departamento", "El Presidente, los Vicepresidentes y los Ministros, sin que una ley pueda añadir otros miembros distintos de los citados", "El Presidente, los Ministros y los Secretarios de Estado"]'::jsonb,0,'Art. 98.1 CE','La Ley 50/1997 concreta que el Gobierno se compone del Presidente, del Vicepresidente o Vicepresidentes, en su caso, y de los Ministros (art. 1.2).',null),
('aux-age:5-d5aef736a1','aux-age',5,'¿Quién dirige la acción del Gobierno y coordina las funciones de los demás miembros?','["El Consejo de Ministros", "El Ministro de la Presidencia", "El Presidente", "El Vicepresidente primero"]'::jsonb,2,'Art. 98.2 CE','Sin perjuicio de la competencia y responsabilidad directa de los Ministros en su gestión.',null),
('aux-age:5-0409cb4d5a','aux-age',5,'Según el art. 98.3 CE, los miembros del Gobierno:','["No pueden ejercer otras funciones representativas que las propias del mandato parlamentario, ni otra función pública que no derive de su cargo, ni actividad profesional o mercantil alguna", "No pueden ser a la vez Diputados ni Senadores", "Pueden compatibilizar su cargo con otra función pública si lo autoriza el Consejo de Ministros", "Pueden ejercer actividades profesionales si no tienen relación con su Departamento"]'::jsonb,0,'Art. 98.3 CE','Por eso sí pueden ser parlamentarios a la vez.',null),
('aux-age:5-59df4492ce','aux-age',5,'Antes de proponer un candidato a la Presidencia del Gobierno, el Rey consulta:','["Al Consejo de Estado y a los presidentes de las Comunidades Autónomas", "A los representantes designados por los grupos políticos con representación parlamentaria", "Al candidato de la lista más votada, que es propuesto en todo caso", "A los Presidentes del Congreso y del Senado y al Presidente del Tribunal Constitucional, por este orden"]'::jsonb,1,'Art. 99.1 CE','La propuesta se hace a través del Presidente del Congreso.',null),
('aux-age:5-3dc93619ff','aux-age',5,'En la investidura, si el candidato no obtiene la mayoría absoluta del Congreso en la primera votación:','["Se somete a nueva votación 48 horas después y la confianza se entiende otorgada por mayoría simple", "Se somete a nueva votación una semana después y basta la mayoría simple", "Se somete a nueva votación 24 horas después y se exige de nuevo la mayoría absoluta de los miembros del Congreso", "Se disuelven las Cámaras y se convocan elecciones generales"]'::jsonb,0,'Art. 99.3 CE','Así lo dispone el art. 99.3 CE.',null),
('aux-age:5-6d2d395f8e','aux-age',5,'Si transcurren dos meses desde la primera votación de investidura sin que ningún candidato obtenga la confianza del Congreso:','["El Rey disuelve el Congreso, pero no el Senado, con el refrendo del Presidente del Gobierno en funciones", "El Rey nombra Presidente al candidato de la lista más votada", "El Rey disuelve ambas Cámaras y convoca nuevas elecciones con el refrendo del Presidente del Congreso", "El Congreso elige Presidente por mayoría simple sin necesidad de propuesta del Rey"]'::jsonb,2,'Art. 99.5 CE','Así lo dispone el art. 99.5 CE.',null),
('aux-age:5-445bce0add','aux-age',5,'Los demás miembros del Gobierno son nombrados y separados:','["Por el Rey, previa autorización del Congreso", "Por el Consejo de Ministros", "Por el Presidente del Gobierno, dando cuenta al Congreso", "Por el Rey, a propuesta de su Presidente"]'::jsonb,3,'Art. 100 CE','Así lo dispone el art. 100 CE.',null),
('aux-age:5-02fe51e0ff','aux-age',5,'¿En cuál de estos casos NO cesa el Gobierno según el art. 101 CE?','["Por pérdida de la confianza parlamentaria", "Tras la celebración de elecciones generales", "Por fallecimiento de su Presidente", "Cuando dimite un Vicepresidente"]'::jsonb,3,'Art. 101.1 CE','Cesa tras las elecciones generales, por pérdida de la confianza parlamentaria y por dimisión o fallecimiento de su Presidente.',null),
('aux-age:5-6ed89ecd6a','aux-age',5,'El Gobierno cesante:','["Es sustituido por la Comisión General de Secretarios de Estado y Subsecretarios", "Continúa en funciones durante un máximo de dos meses", "Continúa en funciones hasta la toma de posesión del nuevo Gobierno", "Cesa inmediatamente y le sustituye el Presidente del Congreso hasta el nuevo nombramiento"]'::jsonb,2,'Art. 101.2 CE','Así lo dispone el art. 101.2 CE.',null),
('aux-age:5-2517808880','aux-age',5,'¿Qué órgano es competente para exigir la responsabilidad criminal del Presidente y los demás miembros del Gobierno?','["El Congreso de los Diputados", "La Sala de lo Penal de la Audiencia Nacional", "La Sala de lo Penal del Tribunal Supremo", "El Tribunal Constitucional"]'::jsonb,2,'Art. 102.1 CE','Así lo dispone el art. 102.1 CE.',null),
('aux-age:5-3203ce6228','aux-age',5,'Si la acusación contra miembros del Gobierno fuera por traición o por cualquier delito contra la seguridad del Estado en el ejercicio de sus funciones, solo podrá plantearse:','["Por iniciativa de la décima parte de los miembros del Congreso y con la aprobación de la mayoría simple de la Cámara en votación pública", "Por iniciativa de la cuarta parte de los miembros del Congreso y con la aprobación de la mayoría absoluta del mismo", "Por iniciativa del Ministerio Fiscal y con la autorización del Senado", "Por iniciativa de la quinta parte de cada Cámara y con aprobación por tres quintos"]'::jsonb,1,'Art. 102.2 CE','La prerrogativa real de gracia no es aplicable a estos supuestos (art. 102.3).',null),
('aux-age:5-5d0c748ed0','aux-age',5,'Según el art. 103.1 CE, la Administración Pública sirve con objetividad los intereses generales y actúa de acuerdo con los principios de:','["Eficacia, jerarquía, centralización, concentración y coordinación", "Eficiencia, autonomía, descentralización, desconcentración y cooperación", "Eficacia, jerarquía, descentralización, oportunidad y coordinación", "Eficacia, jerarquía, descentralización, desconcentración y coordinación"]'::jsonb,3,'Art. 103.1 CE','Con sometimiento pleno a la ley y al Derecho.',null),
('aux-age:5-5524e1064d','aux-age',5,'El supremo órgano consultivo del Gobierno es:','["El Consejo de Ministros", "El Consejo Económico y Social", "La Abogacía General del Estado", "El Consejo de Estado"]'::jsonb,3,'Art. 107 CE','Una ley orgánica regula su composición y competencia (LO 3/1980).',null),
('aux-age:5-4f1e291ee0','aux-age',5,'Según el art. 106.1 CE, ¿quién controla la potestad reglamentaria y la legalidad de la actuación administrativa?','["El Consejo de Estado", "El Defensor del Pueblo", "Los Tribunales", "El Tribunal de Cuentas"]'::jsonb,2,'Art. 106.1 CE','También el sometimiento de la actuación administrativa a los fines que la justifican.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-age:5-e8f74a750b','aux-age',5,'Según la Ley 50/1997, los miembros del Gobierno se reúnen en:','["Consejo de Ministros y en la Comisión General de Secretarios de Estado y Subsecretarios", "Consejo de Ministros solamente", "Consejo de Ministros y en Comisiones Delegadas del Gobierno", "Consejo de Ministros, en Comisiones Delegadas y en Conferencias Sectoriales"]'::jsonb,2,'Art. 1.3 Ley 50/1997','La Comisión General de Secretarios de Estado y Subsecretarios es un órgano de apoyo, no de reunión de los miembros del Gobierno.',null),
('aux-age:5-206804d0fa','aux-age',5,'¿Cuál de estas competencias corresponde al Presidente del Gobierno según la Ley 50/1997?','["Aprobar los reales decretos-leyes y los reales decretos legislativos", "Declarar el estado de alarma y el de excepción", "Aprobar los reglamentos para el desarrollo y la ejecución de las leyes, previo dictamen del Consejo de Estado, y acordar la negociación de los tratados", "Crear, modificar y suprimir, por real decreto, los Departamentos ministeriales y las Secretarías de Estado"]'::jsonb,3,'Art. 2.2 j) Ley 50/1997','Las otras tres son competencias del Consejo de Ministros (art. 5).',null),
('aux-age:5-9d3dfb09e9','aux-age',5,'¿A quién corresponde aprobar los reales decretos-leyes y los reales decretos legislativos?','["Al Ministro competente por razón de la materia, con el visto bueno del Presidente", "Al Presidente del Gobierno", "A las Comisiones Delegadas del Gobierno", "Al Consejo de Ministros"]'::jsonb,3,'Art. 5.1 c) Ley 50/1997','Así lo dispone la Ley del Gobierno.',null),
('aux-age:5-09d79a8735','aux-age',5,'¿Quién ejerce la secretaría del Consejo de Ministros?','["El Ministro de la Presidencia", "El Secretario General Técnico de la Presidencia", "El Subsecretario de la Presidencia", "El Vicepresidente primero del Gobierno"]'::jsonb,0,'Art. 5.3 Ley 50/1997','Las deliberaciones del Consejo de Ministros son secretas.',null),
('aux-age:5-3cedb96f81','aux-age',5,'Según la Ley 50/1997, las deliberaciones del Consejo de Ministros:','["Son públicas, salvo que el Consejo acuerde lo contrario", "Se recogen en acta, que puede consultar cualquier ciudadano", "Son secretas", "Se publican en el BOE en extracto"]'::jsonb,2,'Art. 5.3 Ley 50/1997','Los documentos que se presenten tienen carácter reservado hasta que se hagan públicos.',null),
('aux-age:5-30ebee2d21','aux-age',5,'Las Comisiones Delegadas del Gobierno se crean, modifican y suprimen:','["Por ley de las Cortes Generales", "Por orden del Ministro de la Presidencia", "Por real decreto del Consejo de Ministros, a propuesta del Presidente del Gobierno", "Por acuerdo de la Comisión General de Secretarios de Estado y Subsecretarios, a propuesta del Ministro competente"]'::jsonb,2,'Art. 6.1 Ley 50/1997','El real decreto de creación indica, entre otras cosas, el miembro del Gobierno que asume la presidencia y sus funciones.',null),
('aux-age:5-9108aff4e8','aux-age',5,'¿Quién preside la Comisión General de Secretarios de Estado y Subsecretarios?','["Un Vicepresidente del Gobierno o, en su defecto, el Ministro de la Presidencia", "El Subsecretario de la Presidencia", "El Secretario de Estado de Relaciones con las Cortes y con la Comisión General de Codificación", "El Presidente del Gobierno"]'::jsonb,0,'Art. 8.3 Ley 50/1997','El Secretario de la Comisión es el Subsecretario de la Presidencia.',null),
('aux-age:5-64aab8211e','aux-age',5,'Para ser miembro del Gobierno se requiere, según la Ley 50/1997:','["Ser español de origen, mayor de 25 años y tener la condición de Diputado o Senador", "Ser español, mayor de edad, disfrutar de los derechos de sufragio activo y pasivo y no estar inhabilitado para ejercer empleo o cargo público por sentencia judicial firme", "Ser español, mayor de edad y tener una titulación universitaria", "Ser español o nacional de un Estado de la UE, mayor de edad y no estar inhabilitado"]'::jsonb,1,'Art. 11 Ley 50/1997','No se exige ser parlamentario.',null),
('aux-age:5-e2ec8b76f0','aux-age',5,'En caso de vacante, ausencia o enfermedad, las funciones del Presidente del Gobierno son asumidas:','["Por el Ministro de mayor edad, como en las Mesas de edad", "Por los Vicepresidentes, de acuerdo con el correspondiente orden de prelación, y en defecto de ellos por los Ministros, según el orden de precedencia de los Departamentos", "Por el Ministro de la Presidencia en todo caso", "Por el Presidente del Congreso hasta la elección de un nuevo Presidente del Gobierno"]'::jsonb,1,'Art. 13.1 Ley 50/1997','Así lo establece la Ley del Gobierno.',null),
('aux-age:5-61264aae96','aux-age',5,'El Gobierno en funciones NO podrá:','["Aprobar el Proyecto de Ley de Presupuestos Generales del Estado", "Despachar los asuntos públicos ordinarios", "Adoptar medidas en casos de urgencia debidamente acreditados o por razones de interés general", "Aprobar reales decretos de desarrollo de leyes"]'::jsonb,0,'Art. 21.5 Ley 50/1997','Tampoco puede presentar proyectos de ley al Congreso o, en su caso, al Senado. Limita su gestión al despacho ordinario, salvo urgencia o interés general acreditados.',null),
('aux-age:5-79987db946','aux-age',5,'El Presidente del Gobierno en funciones NO puede:','["Presidir el Consejo de Ministros ni refrendar los actos del Rey", "Nombrar Ministros para cubrir vacantes en el Gobierno", "Representar al Gobierno ante las Cortes ni ante otros Estados", "Proponer al Rey la disolución de las Cámaras, plantear la cuestión de confianza ni proponer la convocatoria de un referéndum consultivo"]'::jsonb,3,'Art. 21.4 Ley 50/1997','Además, las delegaciones legislativas otorgadas por las Cortes quedan en suspenso durante todo el tiempo en que el Gobierno esté en funciones (art. 21.6).',null),
('aux-age:5-195690d61c','aux-age',5,'¿Qué forma adoptan las decisiones del Presidente del Gobierno, según el art. 24 de la Ley 50/1997?','["Real Decreto del Presidente del Gobierno", "Real Decreto-ley", "Acuerdo del Consejo de Ministros a propuesta del Presidente", "Orden Ministerial"]'::jsonb,0,'Art. 24.1 b) Ley 50/1997','Las normas de rango reglamentario del Consejo de Ministros adoptan la forma de Real Decreto acordado en Consejo de Ministros.',null),
('aux-age:5-47f16e902d','aux-age',5,'Según el art. 24 de la Ley 50/1997, ¿qué forma adoptan las disposiciones y resoluciones de los Ministros?','["Real Decreto ministerial", "Instrucción", "Resolución ministerial", "Orden Ministerial"]'::jsonb,3,'Art. 24.1 f) Ley 50/1997','Cuando afectan a varios Departamentos, revisten la forma de orden del Ministro de la Presidencia, a propuesta de los Ministros interesados.',null),
('aux-age:5-abbf5acda5','aux-age',5,'Según la Ley 50/1997, los reglamentos se ordenan según la siguiente jerarquía:','["Primero los reales decretos del Consejo de Ministros; después los del Presidente; y, por último, las órdenes", "Primero las disposiciones aprobadas por real decreto del Presidente o del Consejo de Ministros; después las aprobadas por orden ministerial", "Todas tienen el mismo rango, y prevalece la más reciente", "Primero las órdenes ministeriales; después los reales decretos del Presidente"]'::jsonb,1,'Art. 24.2 Ley 50/1997','Ningún reglamento puede vulnerar preceptos de otro de jerarquía superior.',null),
('aux-age:5-346f28d07a','aux-age',5,'Los Ministros, según la Ley 50/1997:','["Son nombrados por el Presidente del Gobierno sin intervención del Rey y responden individualmente ante el Congreso de los Diputados por su gestión al frente del Departamento", "Son los titulares de los Departamentos en que se divide la Administración General del Estado, aunque puede haber Ministros sin cartera", "Son siempre titulares de un Departamento ministerial, sin excepción", "Dependen jerárquicamente del Vicepresidente primero"]'::jsonb,1,'Art. 4 Ley 50/1997','Los Ministros sin cartera tienen atribuida la responsabilidad de determinadas funciones gubernamentales.',null),
('aux-age:5-7eecf10175','aux-age',5,'Los Secretarios de Estado, según la Ley 50/1997:','["Son órganos de apoyo del Presidente sin funciones ejecutivas", "Son órganos superiores de la AGE directamente responsables de la ejecución de la acción del Gobierno en un sector de actividad específica", "Son órganos directivos que dependen de los Subsecretarios", "Son miembros del Gobierno y asisten con voz y voto al Consejo de Ministros"]'::jsonb,1,'Art. 7 Ley 50/1997','Pueden asistir a las reuniones del Consejo de Ministros cuando sean convocados, pero no son miembros del Gobierno.',null),
('aux-age:5-1e52e3f4ff','aux-age',5,'Según el art. 105 CE, la ley regulará:','["La responsabilidad penal de los funcionarios públicos", "La audiencia de los ciudadanos en la elaboración de las disposiciones administrativas, el acceso a los archivos y registros administrativos y el procedimiento de producción de los actos administrativos", "El régimen de los partidos políticos y de los sindicatos", "El estatuto de los miembros del Gobierno"]'::jsonb,1,'Art. 105 CE','Garantizando, cuando proceda, la audiencia del interesado.',null),
('aux-age:5-c96d11be48','aux-age',5,'Según el art. 106.2 CE, los particulares tienen derecho a ser indemnizados por toda lesión que sufran en sus bienes y derechos:','["Solo si la lesión se debe a un funcionamiento anormal de los servicios públicos, y siempre que no concurra fuerza mayor", "Salvo que la lesión se produzca en estado de alarma, excepción o sitio", "Siempre que la lesión se deba a dolo o culpa grave de un funcionario", "Siempre que sea consecuencia del funcionamiento de los servicios públicos, salvo fuerza mayor"]'::jsonb,3,'Art. 106.2 CE','En los términos establecidos por la ley.',null),
('aux-age:5-0708643bab','aux-age',5,'¿Qué ley regula el Gobierno?','["La Ley 6/1997, de 14 de abril", "La Ley 40/2015, de 1 de octubre, de Régimen Jurídico", "La Ley 50/1997, de 27 de noviembre", "La Ley 30/1992, de 26 de noviembre"]'::jsonb,2,'Ley 50/1997','La Ley 40/2015 regula el Régimen Jurídico del Sector Público, y la antigua Ley 6/1997 (LOFAGE) fue derogada por ella.',null),
('aux-age:5-9fb54ccb1f','aux-age',5,'El Gobierno responde solidariamente de su gestión política:','["Ante el Congreso de los Diputados", "Ante el Rey", "Ante el Senado", "Ante las Cortes Generales en sesión conjunta"]'::jsonb,0,'Art. 108 CE','Así lo dispone el art. 108 CE.',null),
('aux-age:6-0e58e1434e','aux-age',6,'¿Cuáles son los pilares o principios que suelen identificarse con el Gobierno abierto?','["Transparencia, eficacia, jerarquía y coordinación", "Publicidad, objetividad, imparcialidad y mérito", "Participación, descentralización, eficiencia y legalidad", "Transparencia, participación, colaboración y rendición de cuentas"]'::jsonb,3,'Gobierno abierto','Son los principios que recogen la Alianza para el Gobierno Abierto y los planes de Gobierno Abierto de España.',null),
('aux-age:6-18c40f58a5','aux-age',6,'¿En qué año se adhirió España a la Alianza para el Gobierno Abierto (Open Government Partnership)?','["2018", "2015", "2011", "2013"]'::jsonb,2,'Alianza para el Gobierno Abierto','La Alianza se lanzó en 2011 y España se incorporó ese mismo año. Desde entonces aprueba planes de acción de Gobierno Abierto.',null),
('aux-age:6-c30a884c0b','aux-age',6,'En el Gobierno abierto, la rendición de cuentas consiste en:','["Que la Administración publique cada año el balance contable consolidado de todos sus organismos y entidades", "Que los responsables públicos expliquen y respondan de sus decisiones y de sus resultados", "Que los ciudadanos presenten cada año cuentas de los servicios públicos que utilizan ante su Ayuntamiento", "Que el Tribunal de Cuentas fiscalice cada año la contabilidad de los partidos políticos y de sus fundaciones"]'::jsonb,1,'Gobierno abierto','Va unida a la transparencia: sin información pública no se pueden pedir cuentas.',null),
('aux-age:6-b26d034f5f','aux-age',6,'La participación, como principio del Gobierno abierto, supone:','["Que las Comunidades Autónomas participen cada año en la elaboración de los Presupuestos Generales del Estado", "Que los ciudadanos voten en referéndum consultivo todas las leyes antes de su aprobación definitiva por las Cortes", "Que los funcionarios participen, a través de sus representantes sindicales, en la negociación colectiva de sus condiciones", "Implicar a la ciudadanía en el diseño, la ejecución y la evaluación de las políticas públicas"]'::jsonb,3,'Gobierno abierto','Instrumentos como la consulta pública previa del art. 133 de la Ley 39/2015 son ejemplos de participación.',null),
('aux-age:6-adcc8632ff','aux-age',6,'¿Qué órgano facilita en España la participación de la sociedad civil en el impulso de los planes de Gobierno abierto?','["El Foro de Gobierno Abierto", "La Comisión General de Codificación", "El Consejo de Transparencia y Buen Gobierno", "El Consejo Económico y Social"]'::jsonb,0,'Foro de Gobierno Abierto','Es un órgano de composición paritaria entre Administraciones y sociedad civil. El Consejo de Transparencia vigila el cumplimiento de la Ley 19/2013, pero no es el foro de participación del Gobierno abierto.',null),
('aux-age:6-df517b8c35','aux-age',6,'¿Qué portal estatal reúne los conjuntos de datos abiertos de las Administraciones públicas españolas?','["sede.gob.es", "datos.gob.es", "transparencia.gob.es", "administracion.gob.es"]'::jsonb,1,'Datos abiertos','El Portal de la Transparencia es transparencia.gob.es y el Punto de Acceso General es administracion.gob.es.',null),
('aux-age:6-5530cd76d5','aux-age',6,'¿Qué ley estatal regula la transparencia de la actividad pública y el derecho de acceso a la información?','["La Ley 19/2013, de 9 de diciembre", "La LO 3/2018, de 5 de diciembre", "La Ley 39/2015, de 1 de octubre", "La Ley 37/2007, de 16 de noviembre"]'::jsonb,0,'Ley 19/2013','La Ley 37/2007 regula la reutilización de la información del sector público y la LO 3/2018, la protección de datos.',null),
('aux-age:6-9a2e5827d7','aux-age',6,'La consulta pública previa a la elaboración de un proyecto normativo, a través del portal web de la Administración competente, es un instrumento de:','["Participación ciudadana en la elaboración de normas", "Rendición de cuentas de los altos cargos ante el Congreso", "Fiscalización económica de la Administración", "Control parlamentario del Gobierno"]'::jsonb,0,'Art. 133.1 Ley 39/2015','Busca la opinión de los sujetos y organizaciones más representativas potencialmente afectados por la futura norma.',null),
('aux-age:6-c3f09a8453','aux-age',6,'¿Qué organismo aprobó la Agenda 2030 para el Desarrollo Sostenible?','["El Consejo de Seguridad de las Naciones Unidas", "La Organización para la Cooperación y el Desarrollo Económicos", "La Asamblea General de las Naciones Unidas", "El Consejo Europeo"]'::jsonb,2,'Agenda 2030','Se aprobó el 25 de septiembre de 2015 con el título «Transformar nuestro mundo: la Agenda 2030 para el Desarrollo Sostenible».',null),
('aux-age:6-dac447bbf2','aux-age',6,'¿En qué año se aprobó la Agenda 2030?','["En 2012", "En 2020", "En 2015", "En 2000"]'::jsonb,2,'Agenda 2030','La aprobó la Asamblea General de Naciones Unidas en septiembre de 2015.',null),
('aux-age:6-4bffe8c610','aux-age',6,'¿Cuántos Objetivos de Desarrollo Sostenible (ODS) recoge la Agenda 2030?','["8", "15", "20", "17"]'::jsonb,3,'Agenda 2030','Los 17 ODS se concretan en 169 metas.',null),
('aux-age:6-6276049ed2','aux-age',6,'¿Cuántas metas concretan los 17 Objetivos de Desarrollo Sostenible?','["120", "100", "175", "169"]'::jsonb,3,'Agenda 2030','Así lo recoge la Agenda 2030.',null),
('aux-age:6-3f4e25abaf','aux-age',6,'¿A qué agenda internacional suceden los Objetivos de Desarrollo Sostenible?','["A la Estrategia Europa 2020 de la Unión Europea", "Al Protocolo de Kioto sobre el cambio climático", "A la Agenda 21 aprobada en la Cumbre de la Tierra de Río", "A los Objetivos de Desarrollo del Milenio"]'::jsonb,3,'Agenda 2030','Los 8 Objetivos de Desarrollo del Milenio tenían como horizonte el año 2015.',null),
('aux-age:6-caf86f054d','aux-age',6,'¿Cuál es el lema o compromiso central de la Agenda 2030?','["Un planeta, una salud", "Crecer para repartir", "No dejar a nadie atrás", "Pensar globalmente, actuar localmente"]'::jsonb,2,'Agenda 2030','La Agenda se compromete a que ninguna persona quede excluida del desarrollo.',null),
('aux-age:6-a528f5ab65','aux-age',6,'Las cinco esferas o «5 P» de la Agenda 2030 son:','["Planeta, población, prosperidad, política y paz", "Personas, planeta, prosperidad, paz y alianzas", "Personas, pobreza, producción, paz y progreso", "Personas, planeta, participación, paz y presupuesto"]'::jsonb,1,'Agenda 2030','En inglés: people, planet, prosperity, peace y partnership.',null),
('aux-age:6-169819652b','aux-age',6,'¿Qué número tiene el ODS «Igualdad de género»?','["ODS 16", "ODS 3", "ODS 10", "ODS 5"]'::jsonb,3,'Agenda 2030','El ODS 10 es «Reducción de las desigualdades», el ODS 3 «Salud y bienestar» y el ODS 16 «Paz, justicia e instituciones sólidas».',null),
('aux-age:6-251146817a','aux-age',6,'El ODS 13 es:','["Ciudades y comunidades sostenibles", "Energía asequible y no contaminante", "Acción por el clima", "Vida submarina"]'::jsonb,2,'Agenda 2030','El ODS 14 es «Vida submarina», el ODS 7 «Energía asequible y no contaminante» y el ODS 11 «Ciudades y comunidades sostenibles».',null),
('aux-age:6-5f93a7ad41','aux-age',6,'¿Qué ODS se dedica a «Paz, justicia e instituciones sólidas»?','["ODS 9", "ODS 17", "ODS 12", "ODS 16"]'::jsonb,3,'Agenda 2030','El ODS 17 es «Alianzas para lograr los objetivos», el 12 «Producción y consumo responsables» y el 9 «Industria, innovación e infraestructura».',null),
('aux-age:6-8a3f291990','aux-age',6,'El ODS 1 es:','["Salud y bienestar", "Educación de calidad", "Fin de la pobreza", "Hambre cero"]'::jsonb,2,'Agenda 2030','El ODS 2 es «Hambre cero», el 3 «Salud y bienestar» y el 4 «Educación de calidad».',null),
('aux-age:6-b83a27d7b7','aux-age',6,'¿Qué ODS se titula «Agua limpia y saneamiento»?','["ODS 14", "ODS 7", "ODS 15", "ODS 6"]'::jsonb,3,'Agenda 2030','El 14 es «Vida submarina», el 7 «Energía asequible y no contaminante» y el 15 «Vida de ecosistemas terrestres».',null),
('aux-age:6-9441a0e104','aux-age',6,'El ODS 8 se refiere a:','["Producción y consumo responsables", "Trabajo decente y crecimiento económico", "Industria, innovación e infraestructura", "Reducción de las desigualdades"]'::jsonb,1,'Agenda 2030','Son, respectivamente, los ODS 9, 10 y 12.',null),
('aux-age:6-edacbd693e','aux-age',6,'El ODS 17 se titula:','["Vida de ecosistemas terrestres", "Paz, justicia e instituciones sólidas", "Alianzas para lograr los objetivos", "Ciudades y comunidades sostenibles"]'::jsonb,2,'Agenda 2030','Es el último de los 17 objetivos.',null),
('aux-age:6-adf2dcd049','aux-age',6,'La Agenda 2030 es, en cuanto a su naturaleza jurídica:','["Un tratado internacional ratificado por las Cortes Generales y, por tanto, de obligado cumplimiento para España", "Una ley orgánica aprobada por las Cortes Generales que obliga a todas las Administraciones públicas", "Un reglamento de la Unión Europea de aplicación directa en todos los Estados miembros desde su publicación", "Un compromiso político no vinculante jurídicamente, cuyo cumplimiento se revisa de forma voluntaria"]'::jsonb,3,'Agenda 2030','Los países presentan informes nacionales voluntarios ante el Foro Político de Alto Nivel de Naciones Unidas.',null),
('aux-age:6-3cc633f1b6','aux-age',6,'¿Ante qué foro presentan los países sus informes nacionales voluntarios sobre la Agenda 2030?','["El Consejo de Seguridad de Naciones Unidas", "El Foro Político de Alto Nivel sobre el Desarrollo Sostenible de Naciones Unidas", "El Comité de las Regiones de la Unión Europea", "El Tribunal Internacional de Justicia"]'::jsonb,1,'Agenda 2030','Es el órgano de Naciones Unidas encargado del seguimiento de la Agenda.',null),
('aux-age:6-58395a9c29','aux-age',6,'¿Qué instrumento aprobó España en 2021 para implementar la Agenda 2030?','["La Estrategia de Desarrollo Sostenible 2030", "El IV Plan de Gobierno Abierto", "El Plan de Recuperación, Transformación y Resiliencia", "La Estrategia Española de Economía Circular"]'::jsonb,0,'Agenda 2030','La Estrategia de Desarrollo Sostenible 2030 es la hoja de ruta de España para cumplir la Agenda.',null),
('aux-age:6-5c2fc20023','aux-age',6,'¿Cuál de estos NO es uno de los Objetivos de Desarrollo Sostenible?','["Industria, innovación e infraestructura", "Paz, justicia e instituciones sólidas", "Seguridad alimentaria y defensa", "Producción y consumo responsables"]'::jsonb,2,'Agenda 2030','Los otros tres son, respectivamente, los ODS 4, 2 y 14.',null),
('aux-age:6-09951b322a','aux-age',6,'La transparencia, como principio del Gobierno abierto, implica:','["Que las deliberaciones del Consejo de Ministros sean públicas", "Que solo los interesados en un procedimiento puedan conocer la información pública", "Que la información pública esté disponible y sea accesible, de forma activa y a petición de los ciudadanos", "Que toda la información en poder de la Administración se publique sin ningún límite"]'::jsonb,2,'Gobierno abierto','Incluye la publicidad activa y el derecho de acceso a la información pública de la Ley 19/2013, con sus límites.',null),
('aux-age:6-a3482f407e','aux-age',6,'La colaboración, como principio del Gobierno abierto, consiste en:','["Que las Comunidades Autónomas colaboren con el Estado en la ejecución de sus leyes", "Trabajar junto con ciudadanos, empresas y organizaciones, y entre Administraciones, para crear valor público", "Que los funcionarios colaboren con la justicia en las investigaciones penales", "Que los ciudadanos colaboren económicamente con el sostenimiento del gasto público"]'::jsonb,1,'Gobierno abierto','La colaboración va más allá de la participación: se trata de coproducir soluciones.',null),
('aux-age:6-bf9eed0095','aux-age',6,'¿Qué ley regula la reutilización de la información del sector público, base de los datos abiertos?','["La Ley 37/2007, de 16 de noviembre", "La LO 3/2018, de 5 de diciembre", "La Ley 19/2013, de 9 de diciembre", "La Ley 40/2015, de 1 de octubre"]'::jsonb,0,'Ley 37/2007','La reutilización permite que ciudadanos y empresas usen la información pública con fines comerciales o no.',null),
('aux-age:6-f5ed4146cc','aux-age',6,'El horizonte temporal de los Objetivos de Desarrollo Sostenible es el año:','["2050", "2030", "2040", "2025"]'::jsonb,1,'Agenda 2030','De ahí el nombre de la Agenda.',null),
('aux-age:7-b0b006e9f2','aux-age',7,'Según el artículo 6 de la Ley 19/2013, los sujetos obligados deben publicar, como información institucional y organizativa:','["Las funciones que desarrollan, la normativa que les sea de aplicación y su estructura organizativa", "Los expedientes de los procedimientos sancionadores que tramiten", "Las retribuciones de todos los empleados públicos, con su nombre y apellidos", "Las actas completas de todas las reuniones de sus órganos colegiados"]'::jsonb,0,'Art. 6.1 Ley 19/2013','Incluyen un organigrama actualizado que identifique a los responsables de los diferentes órganos y su perfil y trayectoria profesional.',null),
('aux-age:7-44c135a0c1','aux-age',7,'Según el artículo 7 de la Ley 19/2013, ¿qué información de relevancia jurídica debe publicarse?','["Los informes de los servicios jurídicos sobre cualquier asunto en tramitación", "Las denuncias presentadas por los ciudadanos contra las autoridades", "Los anteproyectos de ley y los proyectos de reglamento, entre otros documentos", "Las sentencias firmes dictadas contra la Administración en los últimos cinco años"]'::jsonb,2,'Art. 7 Ley 19/2013','También las directrices, instrucciones y circulares que supongan una interpretación del Derecho o tengan efectos jurídicos y las memorias e informes de los expedientes normativos.',null),
('aux-age:7-7fb4936286','aux-age',7,'Según la Ley 19/2013, ¿deben publicarse las retribuciones percibidas anualmente por los altos cargos?','["Sí, como información económica, presupuestaria y estadística", "No, porque son datos personales protegidos", "Solo si lo solicita un ciudadano mediante el derecho de acceso", "Las de los Ministros y Secretarios de Estado, pero no las del resto"]'::jsonb,0,'Art. 8.1 f) Ley 19/2013','También se publican las indemnizaciones percibidas con ocasión del abandono del cargo.',null),
('aux-age:7-1515151c31','aux-age',7,'¿Cuándo entraron en vigor los títulos preliminar, I y III de la Ley 19/2013 para la Administración General del Estado?','["A los dos años de su publicación en el Boletín Oficial del Estado", "A los seis meses de su publicación en el Boletín Oficial del Estado", "Al año de su publicación en el Boletín Oficial del Estado", "Al día siguiente de su publicación en el Boletín Oficial del Estado"]'::jsonb,2,'Disposición final novena Ley 19/2013','El título II (buen gobierno) entró en vigor al día siguiente de su publicación. Las CCAA y Entidades Locales tuvieron dos años para adaptarse.',null),
('aux-age:7-758dd90de9','aux-age',7,'El título II de la Ley 19/2013 regula:','["El buen gobierno", "La publicidad activa", "El derecho de acceso a la información pública", "El Consejo de Transparencia y Buen Gobierno"]'::jsonb,0,'Ley 19/2013','El título I regula la transparencia (publicidad activa y derecho de acceso) y el título III el Consejo de Transparencia y Buen Gobierno.',null),
('aux-age:7-d9711eb779','aux-age',7,'Cuando un límite al derecho de acceso no afecte a la totalidad de la información solicitada:','["Se deniega el acceso a la totalidad de la información, aunque el límite afecte solo a una parte de ella, para evitar que se conozca el resto", "Se remite la solicitud al Consejo de Transparencia y Buen Gobierno", "Se suspende el procedimiento hasta que el límite deje de aplicarse y se notifica esta circunstancia al solicitante y a los terceros afectados", "Se concede el acceso parcial, omitiendo la información afectada por el límite, salvo que resulte una información distorsionada o sin sentido"]'::jsonb,3,'Art. 16 Ley 19/2013','Debe indicarse al solicitante qué parte de la información ha sido omitida.',null),
('aux-age:7-3852827e4e','aux-age',7,'Según la Ley 19/2013, la solicitud de acceso que se refiera a información cuya divulgación requiera una acción previa de reelaboración:','["Se inadmitirá a trámite mediante resolución motivada", "Se remitirá al órgano que elaboró la información originalmente", "Se tramitará con un plazo ampliado de tres meses", "Se estimará, pero el solicitante deberá abonar el coste de la reelaboración"]'::jsonb,0,'Art. 18.1 c) Ley 19/2013','Es una de las causas de inadmisión, junto con la información en curso de elaboración o de carácter auxiliar, entre otras.',null),
('aux-age:7-885b2e0b43','aux-age',7,'Si la solicitud de acceso se refiere a información que no obre en poder del sujeto al que se dirige:','["Este la archivará y el solicitante deberá presentar una nueva solicitud ante el órgano que corresponda", "Este deberá recabar la información del órgano que la posea y resolver la solicitud en el plazo ordinario", "Este la remitirá al competente, si lo conoce, e informará de esta circunstancia al solicitante", "Este la inadmitirá a trámite, aunque conozca cuál es el órgano o entidad competente para resolver"]'::jsonb,2,'Art. 19.1 Ley 19/2013','Si desconoce el órgano competente, procede la inadmisión.',null),
('aux-age:7-5431ed0dd2','aux-age',7,'El plazo para resolver una solicitud de acceso a la información puede ampliarse:','["Por tres meses más, sin necesidad de comunicarlo previamente al solicitante, cuando así lo acuerde el titular del órgano que debe resolver", "No puede ampliarse, porque es un plazo improrrogable", "Por otro mes, en el caso de que el volumen o la complejidad de la información lo hagan necesario, previa notificación al solicitante", "Por quince días hábiles, solo si hay terceros afectados"]'::jsonb,2,'Art. 20.1 Ley 19/2013','El plazo ordinario es de un mes desde la recepción de la solicitud por el órgano competente.',null),
('aux-age:7-8b81efc48d','aux-age',7,'Según la Ley 19/2013, ¿qué resoluciones sobre el derecho de acceso deben ser motivadas?','["Las que denieguen totalmente el acceso a la información", "Todas las resoluciones, tanto si conceden como si deniegan el acceso", "Las que denieguen el acceso, las que concedan el acceso parcial o a través de una modalidad distinta a la solicitada y las que permitan el acceso con oposición de un tercero", "Las que concedan el acceso, porque afectan a la confidencialidad de la información"]'::jsonb,2,'Art. 20.2 Ley 19/2013','Así lo exige el artículo 20.2.',null),
('aux-age:7-6e4d331227','aux-age',7,'El acceso a la información pública, según la Ley 19/2013:','["Es gratuito, aunque la expedición de copias o la transposición a formatos diferentes del original puede dar lugar a exacciones", "Es gratuito solo para los ciudadanos españoles residentes en España", "Está sujeto al pago de una tasa por cada solicitud presentada, cuya cuantía fija cada año la Ley de Presupuestos Generales del Estado", "Es gratuito, incluida también la expedición de copias en papel o en soporte electrónico y la transposición a otros formatos"]'::jsonb,0,'Art. 22.4 Ley 19/2013','La forma preferente de acceso es la electrónica.',null),
('aux-age:7-a8f5ee8398','aux-age',7,'¿Qué unidades deben existir en la Administración General del Estado para facilitar el conocimiento y acceso a la información pública?','["Delegaciones de protección de datos", "Unidades de información", "Oficinas de asistencia en materia de registros", "Inspecciones generales de servicios"]'::jsonb,1,'Art. 21 Ley 19/2013','Se encargan, entre otras funciones, de recabar y difundir la información de publicidad activa y de recibir y tramitar las solicitudes de acceso.',null),
('aux-age:7-37d401ae56','aux-age',7,'Según la Ley 19/2013, la información de publicidad activa se publicará:','["De forma periódica y actualizada, en las sedes electrónicas o páginas web, de una manera clara, estructurada y entendible y preferiblemente en formatos reutilizables", "Cuando lo solicite cualquier ciudadano por escrito", "Una vez al año, en el Boletín Oficial del Estado y en los diarios oficiales de las Comunidades Autónomas, en un anexo específico que recoja toda la información obligatoria", "En el tablón de anuncios físico de cada órgano"]'::jsonb,0,'Arts. 5.1 y 5.4 Ley 19/2013','Se establecen los mecanismos adecuados para facilitar la accesibilidad, la interoperabilidad y la calidad de la información.',null),
('aux-age:7-fd7adb176d','aux-age',7,'Según el artículo 26 de la Ley 19/2013, ¿cuál de los siguientes es un principio general de actuación de los altos cargos?','["Mantener en secreto todas sus reuniones con grupos de interés", "Actuar con transparencia en la gestión de los asuntos públicos", "Afiliarse obligatoriamente a un partido político", "Percibir una retribución acorde con la de su sector privado de origen"]'::jsonb,1,'Art. 26.2 a) Ley 19/2013','Otros principios son la dedicación al servicio público, la imparcialidad, la igualdad de trato y la diligencia.',null),
('aux-age:8-4ed639cf12','aux-age',8,'Según la Ley 40/2015, son órganos superiores de la Administración General del Estado:','["Los Ministros y los Subsecretarios", "Los Secretarios de Estado y los Secretarios generales", "Los Ministros, los Secretarios de Estado y los Directores generales", "Los Ministros y los Secretarios de Estado"]'::jsonb,3,'Art. 55.3 Ley 40/2015','Los demás órganos de la organización central son órganos directivos.',null),
('aux-age:8-bb20082971','aux-age',8,'¿Cuál de los siguientes es un órgano directivo de la organización central de la AGE?','["El Subdirector general", "El Ministro", "El Secretario de Estado", "El Delegado del Gobierno en la Comunidad Autónoma"]'::jsonb,0,'Art. 55.3 Ley 40/2015','Son órganos directivos los Subsecretarios y Secretarios generales, los Secretarios generales técnicos y Directores generales, y los Subdirectores generales. Los Delegados del Gobierno son órganos directivos, pero de la organización territorial.',null),
('aux-age:8-78cc4d752f','aux-age',8,'En la organización territorial de la AGE, son órganos directivos:','["Los Delegados del Gobierno, los Presidentes de las Diputaciones y los Subdelegados", "Los Delegados del Gobierno en las Comunidades Autónomas y los Subdelegados del Gobierno en las provincias", "Los Delegados del Gobierno y los Directores generales de los servicios periféricos", "Los Subdelegados del Gobierno y los Alcaldes de los municipios de más de 50.000 habitantes"]'::jsonb,1,'Art. 55.4 Ley 40/2015','Los Delegados tienen rango de Subsecretario y los Subdelegados nivel de Subdirector general.',null),
('aux-age:8-22c7ebdc30','aux-age',8,'En la Administración General del Estado en el exterior son órganos directivos:','["Los Embajadores y los Representantes permanentes ante organizaciones internacionales", "Los Cónsules generales y los Agregados sectoriales de los distintos Ministerios en el exterior", "Los Embajadores y los Cónsules honorarios", "Los Consejeros de Embajada y los Encargados de negocios"]'::jsonb,0,'Art. 55.5 Ley 40/2015','Así lo establece la Ley 40/2015 para la Administración General del Estado en el exterior.',null),
('aux-age:8-a42e0508d5','aux-age',8,'¿Qué rango tienen los Delegados del Gobierno en las Comunidades Autónomas?','["Rango de Secretario de Estado", "Nivel de Subdirector general", "Rango de Director general", "Rango de Subsecretario"]'::jsonb,3,'Arts. 55.4 y 72.3 Ley 40/2015','Los Subdelegados del Gobierno en las provincias tienen nivel de Subdirector general.',null),
('aux-age:8-08a1965953','aux-age',8,'Los Subdelegados del Gobierno en las provincias tienen:','["Rango de Secretario general técnico", "Nivel de Subdirector general", "Rango de Director general", "Rango de Subsecretario"]'::jsonb,1,'Arts. 55.4 y 74 Ley 40/2015','Los Delegados del Gobierno, en cambio, tienen rango de Subsecretario.',null),
('aux-age:8-977cfd84ef','aux-age',8,'Los Secretarios generales técnicos tienen categoría de:','["Subdirector general", "Subsecretario", "Director general", "Secretario de Estado"]'::jsonb,2,'Art. 65.1 Ley 40/2015','Los Secretarios generales, en cambio, tienen categoría de Subsecretario.',null),
('aux-age:8-cf3ccd5be3','aux-age',8,'Los Secretarios generales de los Ministerios tienen categoría de:','["Director general", "Subdirector general", "Subsecretario", "Secretario de Estado"]'::jsonb,2,'Art. 64.1 Ley 40/2015','Los Secretarios generales técnicos tienen categoría de Director general.',null),
('aux-age:8-039103b3fb','aux-age',8,'¿Cómo se nombran los Subsecretarios?','["Por real decreto del Consejo de Ministros, a propuesta del titular del Ministerio", "Por real decreto del Presidente del Gobierno, a propuesta del Ministro de Hacienda", "Por orden del Ministro del departamento, entre funcionarios del subgrupo A1", "Por acuerdo de la Comisión General de Secretarios de Estado y Subsecretarios"]'::jsonb,0,'Art. 63.3 Ley 40/2015','Se eligen entre funcionarios de carrera del Estado, de las CCAA o de las Entidades Locales del subgrupo A1.',null),
('aux-age:8-77e7b7db9b','aux-age',8,'Los Subdirectores generales son nombrados y cesados:','["Por real decreto del Consejo de Ministros, a propuesta del Ministro del departamento", "Por el Ministro, el Secretario de Estado o el Subsecretario del que dependan", "Por el Director general del que dependan, entre personal laboral fijo", "Por el Delegado del Gobierno, a propuesta del Director general del que dependan"]'::jsonb,1,'Art. 67.2 Ley 40/2015','Se nombran atendiendo a los principios de igualdad, mérito y capacidad, entre funcionarios de carrera del subgrupo A1.',null),
('aux-age:8-cc29209345','aux-age',8,'¿Entre quiénes se nombra con carácter general a los Directores generales?','["Solo entre funcionarios de carrera de la Administración General del Estado del subgrupo A2", "Entre cualquier persona mayor de edad con nacionalidad española, sin otros requisitos", "Entre funcionarios de carrera del subgrupo A1, salvo excepción motivada en el real decreto de estructura", "Entre altos cargos que hayan sido antes Subdirectores generales durante dos años"]'::jsonb,2,'Art. 66.2 Ley 40/2015','Se nombran y cesan por real decreto del Consejo de Ministros. El real decreto de estructura puede permitir, motivadamente, que el titular no sea funcionario.',null),
('aux-age:8-67651fe4cc','aux-age',8,'A diferencia de los Subsecretarios, los Secretarios generales:','["Tienen categoría de Secretario de Estado", "Son nombrados por el Ministro mediante orden ministerial", "Pueden nombrarse entre personas con cualificación y experiencia, sin ser necesariamente funcionarios", "Deben ser siempre funcionarios de carrera del subgrupo A1 con diez años de servicio"]'::jsonb,2,'Art. 64 Ley 40/2015','Se nombran por real decreto del Consejo de Ministros a propuesta del Ministro, atendiendo a criterios de competencia profesional y experiencia.',null),
('aux-age:8-3447da444b','aux-age',8,'¿A quién corresponde la representación ordinaria del Ministerio?','["Al Ministro", "Al Subsecretario", "Al Secretario general técnico", "Al Secretario de Estado"]'::jsonb,1,'Art. 63.1 a) Ley 40/2015','El Subsecretario ostenta la representación ordinaria del Ministerio y dirige sus servicios comunes.',null),
('aux-age:8-ce553dc538','aux-age',8,'La Secretaría General Técnica depende, dentro de cada Ministerio:','["De la Subsecretaría", "Directamente del Ministro", "De la Secretaría de Estado", "De la Dirección General de Servicios"]'::jsonb,0,'Art. 58 Ley 40/2015','En todo Ministerio existe una Subsecretaría y, dependiendo de ella, una Secretaría General Técnica.',null),
('aux-age:8-1052f2cf46','aux-age',8,'¿Cómo se crean, modifican y suprimen los Ministerios?','["Por ley de las Cortes Generales", "Por real decreto del Consejo de Ministros, a propuesta del Ministro de Hacienda", "Por real decreto del Presidente del Gobierno", "Por orden del Ministro de la Presidencia"]'::jsonb,2,'Art. 2.2 j) Ley 50/1997','Corresponde al Presidente del Gobierno crear, modificar y suprimir por real decreto los Departamentos ministeriales y las Secretarías de Estado.',null),
('aux-age:8-3bc785da61','aux-age',8,'La estructura orgánica básica de cada Ministerio se establece:','["Por resolución del Subsecretario del Ministerio", "Por orden del Ministro del departamento", "Por real decreto del Consejo de Ministros", "Por real decreto del Presidente del Gobierno"]'::jsonb,2,'Art. 59.1 Ley 40/2015','Se aprueba a iniciativa del Ministro interesado y a propuesta del Ministro competente en materia de organización administrativa.',null),
('aux-age:8-6ffcbde562','aux-age',8,'Los órganos de nivel inferior a Subdirección General se crean, modifican y suprimen:','["Por real decreto del Presidente del Gobierno, previo informe del Consejo de Estado", "Por resolución del Subsecretario, sin necesidad de aprobación previa", "Por real decreto del Consejo de Ministros, a propuesta del Ministro respectivo", "Por orden del Ministro respectivo, previa aprobación del Ministro competente en materia de organización"]'::jsonb,3,'Art. 59.2 Ley 40/2015','Las Subdirecciones Generales y órganos superiores se crean por real decreto.',null),
('aux-age:8-7c6f9c4435','aux-age',8,'¿Cómo se nombran los Delegados del Gobierno en las Comunidades Autónomas?','["Por orden del Ministro del Interior, oído el Gobierno autonómico", "Por real decreto del Consejo de Ministros, a propuesta del Presidente del Gobierno", "Por elección de la Asamblea Legislativa de la Comunidad Autónoma", "Por real decreto del Consejo de Ministros, a propuesta del Presidente de la Comunidad Autónoma"]'::jsonb,1,'Art. 72.4 Ley 40/2015','Dependen orgánicamente de la Presidencia del Gobierno y tienen rango de Subsecretario.',null),
('aux-age:8-f42e26d67a','aux-age',8,'¿Quién nombra a los Subdelegados del Gobierno en las provincias?','["El Presidente de la Diputación Provincial, oído previamente el Delegado del Gobierno", "El Consejo de Ministros, por real decreto, a propuesta del Ministro del Interior", "El Ministro competente en política territorial, por concurso de méritos entre funcionarios", "El Delegado del Gobierno, por libre designación entre funcionarios de carrera"]'::jsonb,3,'Art. 74 Ley 40/2015','Se nombran entre funcionarios de carrera del Estado, de las CCAA o de las Entidades Locales del subgrupo A1.',null),
('aux-age:8-37adc08ee4','aux-age',8,'En las Comunidades Autónomas uniprovinciales:','["Existe un Subdelegado del Gobierno con rango de Subsecretario, nombrado por el Consejo de Ministros", "No existe Subdelegado del Gobierno y el Delegado asume sus competencias", "El Subdelegado asume las funciones del Delegado del Gobierno", "Hay siempre un Subdelegado y un Director insular"]'::jsonb,1,'Art. 74 Ley 40/2015','En las Comunidades Autónomas uniprovinciales el Delegado del Gobierno asume las competencias de los Subdelegados.',null),
('aux-age:8-c750e1c1e6','aux-age',8,'¿En qué ámbito se nombran Directores Insulares de la Administración General del Estado?','["En las ciudades de Ceuta y Melilla, por el Ministro de Hacienda, oído el Delegado del Gobierno", "En cada isla, por elección del Cabildo o Consejo insular entre sus propios miembros", "En todas las islas de Baleares y Canarias, por el Consejo de Ministros a propuesta del Delegado", "En las islas que lo determine la normativa, por el Delegado del Gobierno"]'::jsonb,3,'Art. 70 Ley 40/2015','Se nombran por el Delegado del Gobierno por libre designación entre funcionarios de carrera.',null),
('aux-age:8-f2210d3719','aux-age',8,'¿Qué órgano colegiado asiste al Delegado del Gobierno en cada Comunidad Autónoma?','["La Comisión General de Secretarios de Estado y Subsecretarios del Gobierno", "La Comisión Bilateral de Cooperación entre el Estado y la Comunidad Autónoma", "La Conferencia de Presidentes", "La Comisión territorial de asistencia al Delegado del Gobierno"]'::jsonb,3,'Art. 79 Ley 40/2015','En las Comunidades pluriprovinciales la preside el Delegado del Gobierno y la integran los Subdelegados.',null),
('aux-age:8-7789b87068','aux-age',8,'Corresponde a los Delegados del Gobierno, entre otras funciones:','["Proteger el libre ejercicio de los derechos y libertades y garantizar la seguridad ciudadana", "Nombrar a los Alcaldes de los municipios de su Comunidad Autónoma", "Dictar reglamentos ejecutivos de las leyes estatales en su territorio", "Aprobar los presupuestos de los servicios periféricos de todos los Ministerios"]'::jsonb,0,'Art. 73.3 Ley 40/2015','Lo hacen a través de los Subdelegados y de las Fuerzas y Cuerpos de Seguridad del Estado, cuya jefatura les corresponde.',null),
('aux-age:8-39b123a3a0','aux-age',8,'La Administración General del Estado actúa con personalidad jurídica:','["Múltiple, una por cada Ministerio", "Doble, central y periférica", "Propia de cada órgano superior", "Única"]'::jsonb,3,'Art. 3.4 Ley 40/2015','Cada una de las Administraciones Públicas actúa para el cumplimiento de sus fines con personalidad jurídica única.',null),
('aux-age:8-e9b43d786e','aux-age',8,'¿Qué es un Ministerio, según la Ley 40/2015?','["Una entidad de derecho privado adscrita a la Presidencia del Gobierno", "Un Departamento que comprende uno o varios sectores funcionalmente homogéneos de actividad administrativa", "Un órgano colegiado del Gobierno integrado por los Secretarios de Estado", "Un organismo público con personalidad jurídica propia y autonomía de gestión"]'::jsonb,1,'Art. 57.1 Ley 40/2015','La Administración General del Estado se organiza en Presidencia del Gobierno y en Ministerios.',null),
('aux-age:8-9e1299f606','aux-age',8,'Los Secretarios de Estado son directamente responsables, bajo la dirección del Ministro:','["De la representación ordinaria del Ministerio y de la jefatura de su personal", "De la ejecución de la acción del Gobierno en un sector de actividad específica del Departamento", "De la asistencia jurídica y de las publicaciones del Ministerio", "De la gestión de una Subdirección General concreta"]'::jsonb,1,'Art. 62.1 Ley 40/2015','La representación ordinaria corresponde al Subsecretario y la asistencia jurídica y publicaciones a la Secretaría General Técnica.',null),
('aux-age:8-bdf820a3b9','aux-age',8,'La producción normativa, la asistencia jurídica y las publicaciones de un Ministerio corresponden a:','["La Subsecretaría", "La Secretaría de Estado", "La Abogacía General del Estado", "La Secretaría General Técnica"]'::jsonb,3,'Art. 65.1 Ley 40/2015','El Secretario general técnico tiene categoría de Director general.',null),
('aux-age:8-3658d9d94a','aux-age',8,'¿Qué ley regula la Acción y el Servicio Exterior del Estado?','["La Ley 2/2014, de 25 de marzo", "La Ley 25/2014, de 27 de noviembre", "La Ley 50/1997, de 27 de noviembre", "La Ley 40/2015, de 1 de octubre"]'::jsonb,0,'Ley 2/2014','La Ley 25/2014 regula los Tratados y otros Acuerdos Internacionales y la Ley 50/1997, el Gobierno.',null),
('aux-age:8-aadb5f6ab6','aux-age',8,'Los Embajadores, como Jefes de Misión diplomática, se nombran:','["Por real decreto del Presidente del Gobierno, oído el Consejo de Estado", "Por real decreto acordado en Consejo de Ministros, a propuesta del Ministro de Asuntos Exteriores", "Por el Rey, a propuesta del Congreso de los Diputados", "Por orden del Ministro de Asuntos Exteriores, entre funcionarios de la carrera diplomática"]'::jsonb,1,'Ley 2/2014','Las Cortes no intervienen en su nombramiento.',null),
('aux-age:8-1fc028de21','aux-age',8,'¿Quién tiene la condición de alto cargo según la Ley 40/2015?','["Los órganos superiores y directivos, salvo los Subdirectores generales y asimilados", "Todos los funcionarios de carrera del subgrupo A1 que presten servicio en la Administración General del Estado", "Solo los Ministros y los Secretarios de Estado, como órganos superiores de la Administración", "Todos los órganos directivos, incluidos los Subdirectores generales y los asimilados a ellos"]'::jsonb,0,'Art. 55.6 Ley 40/2015','Los Subdirectores generales y asimilados no tienen la consideración de alto cargo.',null),
('aux-age:9-131cfdaed7','aux-age',9,'Según el artículo 137 de la Constitución, el Estado se organiza territorialmente en:','["Provincias, Comunidades Autónomas y Ciudades Autónomas", "Municipios, islas y Comunidades Autónomas", "Municipios, provincias y Comunidades Autónomas", "Municipios, comarcas, provincias y regiones"]'::jsonb,2,'Art. 137 CE','Todas estas entidades gozan de autonomía para la gestión de sus respectivos intereses.',null),
('aux-age:9-812598e178','aux-age',9,'Según la Constitución, el gobierno y la administración de los municipios corresponde a:','["Las Diputaciones Provinciales, a través de sus delegaciones comarcales en cada municipio", "Los Delegados del Gobierno, con la colaboración de los Concejales elegidos por los vecinos", "Las asambleas vecinales abiertas, presididas por el Alcalde y el Secretario municipal", "Sus respectivos Ayuntamientos, integrados por los Alcaldes y los Concejales"]'::jsonb,3,'Art. 140 CE','Los Concejales son elegidos por los vecinos por sufragio universal, igual, libre, directo y secreto.',null),
('aux-age:9-cc4f489e38','aux-age',9,'Según el artículo 140 de la Constitución, los Alcaldes serán elegidos:','["Por el Delegado del Gobierno, a propuesta de los Concejales", "Por el Pleno de la Diputación Provincial", "Por los Concejales o por los vecinos", "Siempre por sufragio universal directo de los vecinos"]'::jsonb,2,'Art. 140 CE','La ley regula las condiciones en las que procede el régimen del concejo abierto.',null),
('aux-age:9-b09daa01a3','aux-age',9,'¿Qué tipo de ley es necesaria para alterar los límites provinciales?','["Una ley orgánica aprobada por las Cortes Generales", "Un real decreto del Consejo de Ministros", "Una ley ordinaria de las Cortes Generales, por mayoría absoluta", "Una ley de la Comunidad Autónoma afectada, previo informe estatal"]'::jsonb,0,'Art. 141.1 CE','La provincia es una entidad local con personalidad jurídica propia, agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado.',null),
('aux-age:9-dd2e7c73d9','aux-age',9,'En los archipiélagos, las islas tendrán además su administración propia en forma de:','["Diputaciones forales", "Cabildos o Consejos", "Juntas Generales", "Mancomunidades insulares"]'::jsonb,1,'Art. 141.4 CE','Los Cabildos existen en Canarias y los Consejos Insulares en Baleares.',null),
('aux-age:9-4c2442c896','aux-age',9,'Según el artículo 143.2 de la Constitución, la iniciativa del proceso autonómico corresponde a todas las Diputaciones interesadas o al órgano interinsular correspondiente y a:','["Los municipios que representen un tercio del censo electoral de la región histórica", "Las tres cuartas partes de los municipios que representen la mayoría absoluta de los electores", "La mitad de los municipios de cada provincia, sea cual sea su población", "Las dos terceras partes de los municipios cuya población represente, al menos, la mayoría del censo electoral de cada provincia o isla"]'::jsonb,3,'Art. 143.2 CE','Los requisitos deben cumplirse en el plazo de seis meses desde el primer acuerdo de una Corporación local.',null),
('aux-age:9-d851033b20','aux-age',9,'¿En qué plazo deben cumplirse los requisitos de iniciativa autonómica del artículo 143.2 de la Constitución?','["Dos años desde que se constituya la asamblea de parlamentarios", "Seis meses desde el primer acuerdo adoptado por alguna de las Corporaciones locales interesadas", "Tres meses desde el acuerdo de la última de las Diputaciones interesadas", "Un año desde la publicación de la Constitución en el Boletín Oficial del Estado y en los diarios oficiales"]'::jsonb,1,'Art. 143.2 CE','Si la iniciativa no prospera, solo puede reiterarse pasados cinco años.',null),
('aux-age:9-0de8bc0ccc','aux-age',9,'Si la iniciativa autonómica del artículo 143 no prospera:','["Podrá reiterarse pasados tres años", "Solo podrá reiterarse pasados cinco años", "Podrá reiterarse al año siguiente", "No podrá volver a plantearse nunca"]'::jsonb,1,'Art. 143.3 CE','Así lo dispone el artículo 143.3 de la Constitución.',null),
('aux-age:9-77a273986b','aux-age',9,'Según el artículo 144 de la Constitución, las Cortes Generales, mediante ley orgánica y por motivos de interés nacional, podrán:','["Integrar dos Comunidades Autónomas limítrofes en una sola, sin necesidad de referéndum", "Disolver una Comunidad Autónoma que incumpla de forma grave las obligaciones que le imponen la Constitución u otras leyes", "Suspender la autonomía de una Comunidad Autónoma por un plazo máximo de seis meses", "Autorizar la constitución de una Comunidad Autónoma cuyo ámbito territorial no supere el de una provincia y no reúna las condiciones del artículo 143.1"]'::jsonb,3,'Art. 144 a) CE','El artículo 155 no permite disolver Comunidades, sino adoptar medidas para obligarlas a cumplir.',null),
('aux-age:9-ce475b811d','aux-age',9,'¿Qué prohíbe el artículo 145 de la Constitución?','["Que una Comunidad Autónoma tenga varias provincias", "La federación de Comunidades Autónomas", "Los convenios entre Comunidades Autónomas", "Que las Comunidades Autónomas tengan himno propio"]'::jsonb,1,'Art. 145.1 CE','Sí se permiten convenios entre Comunidades para la gestión de servicios propios, que deben comunicarse a las Cortes Generales.',null),
('aux-age:9-b493e1b74f','aux-age',9,'Los acuerdos de cooperación entre Comunidades Autónomas, distintos de los convenios para gestión de servicios propios, requieren:','["El dictamen del Consejo de Estado", "La aprobación del Consejo de Ministros", "La autorización de las Cortes Generales", "Una simple comunicación a las Cortes Generales"]'::jsonb,2,'Art. 145.2 CE','Los convenios para la gestión y prestación de servicios propios solo deben comunicarse a las Cortes.',null),
('aux-age:9-225fa75543','aux-age',9,'Según el artículo 147 de la Constitución, el Estatuto de Autonomía es:','["Un tratado entre el Estado y la Comunidad Autónoma", "Un reglamento del Gobierno de la Nación para cada Comunidad", "La norma institucional básica de cada Comunidad Autónoma", "Una ley ordinaria aprobada por el Parlamento autonómico"]'::jsonb,2,'Art. 147.1 CE','El Estado lo reconoce y ampara como parte integrante de su ordenamiento jurídico.',null),
('aux-age:9-abe77c8798','aux-age',9,'¿Cuál de los siguientes contenidos NO exige la Constitución que figure en los Estatutos de Autonomía?','["La delimitación de su territorio", "La denominación de la Comunidad", "La lengua cooficial de la Comunidad", "Las competencias asumidas"]'::jsonb,2,'Art. 147.2 CE','El art. 147.2 exige denominación, delimitación del territorio, denominación, organización y sede de las instituciones propias y competencias asumidas.',null),
('aux-age:9-966685b2c9','aux-age',9,'La reforma de los Estatutos de Autonomía requiere, en todo caso:','["Un referéndum en todo el territorio nacional", "La aprobación por las Cortes Generales mediante ley orgánica", "El acuerdo del Senado por mayoría de tres quintos", "La aprobación por el Gobierno de la Nación mediante real decreto"]'::jsonb,1,'Art. 147.3 CE','El procedimiento lo fija cada Estatuto.',null),
('aux-age:9-7b14ed5a4b','aux-age',9,'Según el artículo 148.2 de la Constitución, las Comunidades Autónomas podían ampliar sucesivamente sus competencias transcurridos:','["Diez años", "Dos años", "Tres años", "Cinco años"]'::jsonb,3,'Art. 148.2 CE','Mediante la reforma de sus Estatutos, dentro del marco del artículo 149.',null),
('aux-age:9-477c215771','aux-age',9,'Las materias no atribuidas expresamente al Estado por la Constitución podrán corresponder a las Comunidades Autónomas:','["Por acuerdo de la Conferencia de Presidentes", "Solo mediante ley de transferencia", "En virtud de sus respectivos Estatutos", "Siempre, de forma automática"]'::jsonb,2,'Art. 149.3 CE','Las no asumidas por los Estatutos corresponden al Estado, cuyo derecho es en todo caso supletorio del de las Comunidades Autónomas.',null),
('aux-age:9-62c4765d9f','aux-age',9,'En caso de conflicto, las normas del Estado prevalecen sobre las de las Comunidades Autónomas:','["En todo lo que no esté atribuido a la exclusiva competencia de estas", "Solo en materia de relaciones internacionales", "Solo si la norma estatal es posterior", "En todo caso, sin excepción alguna"]'::jsonb,0,'Art. 149.3 CE','Es la cláusula de prevalencia del derecho estatal.',null),
('aux-age:9-c31f0a9d86','aux-age',9,'¿Qué leyes permiten a las Cortes atribuir a las Comunidades Autónomas la facultad de dictar normas legislativas en el marco de principios, bases y directrices fijados por una ley estatal?','["Las leyes de bases", "Las leyes marco", "Las leyes de armonización", "Las leyes orgánicas de transferencia"]'::jsonb,1,'Art. 150.1 CE','Las leyes de bases sirven para delegar en el Gobierno la elaboración de textos articulados.',null),
('aux-age:9-1c5c6ef223','aux-age',9,'La transferencia o delegación a las Comunidades Autónomas de facultades de titularidad estatal se hace mediante:','["Ley ordinaria", "Real decreto legislativo", "Ley orgánica", "Ley marco"]'::jsonb,2,'Art. 150.2 CE','Debe prever la correspondiente transferencia de medios financieros y las formas de control que se reserve el Estado.',null),
('aux-age:9-cdafc7e489','aux-age',9,'¿Quién aprecia la necesidad de dictar una ley de armonización?','["El Senado, por mayoría de dos tercios, a propuesta de la Comisión General de las CCAA", "El Tribunal Constitucional, a instancia del Gobierno o de cincuenta diputados", "Las Cortes Generales, por mayoría absoluta de cada Cámara", "El Gobierno de la Nación, previo dictamen favorable del Consejo de Estado"]'::jsonb,2,'Art. 150.3 CE','Lo exige el interés general, aunque se trate de materias atribuidas a la competencia de las Comunidades Autónomas.',null),
('aux-age:9-08885418c9','aux-age',9,'En la vía del artículo 151 de la Constitución, la iniciativa autonómica debía ratificarse mediante referéndum por:','["La mayoría absoluta de los votos válidos emitidos en el conjunto de toda España", "El voto afirmativo de la mayoría absoluta de los electores de cada provincia", "La mayoría simple de los votos emitidos en el conjunto del territorio de la futura Comunidad", "Dos tercios de los votantes de cada provincia"]'::jsonb,1,'Art. 151.1 CE','Además, la iniciativa debía acordarse por las Diputaciones y por las tres cuartas partes de los municipios de cada provincia.',null),
('aux-age:9-5afd774e6a','aux-age',9,'Según el artículo 152 de la Constitución, el Presidente de la Comunidad Autónoma es:','["Elegido por el Senado entre los senadores de la Comunidad", "Elegido directamente por los ciudadanos de la Comunidad en las elecciones autonómicas y nombrado por el Rey", "Nombrado por el Presidente del Gobierno, a propuesta de la Asamblea", "Elegido por la Asamblea Legislativa de entre sus miembros y nombrado por el Rey"]'::jsonb,3,'Art. 152.1 CE','Dirige el Consejo de Gobierno y ostenta la suprema representación de la Comunidad y la ordinaria del Estado en ella.',null),
('aux-age:9-9c4f1117f3','aux-age',9,'El control económico y presupuestario de los órganos de las Comunidades Autónomas corresponde, según el artículo 153 de la Constitución, a:','["La jurisdicción contencioso-administrativa", "El Tribunal de Cuentas", "El Ministerio de Hacienda", "El Tribunal Constitucional"]'::jsonb,1,'Art. 153 d) CE','El TC controla las disposiciones con fuerza de ley y la jurisdicción contencioso-administrativa, la administración autónoma y sus reglamentos.',null),
('aux-age:9-95c155f0c3','aux-age',9,'¿Quién controla las funciones delegadas a las Comunidades Autónomas conforme al artículo 150.2 de la Constitución?','["El Tribunal de Cuentas, previo informe de la Intervención General", "El Tribunal Constitucional, previo recurso del Senado", "Los Tribunales Superiores de Justicia", "El Gobierno, previo dictamen del Consejo de Estado"]'::jsonb,3,'Art. 153 b) CE','Es una de las cuatro vías de control de la actividad autonómica que enumera el artículo 153.',null),
('aux-age:9-376bba21e9','aux-age',9,'Para aplicar las medidas del artículo 155 de la Constitución, el Gobierno necesita:','["Requerir previamente al Presidente de la Comunidad Autónoma y la aprobación de la mayoría absoluta del Senado", "La aprobación del Consejo de Estado y del Congreso", "La autorización del Congreso de los Diputados por mayoría de tres quintos", "Un dictamen favorable del Tribunal Constitucional"]'::jsonb,0,'Art. 155.1 CE','Se aplica si una Comunidad no cumple las obligaciones de la Constitución o las leyes o actúa contra el interés general de España.',null),
('aux-age:9-990f8f830e','aux-age',9,'¿Qué fondo prevé el artículo 158.2 de la Constitución para corregir desequilibrios económicos interterritoriales?','["El Fondo de Suficiencia Global", "El Fondo de Compensación", "El Fondo de Garantía de Servicios Públicos Fundamentales", "El Fondo de Cohesión Territorial"]'::jsonb,1,'Art. 158.2 CE','Sus recursos se distribuyen por las Cortes Generales entre las Comunidades Autónomas y provincias.',null),
('aux-age:9-0097609956','aux-age',9,'¿Cuántas Comunidades Autónomas y Ciudades Autónomas hay en España?','["17 Comunidades Autónomas y 2 Ciudades Autónomas", "16 Comunidades Autónomas y 2 Ciudades Autónomas", "19 Comunidades Autónomas", "17 Comunidades Autónomas y 3 Ciudades Autónomas"]'::jsonb,0,'Organización territorial','Las Ciudades Autónomas son Ceuta y Melilla.',null),
('aux-age:9-323c9274af','aux-age',9,'Según la Ley 7/1985, son elementos del municipio:','["El territorio, la población y la organización", "El término municipal, el padrón y el presupuesto", "El territorio, los vecinos y el Alcalde", "La población, el patrimonio y el Pleno"]'::jsonb,0,'Art. 11.2 LBRL','El municipio es la entidad local básica de la organización territorial del Estado.',null),
('aux-age:9-144e4d8f16','aux-age',9,'La Junta de Gobierno Local existe:','["En los municipios de más de 5.000 habitantes y en los de menos si lo disponen su reglamento orgánico o el Pleno", "Solo en los municipios de más de 20.000 habitantes", "En todos los municipios, sea cual sea su población, como órgano de asistencia permanente al Alcalde en sus funciones", "Solo en los municipios de gran población, regulados en el título X de la Ley 7/1985, reguladora de las Bases del Régimen Local"]'::jsonb,0,'Art. 20.1 b) LBRL','El Alcalde, los Tenientes de Alcalde y el Pleno existen en todos los Ayuntamientos.',null),
('aux-age:9-aa781e9280','aux-age',9,'¿Qué servicio deben prestar los municipios de más de 50.000 habitantes, además de los exigidos a los más pequeños?','["Transporte colectivo urbano de viajeros", "Biblioteca pública", "Instalaciones deportivas de uso público", "Alumbrado público"]'::jsonb,0,'Art. 26.1 d) LBRL','La biblioteca es obligatoria desde 5.000 habitantes, las instalaciones deportivas desde 20.000 y el alumbrado en todos.',null),
('aux-age:10-a10217487a','aux-age',10,'¿Qué tratado creó en 1951 la Comunidad Europea del Carbón y del Acero?','["El Tratado de Roma", "El Tratado de Bruselas", "El Tratado de Maastricht", "El Tratado de París"]'::jsonb,3,'Tratados constitutivos','Los Tratados de Roma de 1957 crearon la CEE y la Comunidad Europea de la Energía Atómica (Euratom).',null),
('aux-age:10-efe9ceb9c2','aux-age',10,'Los Tratados de Roma de 1957 crearon:','["La Comunidad Europea del Carbón y del Acero y el Consejo de Europa con sede en Estrasburgo", "La Comunidad Económica Europea y la Comunidad Europea de la Energía Atómica", "La Unión Europea y el Banco Central Europeo como su institución monetaria común", "El Espacio Económico Europeo y la Unión Europea Occidental de defensa común"]'::jsonb,1,'Tratados constitutivos','La CECA se creó en 1951 por el Tratado de París.',null),
('aux-age:10-a1ba316bd7','aux-age',10,'¿Qué tratado creó la Unión Europea?','["El Tratado de Maastricht de 1992", "El Tratado de Ámsterdam de 1997", "El Tratado de Lisboa de 2007", "El Acta Única Europea de 1986"]'::jsonb,0,'Tratado de la Unión Europea','Se firmó en 1992 y entró en vigor en noviembre de 1993.',null),
('aux-age:10-7cf64875c4','aux-age',10,'¿Cuándo entró en vigor el Tratado de Lisboa?','["El 1 de enero de 2008", "El 13 de diciembre de 2007", "El 1 de diciembre de 2009", "El 1 de noviembre de 1993"]'::jsonb,2,'Tratado de Lisboa','Se firmó el 13 de diciembre de 2007.',null),
('aux-age:10-86c3bbcbc9','aux-age',10,'¿Desde qué fecha es España miembro de las Comunidades Europeas?','["Desde el 1 de enero de 1986", "Desde el 1 de enero de 1981", "Desde el 1 de noviembre de 1993", "Desde el 12 de junio de 1985"]'::jsonb,0,'Adhesión de España','El Tratado de adhesión se firmó el 12 de junio de 1985, junto con Portugal.',null),
('aux-age:10-89934c961a','aux-age',10,'¿Cuántas instituciones enumera el artículo 13 del Tratado de la Unión Europea?','["Cinco", "Seis", "Nueve", "Siete"]'::jsonb,3,'Art. 13 TUE','Parlamento Europeo, Consejo Europeo, Consejo, Comisión, Tribunal de Justicia de la UE, Banco Central Europeo y Tribunal de Cuentas.',null),
('aux-age:10-36af90eeaa','aux-age',10,'¿Cuál de los siguientes NO es una institución de la Unión según el artículo 13 del TUE?','["El Comité de las Regiones", "El Tribunal de Cuentas", "El Banco Central Europeo", "El Consejo Europeo"]'::jsonb,0,'Art. 13 TUE','El Comité de las Regiones y el Comité Económico y Social son órganos consultivos, no instituciones.',null),
('aux-age:10-a37671abf9','aux-age',10,'¿Por cuánto tiempo se elige a los miembros del Parlamento Europeo?','["Cinco años", "Cuatro años", "Dos años y medio", "Seis años"]'::jsonb,0,'Art. 14.3 TUE','Se eligen por sufragio universal directo, libre y secreto.',null),
('aux-age:10-4a3c828ae5','aux-age',10,'El número de miembros del Parlamento Europeo no puede exceder de:','["700, incluido el Presidente", "750, más el Presidente", "751, más el Presidente", "800, más el Presidente"]'::jsonb,1,'Art. 14.2 TUE','Ningún Estado puede tener más de 96 escaños ni menos de 6.',null),
('aux-age:10-b597d25ac9','aux-age',10,'¿Dónde tiene su sede oficial el Parlamento Europeo?','["En Fráncfort", "En Luxemburgo", "En Bruselas", "En Estrasburgo"]'::jsonb,3,'Sedes de las instituciones','También trabaja en Bruselas y su Secretaría General está en Luxemburgo.',null),
('aux-age:10-9dec2e4743','aux-age',10,'¿Quiénes componen el Consejo Europeo?','["Los Ministros de Asuntos Exteriores de los Estados miembros, el Alto Representante y el Presidente de la Comisión", "Un representante de cada Estado miembro de rango ministerial", "Los Presidentes de los Parlamentos nacionales de los Estados miembros y el Presidente del Parlamento Europeo", "Los Jefes de Estado o de Gobierno de los Estados miembros, su Presidente y el Presidente de la Comisión"]'::jsonb,3,'Art. 15.2 TUE','El Alto Representante participa en sus trabajos, pero no es miembro.',null),
('aux-age:10-c0f954001c','aux-age',10,'El Presidente del Consejo Europeo es elegido por un mandato de:','["Seis meses, coincidiendo con la presidencia rotatoria", "Cinco años, no renovable", "Dos años, renovable indefinidamente", "Dos años y medio, renovable una sola vez"]'::jsonb,3,'Art. 15.5 TUE','Lo elige el propio Consejo Europeo por mayoría cualificada.',null),
('aux-age:10-50d74db48a','aux-age',10,'El Consejo de la Unión Europea está compuesto por:','["Un representante de cada Estado miembro de rango ministerial", "Un comisario por cada Estado miembro, nombrado por su Gobierno nacional", "Los Jefes de Estado o de Gobierno de los Estados miembros y su Presidente", "Los embajadores de los Estados miembros ante la Unión, con rango de representantes permanentes"]'::jsonb,0,'Art. 16.2 TUE','Ese representante puede comprometer al Gobierno de su Estado y ejercer el derecho de voto.',null),
('aux-age:10-9b6c3f0dfd','aux-age',10,'¿Cada cuánto tiempo rota la presidencia del Consejo de la Unión Europea entre los Estados miembros?','["Cada año", "Cada dos años y medio", "Cada seis meses", "Cada tres meses"]'::jsonb,2,'Presidencia del Consejo','La única excepción es el Consejo de Asuntos Exteriores, que preside el Alto Representante.',null),
('aux-age:10-7c40e55f5a','aux-age',10,'Desde 2014, la mayoría cualificada en el Consejo se define como:','["Al menos dos tercios de los Estados miembros que representen como mínimo la mitad de la población de la Unión", "La mayoría absoluta de los Estados miembros, sea cual sea su población, siempre que incluya a los cuatro más poblados", "Al menos el 55 % de los miembros del Consejo que representen al menos el 65 % de la población de la Unión", "Al menos el 65 % de los miembros del Consejo que representen como mínimo el 55 % de la población de la Unión"]'::jsonb,2,'Art. 16.4 TUE','La minoría de bloqueo debe incluir al menos a cuatro miembros del Consejo.',null),
('aux-age:10-937ddb8a72','aux-age',10,'¿Qué institución tiene, como regla general, la iniciativa legislativa en la Unión Europea?','["La Comisión Europea", "El Consejo Europeo", "El Consejo de la Unión", "El Parlamento Europeo"]'::jsonb,0,'Art. 17.2 TUE','Los actos legislativos solo pueden adoptarse a propuesta de la Comisión, salvo que los Tratados dispongan otra cosa.',null),
('aux-age:10-12c4728cdf','aux-age',10,'¿Cómo se elige al Presidente de la Comisión Europea?','["Lo eligen los ciudadanos de la Unión por sufragio universal directo cada cinco años", "Lo nombra el Consejo de la Unión por mayoría simple, a propuesta del Parlamento Europeo", "El Consejo Europeo propone un candidato por mayoría cualificada y el Parlamento Europeo lo elige por mayoría de sus miembros", "Lo elige directamente el Consejo Europeo por unanimidad, sin intervención del Parlamento"]'::jsonb,2,'Art. 17.7 TUE','El Consejo Europeo tiene en cuenta el resultado de las elecciones al Parlamento Europeo.',null),
('aux-age:10-c6bb14720b','aux-age',10,'¿Qué cargo ocupa el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad dentro de la Comisión?','["Es su Secretario General, con voz pero sin voto", "Es uno de sus Vicepresidentes", "Es su Presidente, por razón de su cargo", "No forma parte de la Comisión, sino del Consejo Europeo"]'::jsonb,1,'Art. 18.4 TUE','Además preside el Consejo de Asuntos Exteriores.',null),
('aux-age:10-f66ad1797c','aux-age',10,'¿Dónde tiene su sede el Tribunal de Justicia de la Unión Europea?','["En Bruselas", "En Estrasburgo", "En Luxemburgo", "En La Haya"]'::jsonb,2,'Sedes de las instituciones','En La Haya está el Tribunal Internacional de Justicia y en Estrasburgo el Tribunal Europeo de Derechos Humanos, que no son órganos de la UE.',null),
('aux-age:10-92a1343f29','aux-age',10,'¿Dónde tiene su sede el Banco Central Europeo?','["En Ámsterdam", "En Luxemburgo", "En Bruselas", "En Fráncfort"]'::jsonb,3,'Sedes de las instituciones','El BCE dirige la política monetaria de la zona euro.',null),
('aux-age:10-c8e1f63c50','aux-age',10,'Según el artículo 288 del TFUE, el reglamento:','["Obliga al Estado destinatario en cuanto al resultado, dejando a las autoridades nacionales la elección de la forma y los medios", "No es vinculante y solo expresa una opinión de las instituciones", "Tiene alcance general, es obligatorio en todos sus elementos y directamente aplicable en cada Estado miembro", "Solo es obligatorio para sus destinatarios, que deben estar designados en él"]'::jsonb,2,'Art. 288 TFUE','La segunda opción describe la directiva, la tercera la decisión y la cuarta los dictámenes.',null),
('aux-age:10-82c41b0942','aux-age',10,'¿Qué acto de la Unión obliga al Estado miembro destinatario en cuanto al resultado que deba conseguirse, dejando a las autoridades nacionales la elección de la forma y de los medios?','["La recomendación", "La decisión", "El reglamento", "La directiva"]'::jsonb,3,'Art. 288 TFUE','Las directivas deben transponerse al derecho interno.',null),
('aux-age:10-8d8bc04665','aux-age',10,'Según el artículo 288 del TFUE, las recomendaciones y los dictámenes:','["Son obligatorios en todos sus elementos", "Solo obligan a sus destinatarios", "Obligan solo en cuanto al resultado", "No son vinculantes"]'::jsonb,3,'Art. 288 TFUE','Son actos de las instituciones sin fuerza obligatoria.',null),
('aux-age:10-336db8f233','aux-age',10,'En el procedimiento legislativo ordinario, los actos se adoptan conjuntamente por:','["El Consejo Europeo y el Parlamento, a propuesta del Consejo", "La Comisión y el Consejo Europeo, oído el Parlamento", "El Parlamento Europeo y el Consejo, a propuesta de la Comisión", "El Consejo de la Unión por unanimidad, previa consulta al Parlamento"]'::jsonb,2,'Art. 294 TFUE','Antes del Tratado de Lisboa se llamaba procedimiento de codecisión.',null),
('aux-age:10-3e6625c2ae','aux-age',10,'¿Quién elige al Defensor del Pueblo Europeo?','["El Tribunal de Justicia", "El Consejo Europeo", "El Parlamento Europeo", "La Comisión Europea"]'::jsonb,2,'Art. 228 TFUE','Recibe reclamaciones sobre casos de mala administración en la acción de las instituciones, órganos y organismos de la Unión.',null),
('aux-age:10-da1420c488','aux-age',10,'¿Cuántos ciudadanos de la Unión, como mínimo, deben respaldar una iniciativa ciudadana europea?','["Quinientos mil, de al menos cinco Estados miembros distintos de la Unión", "Dos millones, procedentes como mínimo de la mitad de los Estados miembros", "Cien mil, sin importar su nacionalidad ni su Estado de residencia", "Un millón, de un número significativo de Estados miembros"]'::jsonb,3,'Art. 11.4 TUE','Con ella se invita a la Comisión a presentar una propuesta legislativa.',null)
insert into public.preguntas (id,oposicion,tema,pregunta,opciones,correcta,articulo,explicacion,examen) values
('aux-age:10-d3a44fc823','aux-age',10,'¿Qué artículo del Tratado de la Unión Europea regula la retirada voluntaria de un Estado miembro?','["El artículo 7", "El artículo 49", "El artículo 50", "El artículo 48"]'::jsonb,2,'Art. 50 TUE','El artículo 49 regula la adhesión, el 7 la suspensión de derechos y el 48 la revisión de los Tratados.',null),
('aux-age:10-82d66f5a33','aux-age',10,'¿Cuántos Estados miembros tiene actualmente la Unión Europea?','["28", "25", "26", "27"]'::jsonb,3,'Estados miembros','Son 27 desde la salida del Reino Unido en 2020.',null),
('aux-age:10-3d6faecd81','aux-age',10,'¿A qué institución corresponde el control de las cuentas de la Unión?','["Al Banco Central Europeo", "A la Oficina Europea de Lucha contra el Fraude", "Al Tribunal de Justicia de la Unión", "Al Tribunal de Cuentas Europeo"]'::jsonb,3,'Art. 285 TFUE','Tiene su sede en Luxemburgo y está formado por un nacional de cada Estado miembro.',null),
('aux-age:13-e87a06989f','aux-age',13,'Según el TREBEP, ¿cuál es el procedimiento normal de provisión de puestos de trabajo de los funcionarios de carrera?','["La adscripción provisional", "El concurso", "La comisión de servicios", "La libre designación"]'::jsonb,1,'Art. 78 TREBEP','La libre designación con convocatoria pública es el otro procedimiento ordinario, reservado a puestos determinados por su especial responsabilidad o confianza.',null),
('aux-age:13-b4aa923cf8','aux-age',13,'¿Cuál de las siguientes NO es una situación administrativa de los funcionarios de carrera según el artículo 85 del TREBEP?','["Servicios especiales", "Suspensión de funciones", "Servicio en otras Administraciones Públicas", "Expectativa de destino indefinida"]'::jsonb,3,'Art. 85.1 TREBEP','Las situaciones son servicio activo, servicios especiales, servicio en otras Administraciones Públicas, excedencia y suspensión de funciones.',null),
('aux-age:13-435f9ddc96','aux-age',13,'Según el Reglamento General de Ingreso y Provisión (RD 364/1995), las comisiones de servicios tienen una duración máxima de:','["Dos años, prorrogables por otros dos", "Tres años, como los interinos en plaza vacante", "Un año, prorrogable por otro en caso de no haberse cubierto el puesto con carácter definitivo", "Seis meses, sin posibilidad de prórroga"]'::jsonb,2,'Art. 64.3 RD 364/1995','El puesto cubierto en comisión de servicios se incluye en la siguiente convocatoria de provisión.',null),
('aux-age:13-8dccd6307a','aux-age',13,'¿Qué norma aprueba el Reglamento General de Ingreso del Personal al servicio de la Administración General del Estado y de Provisión de Puestos de Trabajo?','["El Real Decreto 364/1995, de 10 de marzo", "El Real Decreto Legislativo 5/2015, de 30 de octubre", "El Real Decreto 33/1986, de 10 de enero", "El Real Decreto 365/1995, de 10 de marzo"]'::jsonb,0,'RD 364/1995','El RD 365/1995 regula las situaciones administrativas y el RD 33/1986 el régimen disciplinario.',null),
('aux-age:13-e95362fced','aux-age',13,'¿Qué reglamento regula el régimen disciplinario de los funcionarios de la Administración General del Estado?','["El Real Decreto 33/1986, de 10 de enero", "El Real Decreto 365/1995, de 10 de marzo", "El Real Decreto 364/1995, de 10 de marzo", "La Ley 53/1984, de 26 de diciembre"]'::jsonb,0,'RD 33/1986','La Ley 53/1984 regula las incompatibilidades del personal al servicio de las Administraciones Públicas.',null),
('aux-age:13-9fb9338bc6','aux-age',13,'Los funcionarios que acceden a la condición de diputado o senador de las Cortes Generales pasan a la situación de:','["Suspensión provisional de funciones", "Servicio activo con dispensa de funciones", "Excedencia voluntaria por interés particular", "Servicios especiales"]'::jsonb,3,'Art. 87.1 TREBEP','Tienen derecho a reingresar al servicio activo en la misma localidad y en las mismas condiciones y con las retribuciones correspondientes a su categoría.',null),
('aux-age:13-905cc8da8d','aux-age',13,'Según el TREBEP, los funcionarios en situación de servicios especiales:','["Pierden la condición de funcionario mientras dure la situación", "No tienen derecho a reserva de puesto ni a que se les compute el tiempo a ningún efecto", "Solo tienen derecho al cómputo de trienios, pero no a la reserva de puesto", "Tienen derecho a que se les compute el tiempo en esa situación a efectos de ascensos, reconocimiento de trienios y derechos en el régimen de Seguridad Social"]'::jsonb,3,'Art. 87.2 TREBEP','No se les aplica, sin embargo, el régimen de derechos pasivos si les corresponde otro.',null),
('aux-age:15-e9ac768348','aux-age',15,'Según el artículo 134 de la Constitución, la elaboración de los Presupuestos Generales del Estado corresponde:','["A las Cortes Generales", "Al Ministerio de Hacienda y al Banco de España", "Al Congreso de los Diputados", "Al Gobierno"]'::jsonb,3,'Art. 134.1 CE','Al Gobierno le corresponde elaborarlos y a las Cortes Generales examinarlos, enmendarlos y aprobarlos.',null),
('aux-age:15-779d6a6c11','aux-age',15,'Según la Constitución, el Gobierno debe presentar los Presupuestos Generales del Estado ante el Congreso:','["Al menos tres meses antes de la expiración de los del año anterior", "Antes del 31 de diciembre del año anterior", "En el primer mes de cada período de sesiones", "Al menos seis meses antes de la expiración de los del año anterior, junto con su memoria"]'::jsonb,0,'Art. 134.3 CE','La Ley General Presupuestaria concreta que debe remitirse antes del 1 de octubre.',null),
('aux-age:15-e8e43e6c6d','aux-age',15,'Según la Ley General Presupuestaria, el proyecto de Ley de Presupuestos Generales del Estado se remite a las Cortes:','["Antes del día 1 de septiembre del año anterior al que se refiera", "Antes del día 31 de octubre del año anterior al que se refiera", "Antes del día 15 de diciembre del año anterior al que se refiera", "Antes del día 1 de octubre del año anterior al que se refiera"]'::jsonb,3,'Art. 37.2 Ley 47/2003','Va acompañado de la documentación complementaria que prevé la propia ley.',null),
('aux-age:15-1af6b05f56','aux-age',15,'Si la Ley de Presupuestos no se aprueba antes del primer día del ejercicio económico correspondiente:','["Se consideran automáticamente prorrogados los presupuestos del ejercicio anterior hasta la aprobación de los nuevos", "Se aplican los presupuestos que presentó el Gobierno, a la espera de su aprobación", "El Gobierno puede aprobarlos mediante real decreto-ley con la convalidación posterior del Congreso", "No puede realizarse ningún gasto público hasta su aprobación definitiva"]'::jsonb,0,'Art. 134.4 CE y art. 38 Ley 47/2003','La prórroga no afecta a los créditos de programas que terminen en el ejercicio anterior.',null),
('aux-age:15-b47591c384','aux-age',15,'Según el artículo 134 de la Constitución, los Presupuestos Generales del Estado tienen carácter:','["Bienal", "Anual", "Plurianual", "Cuatrienal"]'::jsonb,1,'Art. 134.2 CE','Incluyen la totalidad de los gastos e ingresos del sector público estatal y el importe de los beneficios fiscales que afecten a los tributos del Estado.',null),
('aux-age:15-556b426b2c','aux-age',15,'¿Puede la Ley de Presupuestos crear tributos?','["Sí, siempre que se trate de tasas o precios públicos", "No, ni tampoco modificarlos en ningún caso, ni siquiera cuando lo prevea una ley tributaria", "Sí, porque es la ley que aprueba los ingresos del Estado", "No, aunque puede modificarlos si una ley tributaria sustantiva así lo prevé"]'::jsonb,3,'Art. 134.7 CE','Es una limitación constitucional al contenido de la Ley de Presupuestos.',null),
('aux-age:15-443102638e','aux-age',15,'Toda proposición o enmienda que suponga aumento de los créditos o disminución de los ingresos presupuestarios requiere para su tramitación:','["La mayoría absoluta del Congreso", "El dictamen del Consejo de Estado", "El informe del Tribunal de Cuentas", "La conformidad del Gobierno"]'::jsonb,3,'Art. 134.6 CE','Es una garantía del equilibrio presupuestario aprobado.',null),
('aux-age:15-dc73207797','aux-age',15,'¿Qué órgano es el supremo órgano fiscalizador de las cuentas y de la gestión económica del Estado y del sector público?','["El Tribunal Constitucional", "El Tribunal de Cuentas", "La Autoridad Independiente de Responsabilidad Fiscal", "La Intervención General de la Administración del Estado"]'::jsonb,1,'Art. 136.1 CE','Depende directamente de las Cortes Generales. La IGAE ejerce el control interno.',null),
('aux-age:15-59710f4baf','aux-age',15,'El ejercicio presupuestario, según la Ley General Presupuestaria:','["Coincide con el año natural", "Coincide con el período de sesiones de las Cortes", "Dura dieciocho meses", "Va del 1 de julio al 30 de junio"]'::jsonb,0,'Art. 34.1 Ley 47/2003','Se imputan a él los derechos liquidados y las obligaciones reconocidas hasta el 31 de diciembre.',null),
('aux-age:15-89cf3cd5d7','aux-age',15,'¿Cuál de los siguientes NO es un principio de la programación presupuestaria del artículo 26 de la Ley General Presupuestaria?','["Universalidad de las prestaciones", "Estabilidad presupuestaria", "Sostenibilidad financiera", "Plurianualidad"]'::jsonb,0,'Art. 26.1 Ley 47/2003','También lo son la transparencia, la eficiencia en la asignación de los recursos públicos y la responsabilidad y lealtad institucional.',null),
('aux-age:15-d09b5c6b08','aux-age',15,'Los créditos para gastos de los Presupuestos Generales del Estado tienen carácter:','["Ampliable en todo caso", "Orientativo", "Estimativo", "Limitativo"]'::jsonb,3,'Art. 46 Ley 47/2003','No pueden adquirirse compromisos por encima de su importe; los actos que lo incumplan son nulos de pleno derecho.',null),
('aux-age:15-a35f719470','aux-age',15,'Los actos que adquieran compromisos de gasto por cuantía superior al importe de los créditos autorizados son:','["Válidos, aunque generan responsabilidad", "Irregulares no invalidantes", "Nulos de pleno derecho", "Anulables"]'::jsonb,2,'Art. 46 Ley 47/2003','Sin perjuicio de las responsabilidades que regula el título VII de la Ley General Presupuestaria.',null),
('aux-age:15-b44dda8717','aux-age',15,'¿En qué tres clasificaciones se estructuran los estados de gastos de los Presupuestos Generales del Estado?','["Orgánica, territorial y temporal", "Funcional, sectorial y patrimonial", "Económica, financiera y contable", "Orgánica, por programas y económica"]'::jsonb,3,'Art. 40 Ley 47/2003','La clasificación económica distingue operaciones corrientes, de capital, financieras y el Fondo de Contingencia.',null),
('aux-age:15-e2f7a299d8','aux-age',15,'¿Qué recoge el capítulo 1 de la clasificación económica del presupuesto de gastos?','["Transferencias corrientes", "Inversiones reales", "Gastos corrientes en bienes y servicios", "Gastos de personal"]'::jsonb,3,'Clasificación económica','El capítulo 2 son gastos corrientes en bienes y servicios, el 4 transferencias corrientes y el 6 inversiones reales.',null),
('aux-age:15-bd6f540fa2','aux-age',15,'En la clasificación económica del presupuesto de gastos, el capítulo 6 corresponde a:','["Inversiones reales", "Activos financieros", "Transferencias de capital", "Gastos financieros"]'::jsonb,0,'Clasificación económica','El capítulo 7 son transferencias de capital, el 8 activos financieros y el 3 gastos financieros.',null),
('aux-age:15-2526d0ae21','aux-age',15,'¿Qué capítulo del presupuesto de gastos se reserva al Fondo de Contingencia?','["El capítulo 9", "El capítulo 3", "El capítulo 7", "El capítulo 5"]'::jsonb,3,'Clasificación económica','El capítulo 9 son pasivos financieros, el 3 gastos financieros y el 7 transferencias de capital.',null),
('aux-age:15-9e492aa138','aux-age',15,'En la clasificación económica del presupuesto de ingresos, el capítulo 1 corresponde a:','["Ingresos patrimoniales", "Impuestos directos y cotizaciones sociales", "Impuestos indirectos", "Tasas, precios públicos y otros ingresos"]'::jsonb,1,'Clasificación económica','Los impuestos indirectos están en el capítulo 2 y las tasas y precios públicos en el 3.',null),
('aux-age:15-3303d4ee6b','aux-age',15,'¿Qué cuantía tiene el Fondo de Contingencia de ejecución presupuestaria?','["El 1 % de los ingresos tributarios previstos para el ejercicio", "El 10 % de los créditos de inversiones reales del Estado", "El 2 % del total de gastos para operaciones no financieras, con algunas exclusiones", "El 5 % del total del presupuesto de gastos, incluidas las operaciones financieras"]'::jsonb,2,'Art. 50 Ley 47/2003','Su aplicación requiere acuerdo del Consejo de Ministros y el Gobierno informa trimestralmente a las Cortes.',null),
('aux-age:15-c4eea7acac','aux-age',15,'¿Para qué puede utilizarse el Fondo de Contingencia?','["Para financiar ampliaciones de crédito, créditos extraordinarios, suplementos e incorporaciones", "Para pagar las retribuciones del personal cuando se prorrogan los presupuestos", "Para cubrir cualquier gasto de los Ministerios sin necesidad de autorización", "Para amortizar anticipadamente la deuda pública del Estado"]'::jsonb,0,'Art. 50 Ley 47/2003','Solo puede destinarse a necesidades de carácter no discrecional y no previstas en el presupuesto inicialmente aprobado.',null),
('aux-age:15-f549f85057','aux-age',15,'Cuando hay que realizar un gasto que no puede demorarse y no existe crédito adecuado en el presupuesto, se tramita:','["Una generación de crédito", "Un suplemento de crédito", "Una transferencia de crédito", "Un crédito extraordinario"]'::jsonb,3,'Art. 55 Ley 47/2003','Si el crédito existe pero es insuficiente y no ampliable, se tramita un suplemento de crédito.',null),
('aux-age:15-cb064aaddd','aux-age',15,'El suplemento de crédito procede cuando:','["El crédito existe pero es insuficiente y no ampliable", "Se trasladan créditos entre programas", "Se reciben durante el ejercicio ingresos que no estaban previstos inicialmente", "No existe crédito adecuado para el gasto en el presupuesto en vigor"]'::jsonb,0,'Art. 55 Ley 47/2003','Si no existe crédito, procede un crédito extraordinario.',null),
('aux-age:15-1059ecc161','aux-age',15,'¿Cuál es la primera fase de la gestión del presupuesto de gastos?','["El reconocimiento de la obligación", "La ordenación del pago", "El compromiso de gasto", "La aprobación del gasto"]'::jsonb,3,'Art. 73 Ley 47/2003','Le siguen el compromiso de gasto, el reconocimiento de la obligación, la ordenación del pago y el pago material.',null),
('aux-age:15-e749addf5c','aux-age',15,'La fase en la que se acuerda, tras los trámites oportunos, la realización de un gasto previamente aprobado, vinculándose con un tercero, es:','["La aprobación del gasto", "El compromiso de gasto", "El pago material", "El reconocimiento de la obligación"]'::jsonb,1,'Art. 73 Ley 47/2003','El compromiso es un acto con relevancia jurídica para con terceros.',null),
('aux-age:15-d29290fb58','aux-age',15,'¿Qué órgano ejerce el control interno de la gestión económica y financiera del sector público estatal?','["La Intervención General de la Administración del Estado", "El Tribunal de Cuentas, como supremo órgano fiscalizador del Estado", "La Comisión de Presupuestos del Congreso de los Diputados y del Senado", "La Dirección General de Presupuestos del Ministerio de Hacienda"]'::jsonb,0,'Art. 140 Ley 47/2003','El Tribunal de Cuentas ejerce el control externo.',null),
('aux-age:15-4123947320','aux-age',15,'El control interno que ejerce la Intervención General de la Administración del Estado se realiza mediante:','["La función interventora, el control financiero permanente y la auditoría pública", "La auditoría pública, el control de eficacia judicial y la inspección tributaria", "El control previo de legalidad, el recurso de alzada y la revisión de oficio", "La función interventora, el enjuiciamiento contable y la fiscalización parlamentaria"]'::jsonb,0,'Art. 142 Ley 47/2003','El enjuiciamiento contable corresponde al Tribunal de Cuentas.',null),
('aux-age:15-1e4385c033','aux-age',15,'¿Qué ley orgánica regula la estabilidad presupuestaria y la sostenibilidad financiera?','["La LO 8/1980, de 22 de septiembre", "La LO 6/2002, de 27 de junio", "La LO 3/2015, de 30 de marzo", "La LO 2/2012, de 27 de abril"]'::jsonb,3,'LO 2/2012','La LO 8/1980 es la de Financiación de las Comunidades Autónomas.',null),
('aux-age:15-574f4b50ff','aux-age',15,'¿Qué artículo de la Constitución consagra el principio de estabilidad presupuestaria tras la reforma de 2011?','["El artículo 136", "El artículo 134", "El artículo 135", "El artículo 131"]'::jsonb,2,'Art. 135 CE','Todas las Administraciones Públicas adecuarán sus actuaciones al principio de estabilidad presupuestaria.',null),
('aux-age:15-ef0df5f865','aux-age',15,'¿A quién se remite la Cuenta General del Estado para su fiscalización?','["Al Tribunal de Cuentas", "A la Comisión Europea", "Al Banco de España", "Al Consejo de Ministros"]'::jsonb,0,'Art. 136 CE','El Tribunal de Cuentas remite a las Cortes un informe anual sobre ella.',null),
('aux-age:15-f4055f7164','aux-age',15,'Las fases del ciclo presupuestario son:','["Elaboración, publicación, prórroga y liquidación", "Previsión, recaudación, pago y auditoría", "Iniciativa, enmienda, sanción y promulgación", "Elaboración, aprobación, ejecución y control"]'::jsonb,3,'Ciclo presupuestario','El Gobierno elabora y ejecuta, las Cortes aprueban, y el control lo ejercen la IGAE y el Tribunal de Cuentas.',null),
('aux-age:16-8f137b8866','aux-age',16,'¿Qué norma aprobó el Texto Refundido de la Ley General de derechos de las personas con discapacidad y de su inclusión social?','["El Real Decreto Legislativo 1/2013, de 29 de noviembre", "El Real Decreto Legislativo 5/2015, de 30 de octubre", "La Ley 39/2006, de 14 de diciembre", "La Ley 51/2003, de 2 de diciembre"]'::jsonb,0,'RDL 1/2013','La Ley 39/2006 regula la dependencia y el RDL 5/2015 es el TREBEP.',null),
('aux-age:16-be8cdf54cf','aux-age',16,'Según el Real Decreto Legislativo 1/2013, tienen la consideración de personas con discapacidad, a todos los efectos, aquellas a quienes se haya reconocido un grado de discapacidad:','["Igual o superior al 33 %", "Igual o superior al 65 %", "Igual o superior al 25 %", "Superior al 50 %"]'::jsonb,0,'Art. 4.2 RDL 1/2013','También se consideran así, entre otros, los pensionistas de la Seguridad Social con incapacidad permanente total, absoluta o gran invalidez.',null),
('aux-age:16-6b49fb6a2e','aux-age',16,'Según el TREBEP, en las ofertas de empleo público se reserva para personas con discapacidad intelectual, dentro del cupo general, al menos:','["El 7 % de las plazas ofertadas", "El 2 % de las plazas ofertadas", "El 1 % de las plazas ofertadas", "El 5 % de las plazas ofertadas"]'::jsonb,1,'Art. 59.1 TREBEP','El cupo total para personas con discapacidad no es inferior al 7 %, y de él al menos el 2 % es para personas con discapacidad intelectual.',null),
('aux-age:16-dfc471012e','aux-age',16,'Las empresas públicas y privadas que empleen a 50 o más trabajadores están obligadas a que, de entre ellos, sean trabajadores con discapacidad al menos:','["El 2 %", "El 7 %", "El 1 %", "El 5 %"]'::jsonb,0,'Art. 42.1 RDL 1/2013','Excepcionalmente pueden quedar exentas aplicando medidas alternativas.',null),
('aux-age:16-0f9270a8a2','aux-age',16,'Según el RDL 1/2013, los «ajustes razonables» son:','["Las ayudas económicas que concede la Administración a las personas con un grado de discapacidad superior al 65 % para adaptar su puesto de trabajo y su vivienda habitual", "Las reducciones de jornada a las que tienen derecho todos los trabajadores con discapacidad", "Las modificaciones y adaptaciones necesarias y adecuadas que no impongan una carga desproporcionada o indebida, cuando se requieran en un caso particular", "Las bonificaciones fiscales que reciben las empresas por contratar personas con discapacidad"]'::jsonb,2,'Art. 2 RDL 1/2013','Buscan facilitar la accesibilidad y la participación en igualdad de condiciones.',null),
('aux-age:16-63344dde5e','aux-age',16,'La reforma del artículo 49 de la Constitución aprobada en 2024 sustituyó la expresión «disminuidos físicos, sensoriales y psíquicos» por:','["Personas con discapacidad", "Personas dependientes", "Personas con capacidades diferentes", "Personas con diversidad funcional"]'::jsonb,0,'Art. 49 CE (reforma de 17 de febrero de 2024)','Fue la tercera reforma de la Constitución, tras las de 1992 (art. 13.2) y 2011 (art. 135).',null),
('aux-age:16-30f0113943','aux-age',16,'¿Qué tratado internacional sobre discapacidad aprobó la Asamblea General de Naciones Unidas en 2006?','["La Declaración Universal de los Derechos de las Personas Dependientes", "La Carta Social Europea sobre inclusión de las personas con discapacidad", "El Convenio Europeo de Derechos Humanos y su Protocolo de discapacidad", "La Convención sobre los derechos de las personas con discapacidad"]'::jsonb,3,'Convención ONU 2006','España la ratificó y está en vigor en nuestro país desde 2008.',null),
('aux-age:16-7cec75409c','aux-age',16,'¿Qué ley regula la promoción de la autonomía personal y la atención a las personas en situación de dependencia?','["La Ley 15/2022, de 12 de julio", "La Ley 39/2006, de 14 de diciembre", "La Ley 39/2015, de 1 de octubre", "La Ley 4/2023, de 28 de febrero"]'::jsonb,1,'Ley 39/2006','Creó el Sistema para la Autonomía y Atención a la Dependencia (SAAD).',null),
('aux-age:16-b5c9841fcd','aux-age',16,'Según la Ley 39/2006, la situación de dependencia se clasifica en:','["Cinco niveles según el porcentaje de discapacidad", "Cuatro grados: leve, moderada, grave y absoluta", "Tres grados: moderada, severa y gran dependencia", "Dos grados: parcial y total"]'::jsonb,2,'Art. 26 Ley 39/2006','Grado I (moderada), grado II (severa) y grado III (gran dependencia).',null),
('aux-age:16-cbf472f28a','aux-age',16,'En la Ley 39/2006, el grado III corresponde a:','["La dependencia leve", "La dependencia severa", "La dependencia moderada", "La gran dependencia"]'::jsonb,3,'Art. 26.1 c) Ley 39/2006','Se da cuando la persona necesita ayuda para varias actividades básicas de la vida diaria varias veces al día y precisa el apoyo indispensable y continuo de otra persona.',null),
('aux-age:16-4281a49268','aux-age',16,'¿Cuál de los siguientes es un servicio del catálogo de la Ley 39/2006?','["El ingreso mínimo vital", "La pensión no contributiva de invalidez", "La prestación por desempleo", "La teleasistencia"]'::jsonb,3,'Art. 15 Ley 39/2006','El catálogo incluye también la ayuda a domicilio, los centros de día y de noche y la atención residencial.',null),
('aux-age:16-3e4fa50f22','aux-age',16,'Entre las prestaciones económicas de la Ley 39/2006 se encuentra:','["La pensión de viudedad para los cónyuges y parejas de hecho de las personas en situación de dependencia", "El subsidio por incapacidad temporal del cuidador familiar que haya dejado de trabajar para atenderle", "La prestación por nacimiento y cuidado de menor", "La prestación para cuidados en el entorno familiar y apoyo a cuidadores no profesionales"]'::jsonb,3,'Art. 18 Ley 39/2006','Las otras dos son la prestación vinculada al servicio y la de asistencia personal.',null),
('aux-age:16-5af3c96ae3','aux-age',16,'¿Qué ley se aprobó en 2023 para la igualdad real y efectiva de las personas trans y para la garantía de los derechos de las personas LGTBI?','["La Ley 4/2023, de 28 de febrero", "La LO 2/2024, de 1 de agosto", "La LO 10/2022, de 6 de septiembre", "La Ley 15/2022, de 12 de julio"]'::jsonb,0,'Ley 4/2023','La Ley 15/2022 es la ley integral para la igualdad de trato y la no discriminación.',null),
('aux-age:16-2e58d02bb4','aux-age',16,'Según la Ley 4/2023, las terapias de conversión dirigidas a modificar la orientación sexual, la identidad sexual o la expresión de género de las personas:','["Están prohibidas, incluso con el consentimiento de la persona o de sus representantes", "Están permitidas únicamente en centros sanitarios autorizados previamente por la Comunidad Autónoma", "Están permitidas si la persona es mayor de edad y presta su consentimiento expreso y por escrito", "Solo están prohibidas cuando se apliquen a menores de catorce años o a personas con la capacidad modificada"]'::jsonb,0,'Art. 17 Ley 4/2023','Se prohíbe la práctica de métodos, programas y terapias de aversión, conversión o contracondicionamiento.',null),
('aux-age:16-122ddb8053','aux-age',16,'Según la Ley 4/2023, las empresas de más de cincuenta personas trabajadoras deben contar con:','["Un plan de igualdad entre mujeres y hombres negociado y registrado ante el Instituto de las Mujeres y la autoridad laboral de su Comunidad", "Un conjunto planificado de medidas y recursos para la igualdad real de las personas LGTBI, con un protocolo frente al acoso", "Un delegado de diversidad nombrado por la Inspección de Trabajo", "Un cupo de reserva del 2 % de su plantilla para personas trans y un delegado de diversidad elegido por la representación sindical"]'::jsonb,1,'Art. 15 Ley 4/2023','Las medidas se pactan a través de la negociación colectiva.',null),
('aux-age:16-fa72d8ca30','aux-age',16,'¿Qué autoridad crea la Ley 15/2022 para proteger y promover la igualdad de trato y la no discriminación?','["La Autoridad Independiente para la Igualdad de Trato y la No Discriminación", "El Observatorio Estatal de la Discriminación, adscrito al Instituto de las Mujeres", "El Consejo de Participación de las personas LGTBI", "El Defensor de la Igualdad y la Diversidad, dependiente del Ministerio del Interior"]'::jsonb,0,'Ley 15/2022','Es un órgano independiente con funciones de asistencia a las víctimas, investigación y mediación.',null),
('aux-age:16-211746474b','aux-age',16,'¿Qué ley orgánica de 2024 regula la representación paritaria y la presencia equilibrada de mujeres y hombres?','["La LO 3/2007, de 22 de marzo", "La LO 10/2022, de 6 de septiembre", "La LO 1/2004, de 28 de diciembre", "La LO 2/2024, de 1 de agosto"]'::jsonb,3,'LO 2/2024','La LO 3/2007 es la de igualdad efectiva, la LO 10/2022 la de garantía integral de la libertad sexual y la LO 1/2004 la de violencia de género.',null),
('aux-age:16-d0cefddb50','aux-age',16,'La Ley Orgánica 10/2022, de 6 de septiembre, regula:','["La garantía integral de la libertad sexual", "La igualdad real y efectiva de las personas trans", "Las medidas de protección integral contra la violencia de género", "La igualdad efectiva de mujeres y hombres"]'::jsonb,0,'LO 10/2022','Es la conocida como ley del «solo sí es sí».',null),
('aux-age:16-b620e8b8b5','aux-age',16,'El teléfono gratuito de información y asesoramiento jurídico a víctimas de violencia de género es:','["El 091", "El 112", "El 024", "El 016"]'::jsonb,3,'Servicio 016','No deja rastro en la factura telefónica. El 024 es la línea de atención a la conducta suicida.',null),
('aux-age:16-480957ca99','aux-age',16,'Según el RDL 1/2013, la accesibilidad universal es:','["El derecho de las personas con discapacidad a recibir una prestación económica de la Comunidad Autónoma para adaptar su vivienda habitual y su vehículo particular", "La condición que deben cumplir entornos, procesos, bienes, productos, servicios y objetos para ser comprensibles, utilizables y practicables por todas las personas", "La obligación de reservar plazas de aparcamiento en todos los edificios públicos", "El acceso gratuito de las personas con discapacidad a los transportes públicos"]'::jsonb,1,'Art. 2 RDL 1/2013','Debe darse en condiciones de seguridad y comodidad y de la forma más autónoma y natural posible.',null),
('aux-age:17-316a981ec5','aux-age',17,'En la atención al público, la escucha activa consiste en:','["Prestar atención plena al interlocutor y demostrarle que se le entiende, por ejemplo resumiendo o preguntando", "Escuchar en silencio, sin hacer preguntas ni dar ninguna señal, hasta que el ciudadano haya terminado de hablar", "Tomar nota de la petición del ciudadano y remitirla por escrito a la unidad competente para que esta le conteste", "Hablar más que el ciudadano para dirigir la conversación hacia la solución que ya se conoce de antemano en cada caso"]'::jsonb,0,'Comunicación en la atención al público','Incluye señales verbales y no verbales de comprensión, como asentir o parafrasear.',null),
('aux-age:17-e81f078b18','aux-age',17,'La empatía en la atención al ciudadano supone:','["Tratar a cada persona con la misma frialdad para ser imparcial", "Dar siempre la razón al ciudadano para evitar conflictos", "Ponerse en el lugar del otro y comprender su situación y sus sentimientos", "Compartir con el ciudadano las opiniones personales sobre la Administración"]'::jsonb,2,'Comunicación en la atención al público','Comprender no significa necesariamente estar de acuerdo.',null),
('aux-age:17-c370a301aa','aux-age',17,'La asertividad es la habilidad de:','["Responder con rapidez sin escuchar los argumentos del otro", "Expresar las propias opiniones y necesidades de forma clara y respetuosa, sin agredir ni someterse", "Imponer el criterio propio al interlocutor cuando se tiene autoridad para ello, aunque el otro no esté de acuerdo", "Evitar cualquier desacuerdo con el ciudadano cediendo a lo que pide, aunque no sea posible atenderlo"]'::jsonb,1,'Comunicación en la atención al público','Es el punto medio entre la conducta pasiva y la agresiva.',null),
('aux-age:17-dfa7e15c7d','aux-age',17,'La proxémica estudia:','["La forma de redactar los escritos y comunicaciones administrativos dirigidos a los ciudadanos", "El tono, el volumen, el ritmo y las pausas de la voz al hablar con otras personas", "Los gestos, la postura y los movimientos del cuerpo durante la conversación", "El uso del espacio y las distancias entre las personas en la comunicación"]'::jsonb,3,'Comunicación no verbal','Los gestos y movimientos los estudia la kinésica y los aspectos de la voz, el paralenguaje.',null),
('aux-age:17-5160d26835','aux-age',17,'El tono, el volumen, el ritmo y las pausas de la voz forman parte de:','["El paralenguaje", "La proxémica", "La comunicación escrita", "La kinésica"]'::jsonb,0,'Comunicación no verbal','Acompañan a las palabras y pueden reforzar o contradecir el mensaje verbal.',null),
('aux-age:17-313c8effc1','aux-age',17,'La kinésica es la parte de la comunicación no verbal que estudia:','["Los gestos, la postura y los movimientos corporales", "Las características de la voz, como el tono, el timbre y el volumen", "El vocabulario técnico de la Administración", "Las distancias que mantienen los interlocutores durante la conversación"]'::jsonb,0,'Comunicación no verbal','La mirada y la expresión facial también se incluyen en la kinésica.',null),
('aux-age:17-9e0658e99e','aux-age',17,'Ante un ciudadano que se muestra agresivo en la ventanilla, lo más adecuado es:','["Darle la razón en todo lo que plantee para que se tranquilice y se marche cuanto antes", "Mantener la calma, escucharle y no tomarse su actitud como algo personal", "Responderle en el mismo tono para que vea que no se le tiene miedo", "Negarse a atenderle hasta que pida disculpas por escrito"]'::jsonb,1,'Atención al público','Si la situación se vuelve peligrosa, deben seguirse los protocolos de seguridad del centro.',null),
('aux-age:17-3392666fec','aux-age',17,'Al atender una llamada telefónica en una oficina pública, lo correcto es:','["Contestar solo «¿Sí?» para ahorrar tiempo", "Esperar a que el ciudadano se identifique antes de decir nada", "Identificar la unidad y a la persona que atiende, y saludar", "Pasar la llamada a otra extensión sin preguntar el motivo"]'::jsonb,2,'Atención telefónica','Facilita que el ciudadano sepa con quién habla y genera confianza.',null),
('aux-age:17-5a85ffa39d','aux-age',17,'Según el Real Decreto 951/2005, ¿cuál de los siguientes es uno de los programas del marco general para la mejora de la calidad en la AGE?','["El programa de quejas y sugerencias", "El programa de teletrabajo", "El programa de acción social", "El programa de evaluación del desempeño individual"]'::jsonb,0,'Art. 3.1 RD 951/2005','Los programas son: análisis de la demanda y evaluación de la satisfacción, cartas de servicios, quejas y sugerencias, evaluación de la calidad, reconocimiento y Observatorio de la Calidad.',null),
('aux-age:17-0c3d810940','aux-age',17,'Según el Real Decreto 951/2005, ¿en qué plazo debe informarse al ciudadano de las actuaciones realizadas tras una queja o sugerencia?','["Tres meses desde su presentación", "Quince días naturales", "Veinte días hábiles", "Un mes desde su presentación"]'::jsonb,2,'Art. 16.1 RD 951/2005','El plazo se suspende si se requiere al interesado para que aclare su queja, por un máximo de diez días hábiles.',null),
('aux-age:17-fb161ed16d','aux-age',17,'Si el ciudadano no recibe respuesta a su queja en el plazo establecido, según el RD 951/2005 puede dirigirse a:','["El Tribunal de Cuentas", "La Inspección General de Servicios del departamento", "El Defensor del Pueblo, como único cauce", "El juzgado de lo contencioso-administrativo"]'::jsonb,1,'Art. 16.3 RD 951/2005','La Inspección General de Servicios conocerá las causas de la falta de contestación.',null),
('aux-age:17-d34e575fdb','aux-age',17,'Las quejas formuladas conforme al Real Decreto 951/2005:','["No tienen la calificación de recurso administrativo ni interrumpen los plazos de los procedimientos", "Interrumpen los plazos para recurrir", "Tienen la consideración de recurso de alzada ante el superior jerárquico del órgano que dictó el acto del que se quejan", "Suspenden la ejecución del acto del que se quejan"]'::jsonb,0,'Art. 19 RD 951/2005','Tampoco condicionan el ejercicio de las demás acciones o derechos del interesado.',null),
('aux-age:17-a8f5dd1213','aux-age',17,'¿Cómo pueden presentarse las quejas y sugerencias según el RD 951/2005?','["Por escrito dirigido al Subsecretario, con firma reconocida ante notario", "A través del Defensor del Pueblo, que las traslada al órgano afectado", "Mediante comparecencia personal ante la Inspección General de Servicios del departamento", "De forma presencial, por correo postal o por medios electrónicos"]'::jsonb,3,'Art. 15 RD 951/2005','Las presentadas por medios electrónicos deben ir firmadas electrónicamente.',null),
('aux-age:17-9bd1d2add8','aux-age',17,'Las cartas de servicios se aprueban, según el RD 951/2005:','["Por orden del Ministro, sin necesidad de informe previo", "Por real decreto del Consejo de Ministros, a propuesta del Ministro del departamento y previo dictamen preceptivo del Consejo de Estado en pleno", "Por resolución del Subsecretario del departamento, previo informe favorable de la Secretaría General competente en función pública", "Por acuerdo de la Comisión General de Secretarios de Estado y Subsecretarios"]'::jsonb,2,'Art. 11.1 RD 951/2005','La resolución de aprobación se publica en el BOE.',null),
('aux-age:17-f90772f3d2','aux-age',17,'Las cartas de servicios deben actualizarse:','["Cada cinco años", "Periódicamente y, al menos, cada tres años", "Cada año", "Solo cuando cambie la normativa del servicio"]'::jsonb,1,'Art. 10.4 RD 951/2005','También deben revisarse cuando cambien los servicios o los compromisos.',null),
('aux-age:17-409a642761','aux-age',17,'¿Qué recogen las cartas de servicios?','["Los servicios que se ofrecen, los derechos de los usuarios y los compromisos de calidad asumidos", "La relación de puestos de trabajo del organismo", "Las retribuciones de los empleados públicos que prestan servicio en la unidad y su régimen de jornada y horario", "Las sanciones que pueden imponerse a los ciudadanos que incumplan las normas de utilización de los servicios"]'::jsonb,0,'Art. 8 RD 951/2005','Incluyen medidas de subsanación en caso de incumplimiento, que no dan lugar a responsabilidad patrimonial.',null),
('aux-age:17-b336a8d392','aux-age',17,'Las medidas de subsanación previstas en una carta de servicios para el caso de incumplimiento de los compromisos:','["Suponen la anulación de los actos administrativos dictados durante el incumplimiento", "Obligan a abrir un expediente disciplinario al responsable del servicio incumplido", "Dan derecho a una indemnización automática al usuario afectado por el incumplimiento", "No darán lugar a responsabilidad patrimonial de la Administración"]'::jsonb,3,'Art. 9 RD 951/2005','Normalmente consisten en una comunicación del responsable explicando las causas y las medidas adoptadas.',null),
('aux-age:17-8bcd1fc6ea','aux-age',17,'¿Qué órgano analiza periódicamente la percepción ciudadana sobre los servicios públicos según el RD 951/2005?','["El Instituto Nacional de Estadística", "El Observatorio de la Calidad de los Servicios Públicos", "El Centro de Investigaciones Sociológicas", "El Consejo de Transparencia y Buen Gobierno"]'::jsonb,1,'Art. 26 RD 951/2005','Publica un informe anual de evaluación global con conclusiones y recomendaciones.',null),
('aux-age:17-20f02f82e6','aux-age',17,'En la atención a una persona con discapacidad auditiva que lee los labios, conviene:','["Comunicarse solo por escrito, sin mirarla", "Hablarle de frente, vocalizando bien y sin taparse la boca", "Dirigirse a su acompañante en lugar de a ella para evitar malentendidos", "Hablarle en voz muy alta y deprisa para que capte mejor las palabras"]'::jsonb,1,'Atención a personas con discapacidad','La Ley 27/2007 reconoce las lenguas de signos españolas y regula los medios de apoyo a la comunicación oral.',null),
('aux-age:17-db746f3b7e','aux-age',17,'¿Qué ley reconoce las lenguas de signos españolas y regula los medios de apoyo a la comunicación oral de las personas sordas?','["La Ley 51/2003, de 2 de diciembre", "La Ley 27/2007, de 23 de octubre", "La Ley 39/2006, de 14 de diciembre", "La Ley 4/2023, de 28 de febrero"]'::jsonb,1,'Ley 27/2007','Reconoce la lengua de signos española y la lengua de signos catalana.',null),
('aux-age:17-22d4c494c9','aux-age',17,'¿Cuántos programas integran el marco general para la mejora de la calidad del RD 951/2005?','["Cinco", "Ocho", "Seis", "Cuatro"]'::jsonb,2,'Art. 3 RD 951/2005','Son seis: análisis de la demanda y evaluación de la satisfacción, cartas de servicios, quejas y sugerencias, evaluación de la calidad, reconocimiento y Observatorio de la Calidad.',null),
('aux-age:17-b83f63371b','aux-age',17,'Según el RD 951/2005, la unidad que coordina los programas de calidad en cada departamento ministerial la designa:','["El Inspector General de Servicios de la Administración Pública", "El Secretario de Estado de Función Pública", "El Subsecretario del departamento", "El Ministro del departamento"]'::jsonb,2,'Art. 3 RD 951/2005','Cada Subsecretario designa la unidad responsable de coordinar los programas de calidad en su departamento.',null),
('aux-age:17-929cf30dcf','aux-age',17,'Según el RD 951/2005, la satisfacción de los usuarios con los servicios se medirá:','["De forma sistemática y permanente", "Solo cuando se reciban quejas", "Una vez al año, en el primer trimestre", "Cada tres años, al revisar la carta de servicios"]'::jsonb,0,'Art. 5 RD 951/2005','La medición de la percepción de la calidad por los usuarios se hace de forma sistemática y permanente.',null),
('aux-age:17-1fb738e2a1','aux-age',17,'La resolución que aprueba una carta de servicios, según el RD 951/2005, se publica en:','["El tablón de anuncios de la oficina", "Únicamente en la sede electrónica del órgano", "El Boletín Oficial del Estado", "El Diario de Sesiones del Congreso"]'::jsonb,2,'Art. 11 RD 951/2005','La resolución aprobatoria se publica en el BOE y las cartas se difunden también por internet y en las oficinas.',null),
('aux-age:17-17abafe3ed','aux-age',17,'Los órganos con carta de servicios deben enviar, según el RD 951/2005, un informe anual sobre su cumplimiento:','["Cada tres años", "Durante el primer semestre de cada año", "En el mes de diciembre", "Durante el primer trimestre de cada año"]'::jsonb,3,'Art. 12 RD 951/2005','Los órganos remiten anualmente, en el primer trimestre, un informe sobre el grado de cumplimiento de los compromisos.',null),
('aux-age:17-9f043ee95d','aux-age',17,'Si la unidad de quejas pide al ciudadano que aclare su queja, según el RD 951/2005 este dispone para hacerlo de:','["10 días hábiles", "15 días hábiles", "5 días hábiles", "20 días hábiles"]'::jsonb,0,'Art. 16 RD 951/2005','El plazo de 20 días hábiles para contestar se suspende y el ciudadano tiene 10 días hábiles para responder a la aclaración.',null),
('aux-age:17-0c58103c93','aux-age',17,'¿Qué órgano realiza el seguimiento de las quejas y sugerencias en cada departamento, según el RD 951/2005?','["El Defensor del Pueblo", "El Tribunal de Cuentas", "El Consejo de Transparencia y Buen Gobierno de la Administración", "La Inspección General de Servicios del departamento"]'::jsonb,3,'Art. 17 RD 951/2005','Las Inspecciones Generales de Servicios de los departamentos realizan el seguimiento de las quejas y sugerencias.',null),
('aux-age:17-57eec39f19','aux-age',17,'Según el RD 951/2005, para obtener el reconocimiento a la excelencia una organización debe haber realizado previamente:','["Una carta de servicios electrónica", "Una encuesta de satisfacción del Centro de Investigaciones Sociológicas", "Una autoevaluación conforme a un modelo de gestión de calidad reconocido", "Una auditoría del Tribunal de Cuentas"]'::jsonb,2,'Art. 23 RD 951/2005','Para optar al reconocimiento a la excelencia es requisito haber realizado una autoevaluación según los modelos de gestión de calidad reconocidos.',null),
('aux-age:17-1f5ccb630e','aux-age',17,'Según el RD 951/2005, ¿quién designa la unidad encargada de gestionar las quejas y sugerencias?','["La Agencia Española de Protección de Datos", "El Ministerio de Hacienda para todos los departamentos", "Cada órgano o organismo, que debe contestar al ciudadano", "El Defensor del Pueblo para toda la Administración"]'::jsonb,2,'Art. 14 RD 951/2005','Cada órgano designa la unidad responsable de la gestión de quejas y sugerencias, que debe responder al ciudadano.',null),
('aux-age:17-1f306efeff','aux-age',17,'Los órganos que prestan servicios electrónicos operativos deben tener, según el RD 951/2005:','["Un libro de reclamaciones en papel", "Un certificado de calidad ISO", "Cartas de servicios electrónicos", "Un defensor del usuario propio"]'::jsonb,2,'Art. 13 RD 951/2005','Los órganos con servicios electrónicos operativos elaboran cartas de servicios electrónicos.',null),
('aux-age:18-ff55857733','aux-age',18,'¿Qué norma regula los servicios de información administrativa y atención al ciudadano en la Administración General del Estado?','["El Real Decreto 203/2021, de 30 de marzo de 2021", "El Real Decreto 364/1995, de 10 de marzo de 1995", "El Real Decreto 951/2005, de 29 de julio de 2005", "El Real Decreto 208/1996, de 9 de febrero"]'::jsonb,3,'RD 208/1996','El RD 951/2005 regula el marco general para la mejora de la calidad y el RD 203/2021 el Reglamento de actuación y funcionamiento del sector público por medios electrónicos.',null),
('aux-age:18-613c5e807e','aux-age',18,'Según el Real Decreto 208/1996, la información administrativa puede ser:','["Verbal, escrita o telemática", "Ordinaria o extraordinaria", "General o particular", "Pública, reservada o secreta"]'::jsonb,2,'Art. 1 RD 208/1996','Es el cauce a través del cual los ciudadanos conocen sus derechos y obligaciones y la utilización de los bienes y servicios públicos.',null),
('aux-age:18-76f550038f','aux-age',18,'La información general, según el Real Decreto 208/1996, se facilitará:','["A los interesados en un procedimiento administrativo o a sus representantes legales debidamente acreditados", "Previo pago de la tasa correspondiente", "A quien la solicite por escrito y acredite un interés legítimo, personal y directo en el asunto", "Obligatoriamente a los ciudadanos, sin exigir para ello la acreditación de legitimación alguna"]'::jsonb,3,'Art. 2.2 RD 208/1996','Se refiere a la identificación, fines, competencia, estructura y localización de los órganos, y a los requisitos de procedimientos y servicios.',null),
('aux-age:18-70c7526d13','aux-age',18,'La información particular, según el Real Decreto 208/1996, es la relativa a:','["La estructura, las funciones y la localización de los órganos administrativos, así como la identificación de sus titulares y su horario de atención al público", "Los requisitos jurídicos para acceder a una prestación pública", "El estado o el contenido de los procedimientos en tramitación y la identificación de las autoridades y el personal bajo cuya responsabilidad se tramiten", "Las publicaciones oficiales editadas por los Ministerios"]'::jsonb,2,'Art. 3.1 RD 208/1996','Lo demás corresponde a la información general.',null),
('aux-age:18-d56d8ae62b','aux-age',18,'¿A quién puede facilitarse la información particular?','["A las personas que tengan la condición de interesados o a sus representantes legales", "A los abogados colegiados que intervengan en el procedimiento en nombre de un tercero", "A cualquier empleado público de la Administración General del Estado que la pida por escrito", "A cualquier ciudadano que la solicite, aunque no se identifique ni acredite interés alguno"]'::jsonb,0,'Art. 3.2 RD 208/1996','Debe respetarse la normativa de protección de datos personales.',null),
('aux-age:18-86d675dce3','aux-age',18,'Según el Real Decreto 208/1996, la orientación sobre los requisitos de los procedimientos que se presta en las oficinas de información:','["Vincula a la Administración en la resolución posterior del procedimiento al que se refiera", "Puede incluir la interpretación de la norma aplicable al caso concreto que plantee el ciudadano", "Debe darse siempre por escrito y con la firma del jefe de la oficina", "No puede entrañar una interpretación normativa ni una consideración jurídica o económica"]'::jsonb,3,'Art. 4 b) RD 208/1996','Se limita a la determinación de conceptos, la información sobre opciones legales o la colaboración en la cumplimentación de impresos.',null),
('aux-age:18-669b7438fe','aux-age',18,'¿Cuál de las siguientes es una función de atención al ciudadano según el artículo 4 del RD 208/1996?','["La imposición de sanciones por infracciones leves", "La resolución definitiva de los recursos de alzada presentados por los ciudadanos contra actos del propio departamento", "La aprobación de las cartas de servicios del departamento", "La recepción y acogida, para facilitar la orientación y ayuda que precisen en el momento inicial de su visita"]'::jsonb,3,'Art. 4 a) RD 208/1996','Otras funciones son la orientación, la gestión, la recepción de iniciativas y sugerencias y la recepción de quejas.',null),
('aux-age:18-9c8ea61d0e','aux-age',18,'Las oficinas de información y atención al ciudadano de los servicios centrales pueden ser, según el RD 208/1996:','["Oficinas generales, para cualquier asunto, y oficinas especiales, para los procedimientos de cada organismo público adscrito", "Oficinas centrales en la sede de cada Ministerio, que pueden tener oficinas delegadas, y oficinas de organismos públicos", "Oficinas provinciales e insulares", "Oficinas de registro y oficinas de archivo, dependientes en ambos casos de la Secretaría General Técnica del Ministerio correspondiente"]'::jsonb,1,'Art. 8 RD 208/1996','En los órganos territoriales existen oficinas en las Delegaciones y Subdelegaciones del Gobierno.',null),
('aux-age:18-5be4410f4b','aux-age',18,'Según el Real Decreto 208/1996, las oficinas de información de una Administración pueden informar sobre otras Administraciones:','["Cuando lo autorice el Delegado del Gobierno en la Comunidad Autónoma", "Cuando lo autorice el Consejo de Ministros", "Cuando así se prevea en un convenio de colaboración entre ellas", "Cuando el ciudadano lo pida expresamente por escrito"]'::jsonb,2,'Art. 10 RD 208/1996','También pueden crearse oficinas conjuntas de varias Administraciones.',null),
('aux-age:18-ccbcf3db2d','aux-age',18,'¿Qué ley orgánica regula el derecho de petición?','["La LO 9/1983, de 15 de julio", "La LO 3/1981, de 6 de abril de 1981", "La LO 4/2001, de 12 de noviembre", "La LO 1/2002, de 22 de marzo"]'::jsonb,2,'LO 4/2001','La LO 3/1981 regula el Defensor del Pueblo, la LO 9/1983 el derecho de reunión y la LO 1/2002 el derecho de asociación.',null),
('aux-age:18-188e0a413b','aux-age',18,'¿Quién puede ejercer el derecho de petición según la LO 4/2001?','["Las asociaciones y fundaciones inscritas en el registro público correspondiente", "Las personas físicas con residencia legal en España, sean o no nacionales", "Toda persona natural o jurídica, prescindiendo de su nacionalidad", "Los ciudadanos españoles mayores de edad con plena capacidad de obrar"]'::jsonb,2,'Art. 1 LO 4/2001','Los miembros de las Fuerzas Armadas o de los Institutos armados de naturaleza militar solo pueden ejercerlo individualmente.',null),
('aux-age:18-3071168e09','aux-age',18,'Según la LO 4/2001, el escrito de petición debe presentarse:','["Exclusivamente en el registro del órgano destinatario", "Por escrito, por cualquier medio, incluidos los electrónicos, que permita acreditar su autenticidad", "En persona, mediante escrito con la firma de al menos diez solicitantes mayores de edad y su domicilio", "Verbalmente ante el órgano destinatario, que levantará acta de la comparecencia y entregará copia al peticionario"]'::jsonb,1,'Art. 4 LO 4/2001','Debe incluir la identidad del solicitante, la nacionalidad si la tuviera, el lugar o medio de notificación, el objeto y el destinatario.',null),
('aux-age:18-723be88f89','aux-age',18,'¿Qué peticiones NO son admisibles según la LO 4/2001?','["Las presentadas por personas extranjeras no residentes", "Las que se refieran a cualquier asunto de interés general o particular que sea competencia propia del destinatario de la petición", "Aquellas cuya resolución deba ampararse en un título específico distinto al derecho de petición, previsto en el ordenamiento", "Las presentadas de forma colectiva por varias personas"]'::jsonb,2,'Art. 8 LO 4/2001','Tampoco las que se refieran a asuntos sobre los que exista un procedimiento parlamentario, administrativo o judicial en trámite.',null),
('aux-age:18-1e72d75fa8','aux-age',18,'Según la LO 4/2001, el destinatario de la petición debe acusar recibo del escrito dentro de:','["Los diez días siguientes a su recepción", "Los cuarenta y cinco días siguientes a su recepción", "El mes siguiente a su recepción", "Los tres días siguientes a su recepción"]'::jsonb,0,'Art. 6.2 LO 4/2001','Si el escrito no reúne los requisitos, se requiere al peticionario para que lo subsane en quince días.',null),
('aux-age:18-e261345c86','aux-age',18,'Admitida a trámite una petición, la autoridad u órgano competente debe contestar en el plazo máximo de:','["Quince días hábiles desde la admisión", "Tres meses desde la fecha de su presentación", "Un mes desde la fecha de su admisión a trámite", "Seis meses desde la fecha de su presentación en registro"]'::jsonb,1,'Art. 11.1 LO 4/2001','La decisión sobre la admisión debe adoptarse en el plazo de cuarenta y cinco días hábiles.',null),
('aux-age:18-a2dacf8b14','aux-age',18,'¿Qué número de teléfono de información administrativa de la AGE ofrece información general sobre los servicios públicos?','["El 012", "El 016", "El 010", "El 060"]'::jsonb,3,'Teléfono 060','El 010 y el 012 son números de información de ámbito municipal y autonómico, y el 016 atiende a víctimas de violencia de género.',null),
('aux-age:18-eb16acab69','aux-age',18,'¿Cuál es la dirección del Punto de Acceso General electrónico de la Administración General del Estado?','["transparencia.gob.es", "datos.gob.es", "boe.es", "administracion.gob.es"]'::jsonb,3,'Punto de Acceso General','Facilita el acceso a los servicios, trámites e información de las Administraciones Públicas.',null),
('aux-age:18-33563715d7','aux-age',18,'Según el artículo 13 de la Ley 39/2015, es un derecho de las personas en sus relaciones con las Administraciones Públicas:','["Obtener siempre una resolución favorable cuando cumplan los requisitos formales", "Exigir que se les atienda fuera del horario de atención al público", "Elegir al funcionario que tramitará su procedimiento", "Ser tratadas con respeto y deferencia por las autoridades y empleados públicos, que habrán de facilitarles el ejercicio de sus derechos"]'::jsonb,3,'Art. 13 e) Ley 39/2015','El artículo 13 recoge también, entre otros, el derecho a ser asistidas en el uso de medios electrónicos.',null)
